def log_function(request, log_message, status, connection, session=None):
    """
    Create a log entry for general connection activities
    
    Args:
        request: Request object
        log_message: Message to log
        status: Status code (S/E/W)
        connection: Connection ID
        session: Session ID (only for migration-related logs, None for connection activities)
        table: Table name (optional, for table-specific logs)
    """
    Log.objects.create(
        message=log_message,
        cmp=request.user.cmp,
        user=request.user,
        connection_id=connection,
        status=status,
        session=session,
    )
    return "log entered successfully"


def generate_connection_update_message(field_name, old_value, new_value):
    """
    Generate descriptive update messages for connection fields.
    
    Args:
        field_name: Name of the field being updated
        old_value: Previous value of the field
        new_value: New value of the field
    
    Returns:
        Descriptive message string in the format:
        "Updated the field: <Field Name> from <old value> to <new value>"
    """
    # Time frequency mapping (same as used elsewhere in the codebase)
    time_frequencies = {
        'None': 'None',
        '1': '1 minute',
        '5': '5 minutes', 
        '15': '15 minutes',
        '30': '30 minutes',
        '60': '1 hour',
        '120': '2 hours',
        '180': '3 hours',
        '360': '6 hours',
        '480': '8 hours',
        '720': '12 hours',
        '1440': '24 hours'
    }
    
    # Safety interval mapping (same as time_frequencies)
    safety_intervals = time_frequencies
    
    # Execution order mapping
    execution_orders = {
        'parallel': 'Parallel',
        'sequential': 'Sequential'
    }
    
    # Generate descriptive message based on field type
    if field_name == 'chunk_count':
        return f"Updated Transfer packet size from {old_value} to {new_value}"
    
    elif field_name == 'time_frequency':
        old_readable = time_frequencies.get(str(old_value), str(old_value))
        new_readable = time_frequencies.get(str(new_value), str(new_value))
        return f"Updated Sync frequency from {old_readable} to {new_readable}"
    
    elif field_name == 'safety_interval':
        old_readable = safety_intervals.get(str(old_value), str(old_value))
        new_readable = safety_intervals.get(str(new_value), str(new_value))
        return f"Updated Safety interval from {old_readable} to {new_readable}"
    
    elif field_name == 'execution_order':
        old_readable = execution_orders.get(str(old_value), str(old_value))
        new_readable = execution_orders.get(str(new_value), str(new_value))
        return f"Updated Execution order from {old_readable} to {new_readable}"
    
    elif field_name == 'sync_start_date':
        # Handle sync_start_date formatting
        from django.utils import timezone
        
        if old_value:
            if hasattr(old_value, 'strftime'):
                old_formatted = old_value.strftime('%Y-%m-%d %H:%M:%S UTC')
            else:
                old_formatted = str(old_value)
        else:
            old_formatted = 'Not set'
            
        if new_value:
            if hasattr(new_value, 'strftime'):
                new_formatted = new_value.strftime('%Y-%m-%d %H:%M:%S UTC')
            else:
                new_formatted = str(new_value)
        else:
            new_formatted = 'Not set'
            
        return f"Updated Sync start date from {old_formatted} to {new_formatted}"
    
    else:
        # Fallback for any other fields
        return f"Updated {field_name.replace('_', ' ').title()} from {old_value} to {new_value}"
 

