def should_verify_s3_api_ssl() -> bool:
    """
    Toggle TLS certificate verification for AmazonS3 backend calls only.
    Default is False to preserve existing behavior unless explicitly enabled.
    """
    value = str(os.getenv("S3_API_VERIFY_SSL", "false")).strip().lower()
    return value in {"1", "true", "yes", "on"}


_NOTIFICATION_EMAIL_GROUP_IDS_FIELD = "notification_email_group_ids"
_SUPPORTED_FILE_EXPORT_FORMATS = {"csv", "json", "parquet", "excel"}
_SUPPORTED_FILENAME_DATE_FORMATS = {"yyyy_mm_dd", "dd_mm_yyyy", "mm_dd_yyyy"}
# Keep these canonical lowercase tokens in sync with the migration function so
# frontend payloads can use one stable set of Excel conditional rule types.
_SUPPORTED_EXCEL_CONDITIONAL_RULE_TYPES = {
    "aboveaverage",
    "beginswith",
    "cellis",
    "containstext",
    "colorscale",
    "databar",
    "duplicaterecords",
    "endswith",
    "expression",
    "formula",
    "iconset",
    "notcontainstext",
    "timeperiod",
    "top10",
    "uniquerecords",
    "multipleconditions",
}
# Multiple-condition rules are compiled from semantic ``conditions`` by the
# Excel writer.  ``formula`` remains optional for them for legacy/frontend
# preview compatibility; the other formula-based rules still require it.
_EXCEL_RULE_TYPES_REQUIRING_FORMULA = {"cellis", "expression", "formula"}
_EXCEL_TEXT_BASED_RULE_TYPES = {"beginswith", "containstext", "endswith", "notcontainstext"}
_EXCEL_COLOR_SCALE_RULE_TYPES = {"colorscale"}
_EXCEL_DATA_BAR_RULE_TYPES = {"databar"}
_EXCEL_ICON_SET_RULE_TYPES = {"iconset"}
_EXCEL_RANK_RULE_TYPES = {"top10"}
_EXCEL_TIME_PERIOD_RULE_TYPES = {"timeperiod"}
_EXCEL_MULTIPLE_CONDITION_OPERATORS = {
    "equal",
    "notEqual",
    "greaterThan",
    "lessThan",
    "greaterThanOrEqual",
    "lessThanOrEqual",
    "contains",
    "notContains",
    "beginsWith",
    "notBeginsWith",
    "endsWith",
    "notEndsWith",
    "between",
    "notBetween",
    "isEmpty",
    "isNotEmpty",
}
_EXCEL_RANGE_RE = re.compile(r"^[A-Za-z]{1,3}\d{1,7}(?::[A-Za-z]{1,3}\d{1,7})?$")
_EXCEL_COLUMN_NAME_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_ ]*$")

def _normalize_sort_columns(raw_value):
    if raw_value in (None, ""):
        return []
    if not isinstance(raw_value, list):
        raise ValueError("sort_columns must be a list")
    normalized = []
    for index, item in enumerate(raw_value):
        if isinstance(item, str):
            column_name, direction = item, "asc"
        elif isinstance(item, dict):
            column_name = item.get("column_name") or item.get("column") or item.get("field")
            direction = item.get("direction") or item.get("order") or "asc"
        else:
            raise ValueError(f"sort_columns[{index}] must be a string or object")
        column_name = str(column_name or "").strip()
        direction = str(direction or "asc").strip().lower()
        if not column_name or not _EXCEL_COLUMN_NAME_RE.match(column_name):
            raise ValueError(f"sort_columns[{index}].column_name is invalid")
        if direction not in {"asc", "desc"}:
            raise ValueError(f"sort_columns[{index}].direction must be asc or desc")
        normalized.append({"column_name": column_name, "direction": direction})
    return normalized

def _normalize_notification_email_group_ids(raw_value):
    if raw_value in (None, ""):
        return []
    if not isinstance(raw_value, list):
        raise ValueError("notification_email_group_ids must be a list of integers")

    normalized_ids = []
    seen_ids = set()
    for item in raw_value:
        if isinstance(item, bool):
            raise ValueError("notification_email_group_ids must contain only integers")
        try:
            group_id = int(item)
        except (TypeError, ValueError) as exc:
            raise ValueError("notification_email_group_ids must contain only integers") from exc
        if group_id <= 0:
            raise ValueError("notification_email_group_ids must contain only positive integers")
        if group_id in seen_ids:
            continue
        seen_ids.add(group_id)
        normalized_ids.append(group_id)
    return normalized_ids


def _normalize_filename_date_format(raw_value):
    if raw_value in (None, ""):
        return None
    normalized = str(raw_value).strip().lower()
    if normalized not in _SUPPORTED_FILENAME_DATE_FORMATS:
        raise ValueError(
            "filename_date_format must be one of: "
            + ", ".join(sorted(_SUPPORTED_FILENAME_DATE_FORMATS))
        )
    return normalized


def _normalize_excel_sheet_name(raw_value):
    if raw_value in (None, ""):
        return None
    sheet_name = str(raw_value).strip()
    if not sheet_name:
        return None
    if len(sheet_name) > 31:
        raise ValueError("excel_sheet_name must be 31 characters or fewer")
    if any(ch in sheet_name for ch in ('\\', '/', '*', '?', ':', '[', ']')):
        raise ValueError("excel_sheet_name contains invalid Excel sheet characters")
    return sheet_name


def _normalize_excel_options(raw_value):
    if raw_value in (None, ""):
        return None
    if not isinstance(raw_value, dict):
        raise ValueError("excel_options must be an object/dict")
    return copy.deepcopy(raw_value)


def _normalize_excel_conditional_formats(raw_value):
    if raw_value in (None, ""):
        return []
    if not isinstance(raw_value, list):
        raise ValueError("excel_conditional_formats must be a list")

    normalized_rules = []
    for index, raw_rule in enumerate(raw_value):
        if not isinstance(raw_rule, dict):
            raise ValueError(f"excel_conditional_formats[{index}] must be an object/dict")

        # Keep multiple target columns together as one user-facing rule. The
        # Excel writer expands the targets only while creating worksheet
        # ranges, so the saved/API representation remains one rule.
        target_columns = raw_rule.get("target_columns")
        if target_columns not in (None, ""):
            if not isinstance(target_columns, list) or not target_columns:
                raise ValueError(f"excel_conditional_formats[{index}].target_columns must be a non-empty list")
            normalized_targets = []
            for target_index, target_column in enumerate(target_columns):
                target_column = str(target_column or "").strip()
                if not target_column or not _EXCEL_COLUMN_NAME_RE.match(target_column):
                    raise ValueError(
                        f"excel_conditional_formats[{index}].target_columns[{target_index}] is invalid"
                    )
                normalized_targets.append(target_column)

        rule = copy.deepcopy(raw_rule)
        rule_type = str(rule.get("type") or "").strip().lower()
        if not rule_type:
            raise ValueError(f"excel_conditional_formats[{index}].type is required")
        if rule_type not in _SUPPORTED_EXCEL_CONDITIONAL_RULE_TYPES:
            raise ValueError(
                f"excel_conditional_formats[{index}].type must be one of: {', '.join(sorted(_SUPPORTED_EXCEL_CONDITIONAL_RULE_TYPES))}"
            )

        target_range = str(rule.get("range") or "").strip()
        column_name = str(rule.get("column_name") or "").strip()
        if target_columns not in (None, ""):
            rule["target_columns"] = normalized_targets
            # column_name is retained for compatibility with older consumers;
            # the writer uses target_columns when present.
            column_name = normalized_targets[0]
            rule["column_name"] = column_name
        if not target_range and not column_name:
            raise ValueError(f"excel_conditional_formats[{index}] requires either range or column_name")
        if target_range and not _EXCEL_RANGE_RE.match(target_range):
            raise ValueError(f"excel_conditional_formats[{index}].range must be a valid Excel range like A2:A100")
        if column_name and not _EXCEL_COLUMN_NAME_RE.match(column_name):
            raise ValueError(f"excel_conditional_formats[{index}].column_name is invalid")
        condition_column_name = str(rule.get("condition_column_name") or "").strip()
        if condition_column_name and not _EXCEL_COLUMN_NAME_RE.match(condition_column_name):
            raise ValueError(f"excel_conditional_formats[{index}].condition_column_name is invalid")
        highlight_scope = str(rule.get("highlight_scope") or "cell").strip().lower()
        if highlight_scope not in {"cell", "entire_column", "entire_row", "selected_columns"}:
            raise ValueError(f"excel_conditional_formats[{index}].highlight_scope must be cell, entire_column, entire_row, or selected_columns")
        rule["highlight_scope"] = highlight_scope

        if rule_type == "multipleconditions":
            conditions = rule.get("conditions")
            if not isinstance(conditions, list) or not conditions:
                raise ValueError(f"excel_conditional_formats[{index}].conditions must be a non-empty list")
            normalized_conditions = []
            for condition_index, condition in enumerate(conditions):
                if not isinstance(condition, dict):
                    raise ValueError(
                        f"excel_conditional_formats[{index}].conditions[{condition_index}] must be an object/dict"
                    )
                condition_column = str(condition.get("column") or "").strip()
                if not condition_column or not _EXCEL_COLUMN_NAME_RE.match(condition_column):
                    raise ValueError(
                        f"excel_conditional_formats[{index}].conditions[{condition_index}].column is invalid"
                    )
                operator = str(condition.get("operator") or "equal").strip()
                logic = str(condition.get("logic") or "and").strip().lower()
                if operator not in _EXCEL_MULTIPLE_CONDITION_OPERATORS:
                    raise ValueError(
                        f"excel_conditional_formats[{index}].conditions[{condition_index}].operator is invalid"
                    )
                if condition_index > 0 and logic not in {"and", "or"}:
                    raise ValueError(
                        f"excel_conditional_formats[{index}].conditions[{condition_index}].logic is invalid"
                    )
                if operator in {"between", "notBetween"} and condition.get("value2") in (None, ""):
                    raise ValueError(
                        f"excel_conditional_formats[{index}].conditions[{condition_index}].value2 is required for {operator}"
                    )
                open_paren = str(condition.get("open_paren") or "").strip()
                close_paren = str(condition.get("close_paren") or "").strip()
                if any(character != "(" for character in open_paren):
                    raise ValueError(
                        f"excel_conditional_formats[{index}].conditions[{condition_index}].open_paren is invalid"
                    )
                if any(character != ")" for character in close_paren):
                    raise ValueError(
                        f"excel_conditional_formats[{index}].conditions[{condition_index}].close_paren is invalid"
                    )
                normalized_condition = {
                    "column": condition_column,
                    "operator": operator,
                    "value": condition.get("value", ""),
                }
                if condition_index > 0:
                    normalized_condition["logic"] = logic
                if "value2" in condition:
                    normalized_condition["value2"] = condition.get("value2")
                if open_paren:
                    normalized_condition["open_paren"] = open_paren
                if close_paren:
                    normalized_condition["close_paren"] = close_paren
                normalized_conditions.append(normalized_condition)
            parenthesis_depth = 0
            for condition in normalized_conditions:
                parenthesis_depth += len(condition.get("open_paren") or "")
                parenthesis_depth -= len(condition.get("close_paren") or "")
                if parenthesis_depth < 0:
                    raise ValueError(
                        f"excel_conditional_formats[{index}].conditions parentheses are unbalanced"
                    )
            if parenthesis_depth:
                raise ValueError(
                    f"excel_conditional_formats[{index}].conditions parentheses are unbalanced"
                )
            rule["conditions"] = normalized_conditions

        formula_value = rule.get("formula")
        if formula_value not in (None, ""):
            if isinstance(formula_value, str):
                normalized_formula = [formula_value] if str(formula_value).strip() else []
            elif isinstance(formula_value, list):
                normalized_formula = [str(item) for item in formula_value if str(item).strip()]
                if len(normalized_formula) != len(formula_value) and rule_type in _EXCEL_RULE_TYPES_REQUIRING_FORMULA:
                    raise ValueError(f"excel_conditional_formats[{index}].formula entries must be non-empty")
            else:
                raise ValueError(f"excel_conditional_formats[{index}].formula must be a string or list")

            if normalized_formula:
                rule["formula"] = normalized_formula
            elif rule_type in _EXCEL_RULE_TYPES_REQUIRING_FORMULA:
                raise ValueError(f"excel_conditional_formats[{index}].formula entries must be non-empty")
            else:
                rule.pop("formula", None)
        elif rule_type in _EXCEL_TEXT_BASED_RULE_TYPES:
            rule.pop("formula", None)

        if "style" in rule and rule["style"] not in (None, "") and not isinstance(rule["style"], dict):
            raise ValueError(f"excel_conditional_formats[{index}].style must be an object/dict")

        if rule_type in _EXCEL_TEXT_BASED_RULE_TYPES:
            text_value = rule.get("text")
            if text_value in (None, "") or not str(text_value).strip():
                raise ValueError(f"excel_conditional_formats[{index}].text is required for {rule_type}")

        if rule_type in _EXCEL_COLOR_SCALE_RULE_TYPES:
            colors_value = rule.get("colors")
            if not isinstance(colors_value, list) or len(colors_value) not in (2, 3):
                raise ValueError(f"excel_conditional_formats[{index}].colors must be a list of 2 or 3 color values for colorscale")
            normalized_colors = []
            for color_index, color in enumerate(colors_value):
                normalized_color = str(color or "").strip()
                if not normalized_color:
                    raise ValueError(f"excel_conditional_formats[{index}].colors[{color_index}] must be non-empty")
                normalized_colors.append(normalized_color)
            rule["colors"] = normalized_colors

        if rule_type in _EXCEL_DATA_BAR_RULE_TYPES and rule.get("color") not in (None, ""):
            rule["color"] = str(rule.get("color")).strip()

        if rule_type in _EXCEL_ICON_SET_RULE_TYPES:
            icon_style = str(rule.get("icon_style") or "").strip()
            if not icon_style:
                raise ValueError(f"excel_conditional_formats[{index}].icon_style is required for iconset")
            values = rule.get("values")
            if values not in (None, ""):
                if not isinstance(values, list) or not values:
                    raise ValueError(f"excel_conditional_formats[{index}].values must be a non-empty list for iconset")

        if rule_type in _EXCEL_RANK_RULE_TYPES and rule.get("rank") not in (None, ""):
            try:
                rank_value = int(rule.get("rank"))
            except (TypeError, ValueError) as exc:
                raise ValueError(f"excel_conditional_formats[{index}].rank must be an integer") from exc
            if rank_value <= 0:
                raise ValueError(f"excel_conditional_formats[{index}].rank must be greater than 0")
            rule["rank"] = rank_value

        if rule_type in _EXCEL_TIME_PERIOD_RULE_TYPES:
            time_period = str(rule.get("time_period") or rule.get("period") or "").strip()
            if not time_period:
                raise ValueError(f"excel_conditional_formats[{index}].time_period is required for timeperiod")
            rule["time_period"] = time_period

        logger.debug(
            "Normalized excel conditional format rule | index=%s type=%s column_name=%s range=%s formula=%s style=%s",
            index,
            rule_type,
            rule.get("column_name"),
            rule.get("range"),
            rule.get("formula"),
            rule.get("style"),
        )
        normalized_rules.append(rule)

    # Coalesce legacy data where one logical rule was previously stored once
    # per target column. This also makes old saved settings appear as one rule
    # after the user reopens them.
    coalesced_rules = []
    for rule in normalized_rules:
        comparable = {k: v for k, v in rule.items() if k not in {"column_name", "target_columns"}}
        match = next(
            (
                existing
                for existing in coalesced_rules
                if {k: v for k, v in existing.items() if k not in {"column_name", "target_columns"}} == comparable
            ),
            None,
        )
        if match and not rule.get("range") and not match.get("range"):
            existing_targets = match.setdefault("target_columns", [match.get("column_name")])
            target = rule.get("column_name")
            if target and target not in existing_targets:
                existing_targets.append(target)
            match["column_name"] = existing_targets[0]
        else:
            coalesced_rules.append(rule)
    return coalesced_rules



def _get_company_email_groups(company):
    communication_support_obj = CommunicationSupport.objects.filter(company=company).first()
    groups = []
    if communication_support_obj and isinstance(communication_support_obj.email_groups, list):
        groups = communication_support_obj.email_groups
    return groups


def _validate_company_email_group_ids(company, group_ids):
    normalized_group_ids = _normalize_notification_email_group_ids(group_ids)
    available_groups = _get_company_email_groups(company)
    available_group_ids = {
        int(group.get("id")) for group in available_groups
        if str(group.get("id") or "").strip().isdigit()
    }
    invalid_group_ids = [group_id for group_id in normalized_group_ids if group_id not in available_group_ids]
    if invalid_group_ids:
        raise ValueError(
            f"Unknown email group id(s): {', '.join(str(group_id) for group_id in invalid_group_ids)}"
        )
    return normalized_group_ids


def _normalize_email_custom_fields(raw_value):
    if raw_value in (None, ""):
        return None
    if not isinstance(raw_value, dict):
        raise ValueError("email_custom_fields must be an object/dict")

    normalized = copy.deepcopy(raw_value)
    body_fields = normalized.get("body_fields")
    if body_fields is not None and not isinstance(body_fields, list):
        raise ValueError("email_custom_fields.body_fields must be a list")

    styles = normalized.get("styles")
    if styles is not None and not isinstance(styles, dict):
        raise ValueError("email_custom_fields.styles must be an object/dict")

    return normalized


def _merge_email_custom_fields(existing_value, new_value):
    if new_value in (None, ""):
        return copy.deepcopy(existing_value) if isinstance(existing_value, dict) else existing_value

    normalized_new_value = _normalize_email_custom_fields(new_value)
    if normalized_new_value is None:
        return copy.deepcopy(existing_value) if isinstance(existing_value, dict) else existing_value

    merged_value = copy.deepcopy(existing_value) if isinstance(existing_value, dict) else {}
    for key, value in normalized_new_value.items():
        if key == "styles" and isinstance(value, dict):
            existing_styles = merged_value.get("styles") if isinstance(merged_value.get("styles"), dict) else {}
            merged_styles = copy.deepcopy(existing_styles)
            merged_styles.update(value)
            merged_value["styles"] = merged_styles
        else:
            merged_value[key] = value
    return merged_value


def _build_company_email_group_payload(company, group_ids):
    normalized_group_ids = _normalize_notification_email_group_ids(group_ids)
    groups_by_id = {}
    for group in _get_company_email_groups(company):
        try:
            group_id = int(group.get("id"))
        except (TypeError, ValueError):
            continue
        groups_by_id[group_id] = group

    selected_group_names = []
    selected_emails = []
    seen_emails = set()
    for group_id in normalized_group_ids:
        group = groups_by_id.get(group_id)
        if not group:
            continue
        group_name = str(group.get("name") or "").strip()
        if group_name:
            selected_group_names.append(group_name)
        for email in group.get("email_addresses", []) or []:
            normalized_email = str(email or "").strip()
            lowered_email = normalized_email.lower()
            if not normalized_email or lowered_email in seen_emails:
                continue
            seen_emails.add(lowered_email)
            selected_emails.append(normalized_email)

    return {
        _NOTIFICATION_EMAIL_GROUP_IDS_FIELD: normalized_group_ids,
        "notification_email_group_names": selected_group_names,
        "notification_emails": selected_emails,
    }


def _normalize_file_export_settings(settings_obj):
    if settings_obj is None:
        return None
    if not isinstance(settings_obj, dict):
        raise ValueError("file export settings must be an object/dict")

    normalized = {
        "output_file_name": (settings_obj.get("output_file_name") or "").strip() or None,
        "target_folder": (settings_obj.get("target_folder") or "").strip() or None,
        "file_format": (settings_obj.get("file_format") or "").strip().lower() or None,
        "csv_delimiter": (settings_obj.get("csv_delimiter") or "").strip() or None,
        "csv_quote_char": (settings_obj.get("csv_quote_char") or "").strip() or None,
        "excel_sheet_name": _normalize_excel_sheet_name(settings_obj.get("excel_sheet_name")),
        "excel_options": _normalize_excel_options(settings_obj.get("excel_options")),
        "excel_conditional_formats": _normalize_excel_conditional_formats(settings_obj.get("excel_conditional_formats")),
        "add_utc_timestamp": bool(settings_obj.get("add_utc_timestamp", True)),
        "filename_date_format": _normalize_filename_date_format(settings_obj.get("filename_date_format")),
        _NOTIFICATION_EMAIL_GROUP_IDS_FIELD: _normalize_notification_email_group_ids(
            settings_obj.get(_NOTIFICATION_EMAIL_GROUP_IDS_FIELD, [])
        ),
        "email_custom_fields": _normalize_email_custom_fields(settings_obj.get("email_custom_fields")),
    }
    file_format = normalized.get("file_format")
    if file_format and file_format not in _SUPPORTED_FILE_EXPORT_FORMATS:
        raise ValueError(
            f"file_format must be one of: {', '.join(sorted(_SUPPORTED_FILE_EXPORT_FORMATS))}"
        )
    if file_format != "excel":
        normalized["excel_sheet_name"] = None
        normalized["excel_options"] = None
        normalized["excel_conditional_formats"] = []
    if file_format == "excel":
        normalized["csv_delimiter"] = None
        normalized["csv_quote_char"] = None
        logger.debug(
            "Normalized Excel file export settings | output_file_name=%s target_folder=%s excel_sheet_name=%s excel_options=%s conditional_rule_count=%s",
            normalized.get("output_file_name"),
            normalized.get("target_folder"),
            normalized.get("excel_sheet_name"),
            normalized.get("excel_options"),
            len(normalized.get("excel_conditional_formats") or []),
        )
    return normalized


def _get_effective_file_export_settings(source):
    if source is None:
        return None
    if isinstance(source, dict):
        normalized = _normalize_file_export_settings(source)
    else:
        normalized = {
            "output_file_name": getattr(source, "output_file_name", None),
            "target_folder": getattr(source, "target_folder", None),
            "file_format": getattr(source, "file_format", None),
            "csv_delimiter": getattr(source, "csv_delimiter", None),
            "csv_quote_char": getattr(source, "csv_quote_char", None),
            "excel_sheet_name": getattr(source, "excel_sheet_name", None),
            "excel_options": getattr(source, "excel_options", None),
            "excel_conditional_formats": getattr(source, "excel_conditional_formats", []) or [],
            "sort_columns": (getattr(source, "excel_options", None) or {}).get("sort_columns", []),
            "add_utc_timestamp": bool(getattr(source, "add_utc_timestamp", True)),
            "filename_date_format": _normalize_filename_date_format(
                getattr(source, "filename_date_format", None)
            ),
            _NOTIFICATION_EMAIL_GROUP_IDS_FIELD: list(
                getattr(source, _NOTIFICATION_EMAIL_GROUP_IDS_FIELD, []) or []
            ),
            "email_custom_fields": copy.deepcopy(getattr(source, "email_custom_fields", None)),
        }
    has_non_default_value = any(
        normalized[key] not in (None, []) for key in normalized if key != "add_utc_timestamp"
    )
    if not has_non_default_value and normalized["add_utc_timestamp"] is True:
        return None
    return normalized


def _apply_file_export_settings_to_table_record(table_record, settings_obj, *, include_notification_groups=True):
    normalized = _normalize_file_export_settings(settings_obj)
    table_record.output_file_name = normalized.get("output_file_name") if normalized else None
    table_record.target_folder = normalized.get("target_folder") if normalized else None
    table_record.file_format = normalized.get("file_format") if normalized else None
    table_record.csv_delimiter = normalized.get("csv_delimiter") if normalized else None
    table_record.csv_quote_char = normalized.get("csv_quote_char") if normalized else None
    table_record.excel_sheet_name = normalized.get("excel_sheet_name") if normalized else None
    table_record.excel_options = normalized.get("excel_options") if normalized else None
    table_record.excel_conditional_formats = normalized.get("excel_conditional_formats", []) if normalized else []
    table_record.add_utc_timestamp = normalized.get("add_utc_timestamp", True) if normalized else True
    table_record.filename_date_format = normalized.get("filename_date_format") if normalized else None
    table_record.email_custom_fields = normalized.get("email_custom_fields") if normalized else None
    if include_notification_groups:
        table_record.notification_email_group_ids = (
            normalized.get(_NOTIFICATION_EMAIL_GROUP_IDS_FIELD, []) if normalized else []
        )


def _normalize_destination_key(destination_name):
    return re.sub(r"[^a-z0-9]+", "", str(destination_name or "").strip().lower())


def _normalize_destination_key(destination_name):
    return re.sub(r"[^a-z0-9]+", "", str(destination_name or "").strip().lower())


def _ordinal_position_sort_key(field_meta, default=999999):
    """Sort key for column metadata; null ordinal_position must not break sorting."""
    if not isinstance(field_meta, dict):
        return default
    pos = field_meta.get("ordinal_position")
    if pos is None:
        return default
    try:
        return int(pos)
    except (TypeError, ValueError):
        return default


def _get_destination_model_capability(destination_name, field_name):
    normalized = str(destination_name or "").strip()
    if not normalized:
        return False

    try:
        value = (
            DestinationModel.objects.filter(name__iexact=normalized)
            .values_list(field_name, flat=True)
            .first()
        )
        return bool(value)
    except Exception:
        fallback = _normalize_destination_key(destination_name)
        fallback_map = {
            "is_file_based": {"sftp", "sharepoint", "googledrive", "amazons3", "azuredatalakestorage", "adls"},
            "supports_notification_groups": {"sharepoint", "googledrive"},
        }
        return fallback in fallback_map.get(field_name, set())


def _is_file_based_destination(destination_name):
    return _get_destination_model_capability(destination_name, "is_file_based")


def _is_sharepoint_destination(destination_name):
    return _normalize_destination_key(destination_name) == "sharepoint"


def _is_sftp_destination(destination_name):
    return _normalize_destination_key(destination_name) == "sftp"


def _is_google_drive_destination(destination_name):
    return _normalize_destination_key(destination_name) == "googledrive"


def _is_adls_destination(destination_name):
    return _normalize_destination_key(destination_name) in {"azuredatalakestorage", "adls"}


def _is_s3_destination(destination_name):
    return _normalize_destination_key(destination_name) in {"amazons3", "s3"}


def _build_destination_authorization_payload(destination_name, config_data):
    if _is_adls_destination(destination_name):
        return {"destination_config": config_data}
    return {destination_name: config_data}


def _supports_notification_groups(destination_name):
    if _is_adls_destination(destination_name):
        return True
    return _get_destination_model_capability(destination_name, "supports_notification_groups")


def _supports_notification_email_groups(destination_name):
    return _supports_notification_groups(destination_name)


def _get_destination_field_read_only(destination_name, attribute, has_data_transfers):
    if has_data_transfers and (
        _is_s3_destination(destination_name)
        or _is_adls_destination(destination_name)
        or _is_google_drive_destination(destination_name)
        or _is_sftp_destination(destination_name)
        or _is_sharepoint_destination(destination_name)
    ):
        return True

    from .utils import get_field_read_only
    return get_field_read_only(attribute, has_data_transfers)


def _apply_destination_attribute_field_rules(field_dict, attr):
    """
    Attach dropdown choices and conditional visibility from DestinationAttribute.

    ``visibility_any_of`` is stored in ``choices`` JSON as
    ``{"_visibility_any_of": [{"depend_on": ..., "dependency": ...}, ...]}``.
    """
    choices = attr.choices
    if isinstance(choices, dict) and (
        choices.get("_visibility_any_of") or choices.get("_visibility_all_of")
    ):
        if choices.get("_visibility_any_of"):
            field_dict["visibility_any_of"] = choices["_visibility_any_of"]
        if choices.get("_visibility_all_of"):
            field_dict["visibility_all_of"] = choices["_visibility_all_of"]
        if choices.get("_field_choices"):
            field_dict["choices"] = choices["_field_choices"]
    elif isinstance(choices, list):
        field_dict["choices"] = choices
    elif isinstance(choices, str):
        field_dict["choices"] = [c.strip() for c in choices.split(",")]

    if attr.depend_on:
        field_dict["depend_on"] = attr.depend_on
        field_dict["dependency"] = attr.dependency
        field_dict["dependency_value"] = attr.dependency


def _should_hide_destination_field_on_edit(destination_name, attribute_name, is_edit=False):
    return (
        is_edit
        and _is_google_drive_destination(destination_name)
        and attribute_name == "create_folder_if_missing"
    )


def _build_selected_table_folder_map(queryset, destination_name=None):
    """
    Build the per-table folder mapping used by reverse-ETL/file-based flows.
    File-based destinations store the user's UI folder under `target_folder`,
    while older paths may still populate `folder_path`.
    """
    folder_map = {}
    use_target_folder = _is_file_based_destination(destination_name)

    for source in queryset or []:
        table_name = str(getattr(source, "table", "") or "").strip()
        if not table_name:
            continue

        if use_target_folder:
            folder_value = getattr(source, "target_folder", None)
            if not str(folder_value or "").strip():
                folder_value = getattr(source, "folder_path", None)
        else:
            folder_value = getattr(source, "folder_path", None)

        folder_map[table_name] = str(folder_value or "").strip()

    return folder_map


_SHAREPOINT_CERT_ALLOWED_EXTENSIONS = {".pfx", ".p12", ".pem"}
_SHAREPOINT_CERT_MAX_UPLOAD_BYTES = 5 * 1024 * 1024
_SHAREPOINT_CERT_PASSWORD_MASK = "********"
_SHAREPOINT_SENSITIVE_CONFIG_KEYS = {
    "client_certificate_content",
    "certificate_password",
}


def _parse_destination_request_config_data(raw_config_data):
    if isinstance(raw_config_data, dict):
        return dict(raw_config_data)
    if isinstance(raw_config_data, str):
        try:
            parsed = json.loads(raw_config_data)
        except json.JSONDecodeError as exc:
            raise ValueError("config_data must be valid JSON") from exc
        if not isinstance(parsed, dict):
            raise ValueError("config_data must be a dictionary")
        return parsed
    raise ValueError("config_data must be a dictionary")


def _normalize_nested_destination_config_payload(config_data):
    if not isinstance(config_data, dict):
        return config_data

    nested_config = config_data.get("config_data")
    if not isinstance(nested_config, dict):
        return config_data

    return dict(nested_config)


def _sanitize_destination_config_for_response(config_data, destination_name=None):
    if not isinstance(config_data, dict):
        return config_data

    sanitized = dict(config_data)
    if _is_sharepoint_destination(destination_name):
        certificate_filename = sanitized.get("certificate_filename")
        certificate_password_present = sanitized.get("certificate_password") not in ("", None)
        for key in _SHAREPOINT_SENSITIVE_CONFIG_KEYS:
            sanitized.pop(key, None)
        sanitized["client_certificate_file"] = certificate_filename
        sanitized["client_certificate_uploaded"] = bool(certificate_filename)
        sanitized["certificate_password_set"] = bool(certificate_password_present)
        sanitized["certificate_password"] = (
            _SHAREPOINT_CERT_PASSWORD_MASK if certificate_password_present else None
        )
        sanitized.pop("client_certificate", None)
    return sanitized


def _redact_destination_config_for_log(config_data):
    if isinstance(config_data, dict):
        redacted = {}
        for key, value in config_data.items():
            key_str = str(key).lower()
            if key_str in {
                "password",
                "passphrase",
                "private_key",
                "token",
                "access_token",
                "refresh_token",
                "client_secret",
                "client_certificate_content",
                "certificate_password",
            }:
                redacted[key] = "***REDACTED***"
            elif isinstance(value, dict):
                redacted[key] = _redact_destination_config_for_log(value)
            elif isinstance(value, list):
                redacted[key] = [
                    _redact_destination_config_for_log(item) if isinstance(item, dict) else item
                    for item in value
                ]
            else:
                redacted[key] = value
        return redacted
    return config_data


def _read_uploaded_sharepoint_file(uploaded_file, *, allowed_extensions, field_label):
    filename = str(getattr(uploaded_file, "name", "") or "").strip()
    if not filename:
        raise ValueError(f"{field_label} is missing a filename.")

    _, extension = os.path.splitext(filename.lower())
    if extension not in allowed_extensions:
        allowed_list = ", ".join(sorted(allowed_extensions))
        raise ValueError(f"{field_label} must be one of: {allowed_list}")

    file_size = getattr(uploaded_file, "size", None)
    if file_size is not None and int(file_size) > _SHAREPOINT_CERT_MAX_UPLOAD_BYTES:
        raise ValueError(
            f"{field_label} exceeds the maximum allowed size of {_SHAREPOINT_CERT_MAX_UPLOAD_BYTES // (1024 * 1024)} MB"
        )

    file_bytes = uploaded_file.read()
    if not file_bytes:
        raise ValueError(f"{field_label} is empty.")
    if len(file_bytes) > _SHAREPOINT_CERT_MAX_UPLOAD_BYTES:
        raise ValueError(
            f"{field_label} exceeds the maximum allowed size of {_SHAREPOINT_CERT_MAX_UPLOAD_BYTES // (1024 * 1024)} MB"
        )
    try:
        uploaded_file.seek(0)
    except Exception:
        pass

    return {
        "filename": filename,
        "format": extension.lstrip("."),
        "content": base64.b64encode(file_bytes).decode("ascii"),
    }


def _merge_sharepoint_uploaded_certificate_fields(
    request,
    config_data,
    *,
    destination_name=None,
    existing_config_data=None,
):
    if not isinstance(config_data, dict):
        return config_data

    merged = dict(config_data)
    if not _is_sharepoint_destination(destination_name):
        return merged

    existing = existing_config_data if isinstance(existing_config_data, dict) else {}
    auth_type = str(merged.get("auth_type") or existing.get("auth_type") or "").strip().lower()

    merged.pop("client_certificate_file", None)

    if auth_type != "client_certificate":
        for key in (
            "client_certificate_content",
            "certificate_filename",
            "certificate_format",
            "certificate_password",
        ):
            merged.pop(key, None)
        return merged

    uploaded_cert = request.FILES.get("client_certificate_file") or request.FILES.get("client_certificate")

    if uploaded_cert is not None:
        cert_info = _read_uploaded_sharepoint_file(
            uploaded_cert,
            allowed_extensions=_SHAREPOINT_CERT_ALLOWED_EXTENSIONS,
            field_label="Client certificate file",
        )
        merged["client_certificate_content"] = cert_info["content"]
        merged["certificate_filename"] = cert_info["filename"]
        merged["certificate_format"] = cert_info["format"]
    else:
        for key in ("client_certificate_content", "certificate_filename", "certificate_format"):
            if key not in merged and key in existing:
                merged[key] = existing[key]

    certificate_password = merged.get("certificate_password")
    if certificate_password == _SHAREPOINT_CERT_PASSWORD_MASK:
        certificate_password = existing.get("certificate_password")

    if certificate_password in ("", None):
        if uploaded_cert is None and existing.get("certificate_password") not in ("", None):
            merged["certificate_password"] = existing.get("certificate_password")
        else:
            merged.pop("certificate_password", None)
    else:
        merged["certificate_password"] = str(certificate_password)

    return merged


def _is_sharepoint_derived_edit_field(field_name, destination_name=None):
    if not _is_sharepoint_destination(destination_name):
        return False

    return field_name in {
        "client_certificate_uploaded",
        "certificate_password_set",
        "client_certificate_file",
    }


@csrf_exempt
def stripe_webhook(request):
    logger.info(
        "[STRIPE][WEBHOOK] Received webhook request | content_length=%s signature_present=%s",
        request.META.get("CONTENT_LENGTH"),
        bool(request.META.get("HTTP_STRIPE_SIGNATURE")),
    )
    payload_bytes = request.body
    signature_header = request.META.get("HTTP_STRIPE_SIGNATURE")
    webhook_secret = getattr(settings, "STRIPE_WEBHOOK_SECRET", "")
    if not webhook_secret:
        logger.error("[STRIPE][WEBHOOK] STRIPE_WEBHOOK_SECRET is not configured")
        return HttpResponse(status=400)
    try:
        event = stripe.Webhook.construct_event(
            payload_bytes,
            signature_header,
            webhook_secret,
        )
    except Exception as webhook_error:
        logger.warning(
            "[STRIPE][WEBHOOK] Signature verification failed: %s",
            webhook_error,
        )
        return HttpResponse(status=400)

    event_type = event.get("type")
    event_id = event.get("id")
    logger.info(
        "[STRIPE][WEBHOOK] Event received | type=%s id=%s",
        event_type,
        event_id,
    )
    stripe_event = None
    if event_id:
        try:
            with transaction.atomic():
                stripe_event, created = StripeWebhookEvent.objects.get_or_create(
                    event_id=event_id,
                    defaults={"event_type": event_type},
                )
            if not created:
                logger.info(
                    "[STRIPE][WEBHOOK] Duplicate event received; skipping | event_id=%s type=%s",
                    event_id,
                    event_type,
                )
                return HttpResponse(status=200)
        except Exception as event_error:
            logger.warning(
                "[STRIPE][WEBHOOK] Failed to register event | event_id=%s type=%s error=%s",
                event_id,
                event_type,
                event_error,
            )

    if event_type == "payment_intent.succeeded":
        from apps.elttool.billing.services.invoice_email import send_invoice_paid_email

        payment_intent = event["data"]["object"]
        metadata = payment_intent.get("metadata") or {}
        invoice_id = metadata.get("invoice_id")
        if not invoice_id:
            logger.warning(
                "[STRIPE][WEBHOOK] Missing invoice_id in metadata | intent_id=%s metadata_keys=%s",
                payment_intent.get("id"),
                list(metadata.keys()),
            )
            if stripe_event:
                stripe_event.status = "skipped"
                stripe_event.processed_at = timezone.now()
                stripe_event.save(update_fields=["status", "processed_at"])
            return HttpResponse(status=200)
        try:
            invoice = Invoice.objects.get(id=invoice_id)
        except Invoice.DoesNotExist:
            logger.warning(
                "[STRIPE][WEBHOOK] Invoice not found for id=%s",
                invoice_id,
            )
            if stripe_event:
                stripe_event.status = "skipped"
                stripe_event.processed_at = timezone.now()
                stripe_event.save(update_fields=["status", "processed_at"])
            return HttpResponse(status=200)
        if invoice.payment_status == "PAID":
            logger.info(
                "[STRIPE][WEBHOOK] Invoice %s already marked as PAID, skipping",
                invoice_id,
            )
            if stripe_event:
                stripe_event.invoice = invoice
                stripe_event.status = "skipped"
                stripe_event.processed_at = timezone.now()
                stripe_event.save(update_fields=["invoice", "status", "processed_at"])
            return HttpResponse(status=200)
        payment_method_id = payment_intent.get("payment_method")
        customer_id = payment_intent.get("customer")
        logger.info(
            "[STRIPE][WEBHOOK] Payment intent details | intent_id=%s customer_id=%s payment_method_id=%s",
            payment_intent.get("id"),
            customer_id,
            payment_method_id,
        )
        if payment_method_id and customer_id:
            logger.info(
                "[STRIPE][WEBHOOK] Attaching payment method | customer_id=%s payment_method_id=%s",
                customer_id,
                payment_method_id,
            )
            try:
                stripe.PaymentMethod.attach(
                    payment_method_id,
                    customer=customer_id,
                )
                stripe.Customer.modify(
                    customer_id,
                    invoice_settings={"default_payment_method": payment_method_id},
                )
                logger.info(
                    "[STRIPE][WEBHOOK] Payment method attached and set as default | customer_id=%s",
                    customer_id,
                )
            except Exception as attach_error:
                logger.warning(
                    "[STRIPE][WEBHOOK] Failed to attach payment method: %s",
                    attach_error,
                )
        charges = (payment_intent.get("charges") or {}).get("data") or []
        if not charges:
            latest_charge_id = payment_intent.get("latest_charge")
            if latest_charge_id:
                try:
                    charge = stripe.Charge.retrieve(
                        latest_charge_id,
                        expand=["payment_method_details", "billing_details"],
                    )
                    if charge:
                        charges = [charge]
                except Exception as charge_error:
                    logger.warning(
                        "[STRIPE][WEBHOOK] Failed to fetch latest charge %s: %s",
                        latest_charge_id,
                        charge_error,
                    )
        card_details = {}
        billing_details = {}
        if charges:
            card_details = (
                charges[0]
                .get("payment_method_details", {})
                .get("card", {})
            )
            billing_details = charges[0].get("billing_details", {}) or {}
        receipt_url = charges[0].get("receipt_url") if charges else None
        invoice.payment_status = "PAID"
        invoice.payment_date = timezone.now()
        invoice.payment_reference = payment_intent.get("id")
        invoice.receipt_url = receipt_url
        invoice.payment_method_last4 = card_details.get("last4")
        invoice.payment_method_brand = card_details.get("brand")
        invoice.payment_method_exp_month = card_details.get("exp_month")
        invoice.payment_method_exp_year = card_details.get("exp_year")
        invoice.card_holder_name = billing_details.get("name")
        invoice.failure_reason = None
        safe_payment_intent = copy.deepcopy(payment_intent)
        safe_payment_intent.pop("client_secret", None)
        invoice.decrypted_payment_details = {
            "event_id": event.get("id"),
            "event_type": event_type,
            "webhook_received_at": timezone.now().isoformat(),
            "payment_intent": safe_payment_intent,
        }
        invoice.save(update_fields=[
            "payment_status",
            "payment_date",
            "payment_reference",
            "receipt_url",
            "payment_method_last4",
            "payment_method_brand",
            "payment_method_exp_month",
            "payment_method_exp_year",
            "card_holder_name",
            "failure_reason",
            "payment_details",
        ])
        if stripe_event:
            stripe_event.invoice = invoice
            stripe_event.status = "processed"
            stripe_event.processed_at = timezone.now()
            stripe_event.save(update_fields=["invoice", "status", "processed_at"])
        company = invoice.cmp
        company_updates = {}
        stripe_customer_id = payment_intent.get("customer")
        stripe_payment_method_id = payment_intent.get("payment_method")
        if stripe_customer_id:
            company_updates["stripe_customer_id"] = stripe_customer_id
        if stripe_payment_method_id:
            company_updates["stripe_default_payment_method_id"] = stripe_payment_method_id
        if card_details:
            company_updates["stripe_card_last4"] = card_details.get("last4")
            company_updates["stripe_card_brand"] = card_details.get("brand")
            company_updates["stripe_card_exp_month"] = card_details.get("exp_month")
            company_updates["stripe_card_exp_year"] = card_details.get("exp_year")
        if billing_details.get("name"):
            company_updates["stripe_card_holder_name"] = billing_details.get("name")
        if company_updates:
            for field_name, field_value in company_updates.items():
                setattr(company, field_name, field_value)
            company.save(update_fields=list(company_updates.keys()))
            logger.info(
                "[STRIPE][WEBHOOK] Updated company %s with Stripe payment method details",
                company.cmp_id,
            )
        logger.info(
            "[STRIPE][WEBHOOK] Invoice %s marked as PAID (intent=%s)",
            invoice_id,
            payment_intent.get("id"),
        )
        try:
            send_invoice_paid_email(invoice)
        except Exception as email_error:
            logger.warning(
                "[STRIPE][WEBHOOK] Failed to send invoice email for %s: %s",
                invoice_id,
                email_error,
            )
    elif event_type == "payment_intent.payment_failed":
        from apps.elttool.billing.services.invoice_email import send_invoice_payment_failed_email

        payment_intent = event["data"]["object"]
        metadata = payment_intent.get("metadata") or {}
        invoice_id = metadata.get("invoice_id")
        if not invoice_id:
            logger.warning(
                "[STRIPE][WEBHOOK] Missing invoice_id in metadata for failed intent | intent_id=%s metadata_keys=%s",
                payment_intent.get("id"),
                list(metadata.keys()),
            )
            if stripe_event:
                stripe_event.status = "skipped"
                stripe_event.processed_at = timezone.now()
                stripe_event.save(update_fields=["status", "processed_at"])
            return HttpResponse(status=200)
        try:
            invoice = Invoice.objects.get(id=invoice_id)
        except Invoice.DoesNotExist:
            logger.warning(
                "[STRIPE][WEBHOOK] Invoice not found for id=%s (failed intent)",
                invoice_id,
            )
            if stripe_event:
                stripe_event.status = "skipped"
                stripe_event.processed_at = timezone.now()
                stripe_event.save(update_fields=["status", "processed_at"])
            return HttpResponse(status=200)
        if invoice.payment_status == "PAID":
            logger.info(
                "[STRIPE][WEBHOOK] Invoice %s already PAID; ignoring failed intent",
                invoice_id,
            )
            if stripe_event:
                stripe_event.invoice = invoice
                stripe_event.status = "skipped"
                stripe_event.processed_at = timezone.now()
                stripe_event.save(update_fields=["invoice", "status", "processed_at"])
            return HttpResponse(status=200)
        previous_status = invoice.payment_status
        previous_reason = invoice.get_decrypted_field("failure_reason")
        charges = (payment_intent.get("charges") or {}).get("data") or []
        if not charges:
            latest_charge_id = payment_intent.get("latest_charge")
            if latest_charge_id:
                try:
                    charge = stripe.Charge.retrieve(
                        latest_charge_id,
                        expand=["payment_method_details", "billing_details"],
                    )
                    if charge:
                        charges = [charge]
                except Exception as charge_error:
                    logger.warning(
                        "[STRIPE][WEBHOOK] Failed to fetch latest charge %s: %s",
                        latest_charge_id,
                        charge_error,
                    )
        card_details = {}
        billing_details = {}
        if charges:
            card_details = (
                charges[0]
                .get("payment_method_details", {})
                .get("card", {})
            )
            billing_details = charges[0].get("billing_details", {}) or {}
        invoice.payment_status = "FAILED"
        invoice.payment_reference = payment_intent.get("id")
        invoice.receipt_url = None
        invoice.failure_reason = str(payment_intent.get("last_payment_error") or "")
        invoice.payment_method_last4 = card_details.get("last4")
        invoice.payment_method_brand = card_details.get("brand")
        invoice.payment_method_exp_month = card_details.get("exp_month")
        invoice.payment_method_exp_year = card_details.get("exp_year")
        invoice.card_holder_name = billing_details.get("name")
        safe_payment_intent = copy.deepcopy(payment_intent)
        safe_payment_intent.pop("client_secret", None)
        invoice.decrypted_payment_details = {
            "event_id": event.get("id"),
            "event_type": event_type,
            "webhook_received_at": timezone.now().isoformat(),
            "payment_intent": safe_payment_intent,
        }
        invoice.save(update_fields=[
            "payment_status",
            "payment_reference",
            "receipt_url",
            "failure_reason",
            "payment_method_last4",
            "payment_method_brand",
            "payment_method_exp_month",
            "payment_method_exp_year",
            "card_holder_name",
            "payment_details",
        ])
        if stripe_event:
            stripe_event.invoice = invoice
            stripe_event.status = "processed"
            stripe_event.processed_at = timezone.now()
            stripe_event.save(update_fields=["invoice", "status", "processed_at"])
        logger.info(
            "[STRIPE][WEBHOOK] Invoice %s marked as FAILED (intent=%s)",
            invoice_id,
            payment_intent.get("id"),
        )
        current_reason = invoice.get_decrypted_field("failure_reason")
        if previous_status != "FAILED" or (previous_reason or "") != (current_reason or ""):
            try:
                send_invoice_payment_failed_email(invoice, current_reason)
            except Exception as email_error:
                logger.warning(
                    "[STRIPE][WEBHOOK] Failed to send payment failure email for %s: %s",
                    invoice_id,
                    email_error,
                )
    elif event_type == "setup_intent.succeeded":
        setup_intent = event["data"]["object"]
        metadata = setup_intent.get("metadata") or {}
        cmp_id = metadata.get("cmp_id")
        stripe_customer_id = setup_intent.get("customer")
        stripe_payment_method_id = setup_intent.get("payment_method")

        if not cmp_id:
            logger.warning("[STRIPE][WEBHOOK] Missing cmp_id in setup_intent metadata")
            if stripe_event:
                stripe_event.status = "skipped"
                stripe_event.processed_at = timezone.now()
                stripe_event.save(update_fields=["status", "processed_at"])
            return HttpResponse(status=200)

        try:
            company = Company.objects.get(cmp_id=cmp_id)
        except Company.DoesNotExist:
            logger.warning(
                "[STRIPE][WEBHOOK] Company not found for cmp_id=%s (setup_intent)",
                cmp_id,
            )
            if stripe_event:
                stripe_event.status = "skipped"
                stripe_event.processed_at = timezone.now()
                stripe_event.save(update_fields=["status", "processed_at"])
            return HttpResponse(status=200)

        if stripe_payment_method_id and stripe_customer_id:
            logger.info(
                "[STRIPE][WEBHOOK] Attaching payment method from setup_intent | customer_id=%s payment_method_id=%s",
                stripe_customer_id,
                stripe_payment_method_id,
            )
            try:
                stripe.PaymentMethod.attach(
                    stripe_payment_method_id,
                    customer=stripe_customer_id,
                )
                stripe.Customer.modify(
                    stripe_customer_id,
                    invoice_settings={"default_payment_method": stripe_payment_method_id},
                )
            except Exception as attach_error:
                logger.warning(
                    "[STRIPE][WEBHOOK] Failed to attach setup_intent payment method: %s",
                    attach_error,
                )

        card_details = {}
        billing_details = {}
        if stripe_payment_method_id:
            try:
                payment_method = stripe.PaymentMethod.retrieve(stripe_payment_method_id)
                card_details = payment_method.get("card") or {}
                billing_details = payment_method.get("billing_details") or {}
            except Exception as payment_method_error:
                logger.warning(
                    "[STRIPE][WEBHOOK] Failed to retrieve payment method %s: %s",
                    stripe_payment_method_id,
                    payment_method_error,
                )

        company_updates = {}
        if stripe_customer_id:
            company_updates["stripe_customer_id"] = stripe_customer_id
        if stripe_payment_method_id:
            company_updates["stripe_default_payment_method_id"] = stripe_payment_method_id
        if card_details:
            company_updates["stripe_card_last4"] = card_details.get("last4")
            company_updates["stripe_card_brand"] = card_details.get("brand")
            company_updates["stripe_card_exp_month"] = card_details.get("exp_month")
            company_updates["stripe_card_exp_year"] = card_details.get("exp_year")
        if billing_details.get("name"):
            company_updates["stripe_card_holder_name"] = billing_details.get("name")

        if company_updates:
            for field_name, field_value in company_updates.items():
                setattr(company, field_name, field_value)
            company.save(update_fields=list(company_updates.keys()))
            logger.info(
                "[STRIPE][WEBHOOK] Updated company %s with setup_intent payment method",
                company.cmp_id,
            )

        if stripe_event:
            stripe_event.status = "processed"
            stripe_event.processed_at = timezone.now()
            stripe_event.save(update_fields=["status", "processed_at"])

    return HttpResponse(status=200)


def format_error_message(message):
    """
    Ensures error messages start with "Error: " prefix.
    If message is None or empty, returns a default error message.
    """
    if not message:
        return "Error: An unexpected error occurred."
    
    message_str = str(message).strip()
    
    # If already starts with "Error: " or "error: ", return as is (normalize case)
    if message_str.lower().startswith("error: "):
        # Normalize to "Error: " (capital E)
        if message_str.startswith("error: "):
            return "Error: " + message_str[7:].strip()
        return message_str
    
    # Add "Error: " prefix if not present
    return f"Error: {message_str}"


def normalize_snowflake_connectivity_error_message(message):
    """Return backend error text as-is (no message substitution)."""
    return str(message or "").strip()

    trial_expired_markers = [
        "your free trial has ended",
        "trial has ended",
        "trial expired",
        "virtual warehouses have been suspended",
        "add billing information in the snowflake web ui",
        "billing information",
    ]
    if any(marker in msg_lower for marker in trial_expired_markers):
        return (
            "Snowflake trial expired or billing is inactive. "
            "Please add billing in Snowflake or reactivate your warehouse."
        )

    snowflake_markers = [
        "could not connect to snowflake backend",
        "failed to connect to snowflake",
        "snowflake backend",
        "250001",
        "251012",
        "login request is retryable",
    ]
    if any(marker in msg_lower for marker in snowflake_markers):
        return "Unable to connect to Snowflake at the moment. The Snowflake service may be temporarily unavailable. Please try again later."

def unwrap_backend_error_detail(error_value):
    """
    Return the user-facing reason from backend error payloads.

    Migration services often return FastAPI errors as {"detail": "..."}.
    If that JSON reaches the task aggregator as a string, show only the detail
    instead of leaking the wrapper into API responses and logs.
    """
    if error_value is None:
        return ""

    payload = error_value
    if isinstance(payload, str):
        payload = payload.strip()
        if not payload:
            return ""
        prefixes = (
            "Error:",
            "HTTPException:",
            "Authorization service returned HTTP 400:",
            "Authorization service returned HTTP 401:",
            "Authorization service returned HTTP 403:",
            "Authorization service returned HTTP 404:",
            "Authorization service returned HTTP 409:",
            "Authorization service returned HTTP 422:",
            "Authorization service returned HTTP 500:",
        )
        for prefix in prefixes:
            if payload.startswith(prefix):
                return unwrap_backend_error_detail(payload[len(prefix):].strip())

        # Some callers prepend context before the serialized FastAPI payload.
        # Preserve the prefix, but unwrap the payload portion.
        json_start = payload.find('{"detail"')
        if json_start == -1:
            json_start = payload.find("{'detail'")
        if json_start > 0:
            prefix = payload[:json_start].strip(" :")
            detail = unwrap_backend_error_detail(payload[json_start:])
            return f"{prefix}: {detail}" if prefix else detail

        try:
            payload = json.loads(payload)
        except Exception:
            try:
                payload = ast.literal_eval(payload)
            except Exception:
                return payload

    if isinstance(payload, dict):
        if "loc" in payload and "msg" in payload:
            loc = payload.get("loc") or []
            field = ".".join(str(part) for part in loc if part not in ("body", "__root__"))
            msg = unwrap_backend_error_detail(payload.get("msg"))
            return f"{field}: {msg}" if field else msg

        detail = payload.get("detail") or payload.get("message") or payload.get("body") or payload.get("error")
        if detail is None:
            return str(payload)
        return unwrap_backend_error_detail(detail)

    if isinstance(payload, list):
        parts = [unwrap_backend_error_detail(item) for item in payload]
        return "; ".join([part for part in parts if part])

    return str(payload)


