def sanitize_identifier(name):
    """Sanitize identifier for Snowflake/table-name comparisons."""
    return re.sub(r"[^A-Z0-9_]", "_", str(name or "").upper())


def extract_api_error_message(response):
    """
    Extract a user-friendly error message from upstream API response.
    """
    try:
        payload = response.json()
    except Exception:
        payload = None

    if isinstance(payload, dict):
        detail = payload.get("detail")
        if isinstance(detail, str) and detail.strip():
            return detail.strip()
        if isinstance(detail, list) and detail:
            first = detail[0]
            if isinstance(first, dict):
                msg = first.get("msg") or first.get("detail")
                if msg:
                    return str(msg)
            if isinstance(first, str):
                return first

        for key in ("message", "body", "error"):
            value = payload.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()

        return str(payload)

    text = (response.text or "").strip()
    if text:
        return text
    return f"Request failed with HTTP {response.status_code}."


