# ✅ HELPER FUNCTIONS FOR DRY CODE - STANDARDIZED PATTERNS
# ===========================================================================================

def safe_parse_json(data, default=None, field_name="data"):
    """
    Safely parse JSON string to dict/list, with fallback to default value.
    
    Args:
        data: String, dict, list, or other type to parse
        default: Default value if parsing fails (default: None)
        field_name: Name of field for logging (default: "data")
    
    Returns:
        Parsed dict/list if successful, otherwise default value
    """
    if isinstance(data, (dict, list)):
        return data
    
    if isinstance(data, str):
        try:
            return json.loads(data)
        except (json.JSONDecodeError, ValueError) as e:
            logger.warning(f"Failed to parse {field_name} JSON string: {e}")
            return default if default is not None else {}
    
    return default if default is not None else {}


def merge_salesforce_oauth_source_config(existing_data, form_data, updated_data):
    """
    Merge OAuth callback data into a Salesforce/Sandbox source config.

    Preserves existing CLIENT_ID/CLIENT_SECRET when present, but backfills them from
    the OAuth session form when missing (e.g. after a prior save lost credentials).
    """
    if not isinstance(existing_data, dict):
        existing_data = safe_parse_json(existing_data, default={}, field_name="existing_config_data")
    if not isinstance(form_data, dict):
        form_data = {}
    credential_fields = ("connection_name", "CLIENT_ID", "CLIENT_SECRET", "CUSTOM_DOMAIN")
    for field in credential_fields:
        value = form_data.get(field)
        if value is not None and str(value).strip() != "" and not existing_data.get(field):
            existing_data[field] = value
    if isinstance(updated_data, dict):
        existing_data.update(updated_data)
    return existing_data


def remove_old_key_pair_fields(config_data, config_type="config"):
    """
    Remove old key pair fields (private_key, public_key, passphrase) from config_data
    if authentication_type is not "key_pair".
    
    This ensures that when a user switches from key_pair to password authentication,
    old key fields are cleaned up to prevent stale data from being returned.
    
    Args:
        config_data: Dictionary containing configuration data (modified in-place)
        config_type: Type of config for logging (e.g., "destination", "source")
    
    Returns:
        list: List of removed field names (empty if none removed)
    """
    if not isinstance(config_data, dict):
        return []
    
    auth_type = str(config_data.get("authentication_type", "")).lower()
    # Salesforce JWT Bearer also stores private_key/passphrase but is not Snowflake key_pair auth.
    if auth_type in ("jwt_bearer", "jwt", "jwt-bearer"):
        return []
    if auth_type != "key_pair":
        key_fields_to_remove = ["private_key", "public_key", "passphrase"]
        removed_fields = []
        for field in key_fields_to_remove:
            if field in config_data:
                del config_data[field]
                removed_fields.append(field)
        
        if removed_fields:
            print(f"🧹 Removed old key pair fields from {config_type} (auth_type={auth_type}): {removed_fields}")
        
        return removed_fields
    
    return []


def _is_salesforce_jwt_config(config_data) -> bool:
    if not isinstance(config_data, dict):
        return False
    auth_type = str(config_data.get("authentication_type") or "oauth").strip().lower()
    return auth_type in ("jwt_bearer", "jwt", "jwt-bearer")


def sanitize_salesforce_config_for_auth_type(config_data, config_type="config"):
    """Remove irrelevant Salesforce auth fields when switching OAuth vs JWT Bearer."""
    if not isinstance(config_data, dict):
        return config_data

    sanitized = dict(config_data)
    if _is_salesforce_jwt_config(sanitized):
        for key in ("access_token", "refresh_token", "CLIENT_SECRET", "state"):
            sanitized.pop(key, None)
    else:
        for key in ("private_key", "passphrase", "integration_username"):
            sanitized.pop(key, None)
        if not sanitized.get("authentication_type"):
            sanitized["authentication_type"] = "oauth"
    return sanitized


def _merge_salesforce_jwt_fields_on_edit(existing_data, incoming_data):
    """Preserve JWT private key on edit when UI sends empty/masked values."""
    if not isinstance(existing_data, dict):
        existing_data = safe_parse_json(existing_data, default={}, field_name="existing_config_data")
    if not isinstance(incoming_data, dict):
        return incoming_data

    merged = dict(incoming_data)
    for key in ("private_key", "passphrase", "integration_username", "CLIENT_ID", "CUSTOM_DOMAIN"):
        value = merged.get(key)
        if value in (None, "", "********") and existing_data.get(key):
            merged[key] = existing_data.get(key)
    return merged


def _apply_salesforce_jwt_validation_response(config_data, response_json):
    if not isinstance(config_data, dict) or not isinstance(response_json, dict):
        return config_data
    if response_json.get("instance_url"):
        config_data["instance_url"] = response_json["instance_url"]
    if response_json.get("access_token"):
        config_data["access_token"] = response_json["access_token"]
    config_data["authentication_type"] = "jwt_bearer"
    return config_data


def has_data_transfers(connection):
    """
    Check if a connection has any Data_Transfer records (has been synced at least once).
    
    Args:
        connection: Connection model instance or connection_id (int)
    
    Returns:
        bool: True if connection has data transfers, False otherwise
    """
    if isinstance(connection, int):
        return Data_Transfer.objects.filter(connection_id=connection).exists()
    return Data_Transfer.objects.filter(connection=connection).exists()


def parse_s3_mapping_json(mapping_data, mapping_type="mapping"):
    """
    Parse S3 mapping data from JSON string.
    
    Args:
        mapping_data: String (JSON) or dict
        mapping_type: Type of mapping for logging (default: "mapping")
    
    Returns:
        dict: Parsed mapping dictionary, or empty dict if parsing fails
    """
    if isinstance(mapping_data, dict):
        return mapping_data
    
    if isinstance(mapping_data, str):
        try:
            parsed = json.loads(mapping_data)
            if isinstance(parsed, dict):
                return parsed
            logger.warning(f"S3 {mapping_type} parsed but not a dict: {type(parsed)}")
            return {}
        except (json.JSONDecodeError, ValueError) as e:
            logger.warning(f"Failed to parse S3 {mapping_type} JSON: {e}")
            return {}
    
    return {}


def normalize_s3_base_prefix(base_prefix):
    """
    Normalize S3 folder path for consistent save/compare.
    Example: "folder//sub" -> "folder/sub/"; invalid prefixes remain unchanged.
    """
    if base_prefix is None:
        return ""
    value = str(base_prefix).strip().replace("\\", "/")
    # Keep invalid prefixes intact so callers cannot normalize away validation errors.
    if value.lower().startswith("s3:") or value.startswith("/"):
        return value
    value = re.sub(r"/+", "/", value).lstrip("/")
    if value and not value.endswith("/"):
        value += "/"
    return value


def validate_s3_base_prefix(base_prefix):
    """
    Validate S3 base folder path format.
    Must be a relative key prefix (not full s3:// URL).
    """
    if base_prefix in (None, ""):
        return True, None
    value = str(base_prefix).strip()
    if value.lower().startswith("s3:"):
        return False, "Use folder path only in S3 base path (for example: 'folder/subfolder/'), not full s3:// URL."
    if value.startswith("/"):
        return False, "S3 base path should not start with '/'. Use relative folder path."
    # Catch common typo: accidental spaces around path separators.
    # Example invalid: "VINOD/ CSV/MULTI/" or "VINOD /CSV/MULTI/"
    if re.search(r"(?:^|/)\s+|\s+(?:/|$)", value):
        shown_value = value if len(value) <= 200 else f"{value[:200]}..."
        return False, (
            "S3 base path contains extra spaces around '/'. "
            "Remove spaces around folder separators (for example: 'folder/subfolder/'). "
            f"Received: '{shown_value}'"
        )
    return True, None


def normalize_amazons3_destination_config_for_authorization(config_data):
    """
    Keep destination form naming stable while sending the auth service the
    canonical S3 prefix field it validates.
    """
    if not isinstance(config_data, dict):
        raise ValueError("AmazonS3 destination configuration must be a dictionary.")

    normalized_config = dict(config_data)
    base_folder_path = (
        normalized_config.get("base_folder_path")
        or normalized_config.get("base_folder")
        or normalized_config.get("s3_base_prefix")
        or ""
    )
    normalized_base_prefix = normalize_s3_base_prefix(base_folder_path)
    s3_prefix_valid, s3_prefix_error = validate_s3_base_prefix(normalized_base_prefix)
    if not s3_prefix_valid:
        raise ValueError(s3_prefix_error)

    normalized_config["s3_base_prefix"] = normalized_base_prefix
    return normalized_config


def format_amazons3_destination_error_message(message):
    return str(message or "").replace("s3_base_prefix", "base_folder_path")

def is_dynamics_fo_source(source_name: str) -> bool:
    """True when the source connector is Microsoft Dynamics 365 F&O."""
    return source_name == "MicrosoftDynamics365_FO"


def _parse_config_bool(value) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() in {"1", "true", "yes", "on"}


def is_sap_odata_source(source_name: str) -> bool:
    """True when the source connector is SAP OData."""
    return source_name == "SAPOData"


LISTING_CAPABLE_SOURCES = frozenset({
    "Snowflake",
    "Databricks",
    "MicrosoftDynamics365_FO",
    "SAPOData",
    "NetSuite",
    "Salesforce",
    "SalesforceSandbox",
    "GoogleReviews",
})


def should_auto_trigger_schema_refresh_on_create(source_name: str) -> bool:
    """Sources that run listing-tables automatically when a connection is first created."""
    return is_file_based_source(source_name) or source_name in LISTING_CAPABLE_SOURCES

def _coerce_destination_config_id(value):
    """Parse session/request destination_config_id values safely."""
    if value is None or value == "":
        return None
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return None
    return parsed if parsed > 0 else None

def _resolve_destination_config_id_for_connection_save(request, connection, is_update):
    """
    Resolve which DestinationConfig to bind on source connection save.

    Create: prefer destination_config_id from the request body (JWT SPA clients
    may not round-trip Django session cookies), then fall back to session.
    Update: keep the connection's existing destination unless the client
    explicitly sends destination_config_id — ignore stale session values that
    may linger from another connector flow (e.g. Snowflake→Salesforce RETL).
    """
    session_id = _coerce_destination_config_id(request.session.get("destination_config_id"))
    explicit_id = _coerce_destination_config_id(request.data.get("destination_config_id"))

    if is_update and connection is not None:
        existing_id = connection.dst_config.dst_config_id
        if explicit_id is not None:
            return explicit_id, "request"
        if session_id is not None and session_id != existing_id:
            logger.warning(
                "Ignoring stale session destination_config_id on connection update | "
                "connection_id=%s session_dst=%s existing_dst=%s",
                connection.connection_id,
                session_id,
                existing_id,
            )
        return existing_id, "existing_connection"

    if explicit_id is not None:
        return explicit_id, "request"
    if session_id is not None:
        return session_id, "session"
    if connection is not None:
        return connection.dst_config.dst_config_id, "existing_connection"
    return None, None


def is_amazon_s3_source(source_name: str, actual_source_name: str = None) -> bool:
    """
    DRY helper to check if source is AmazonS3.
    
    Args:
        source_name: Source name from URL/request
        actual_source_name: Actual source name (if different from source_name)
    
    Returns:
        True if source is AmazonS3, False otherwise
    """
    return (source_name == "AmazonS3" or (actual_source_name and actual_source_name == "AmazonS3"))


def save_shared_file_mapping(connection, source_form_data, user):
    """Save SFTP, Google Drive, or ADLS file/table mapping state."""
    mode = (
        source_form_data.get("file_mapping_method")
        or source_form_data.get("file_mapping_mode")
        or "single_table_per_file"
    )
    single_map = parse_s3_mapping_json(
        source_form_data.get("single_file_table_mapping") or {},
        mapping_type="single_file_table_mapping",
    )
    multi_map = parse_s3_mapping_json(
        source_form_data.get("table_to_files_mapping") or {},
        mapping_type="table_to_files_mapping",
    )
    source_id = getattr(connection.src_config, "src_id", None)
    cmp_id = getattr(user, "cmp_id", None) or getattr(connection, "cmp_id", None)
    user_id = getattr(user, "user_id", None)
    basefolder_path = (
        source_form_data.get("base_folder_path")
        or source_form_data.get("s3_base_prefix")
        or source_form_data.get("root_folder")
        or source_form_data.get("folder_id")
        or source_form_data.get("folder_name")
        or ""
    )
    mapping, created = SourceFileMapping.objects.get_or_create(
        connection=connection,
        defaults={
            "file_mapping_mode": mode,
            "single_file_table_mapping": single_map,
            "table_to_files_mapping": multi_map,
            "cmp_id": cmp_id,
            "source_id": source_id,
            "basefolder_path": basefolder_path,
            "created_by": user_id,
            "updated_by": user_id,
        },
    )
    if not created:
        mapping.file_mapping_mode = mode
        mapping.single_file_table_mapping = single_map
        mapping.table_to_files_mapping = multi_map
        mapping.cmp_id = cmp_id
        mapping.source_id = source_id
        mapping.basefolder_path = basefolder_path
        if mapping.created_by is None:
            mapping.created_by = user_id
        mapping.updated_by = user_id
        mapping.save(update_fields=[
            "file_mapping_mode",
            "single_file_table_mapping",
            "table_to_files_mapping",
            "cmp_id",
            "source_id",
            "basefolder_path",
            "created_by",
            "updated_by",
            "updated_at",
        ])
    return mapping


def _google_drive_request_config(data):
    for config_key in ("GoogleDrive", "googledrive", "form_data"):
        if isinstance(data.get(config_key), dict):
            return data.get(config_key) or {}
    return data


def _optional_enum_value(data, source_config, key):
    """Return None for blank optional enum fields (json_mode/xml_mode on CSV sources)."""
    value = _google_drive_value(data, source_config, key, None)
    if value in (None, "", "null", "undefined"):
        return None
    return value


def _build_google_drive_config(data, source_config):
    request_config = _google_drive_request_config(data)
    if not isinstance(request_config, dict):
        request_config = {}

    file_mapping_mode = (
        _google_drive_value(data, source_config, "file_mapping_method")
        or _google_drive_value(data, source_config, "file_mapping_mode")
        or "single_table_per_file"
    )
    drive_config = {
        **source_config,
        **request_config,
        "CLIENT_ID": (
            _google_drive_value(data, source_config, "CLIENT_ID")
            or _google_drive_value(data, source_config, "client_id")
        ),
        "CLIENT_SECRET": (
            _google_drive_value(data, source_config, "CLIENT_SECRET")
            or _google_drive_value(data, source_config, "client_secret")
        ),
        "access_token": _google_drive_value(data, source_config, "access_token"),
        "refresh_token": _google_drive_value(data, source_config, "refresh_token"),
        "token_expires_at": _google_drive_value(data, source_config, "token_expires_at"),
        "folder_id": _google_drive_value(data, source_config, "folder_id"),
        "folder_name": _google_drive_value(data, source_config, "folder_name"),
        "include_subfolders": parse_bool_like(
            _google_drive_value(data, source_config, "include_subfolders"),
            default=False,
        ),
        "file_type": _google_drive_value(data, source_config, "file_type"),
        "file_mapping_method": file_mapping_mode,
        "file_mapping_mode": file_mapping_mode,
        "single_file_table_mapping": parse_s3_mapping_json(
            _google_drive_value(data, source_config, "single_file_table_mapping"),
            mapping_type="single_file_table_mapping",
        ),
        "table_to_files_mapping": _google_drive_value(
            data, source_config, "table_to_files_mapping", {}
        ) or {},
        "multi_files_prefix": _google_drive_value(
            data, source_config, "multi_files_prefix", ""
        ) or "",
        "multi_files_table_name": _google_drive_value(
            data, source_config, "multi_files_table_name", ""
        ) or "",
        "load_method": _google_drive_value(data, source_config, "load_method", "") or "",
        "custom_primary_key": _google_drive_value(
            data, source_config, "custom_primary_key", {}
        ) or {},
        "json_mode": _optional_enum_value(data, source_config, "json_mode"),
        "xml_mode": _optional_enum_value(data, source_config, "xml_mode"),
    }
    # Drop null optional enums so FastAPI/Pydantic does not reject empty strings.
    for optional_key in ("json_mode", "xml_mode"):
        if drive_config.get(optional_key) is None:
            drive_config.pop(optional_key, None)

    # The UI may submit blank hidden credential inputs. Treat those as absent
    # so an already-authorized connection continues using its stored tokens.
    for credential_key in (
        "CLIENT_ID",
        "CLIENT_SECRET",
        "access_token",
        "refresh_token",
        "token_expires_at",
    ):
        if drive_config.get(credential_key) in (None, ""):
            stored_value = source_config.get(credential_key)
            if stored_value not in (None, ""):
                drive_config[credential_key] = stored_value

    return drive_config


def _adls_proxy_timeout_message():
    return (
        "ADLS validation timed out while contacting Azure. "
        "Check the storage account name and Azure Storage firewall/private-network access."
    )


def overlay_file_mapping_from_source_file_mapping(connection, source_config):
    """Overlay shared file-source mappings from SourceFileMapping."""
    if not isinstance(source_config, dict):
        source_config = {}
    try:
        mapping = connection.source_file_mapping
    except SourceFileMapping.DoesNotExist:
        return source_config

    source_config["file_mapping_mode"] = (
        mapping.file_mapping_mode or "single_table_per_file"
    ).strip()
    source_config["single_file_table_mapping"] = (
        mapping.single_file_table_mapping
        if isinstance(mapping.single_file_table_mapping, dict)
        else {}
    )
    source_config["table_to_files_mapping"] = (
        mapping.table_to_files_mapping
        if isinstance(mapping.table_to_files_mapping, dict)
        else {}
    )
    return source_config


def persist_file_mapping_to_source_config_if_changed(connection, source_config):
    """Persist shared file-source mapping fields into SourceConfig.data."""
    if not isinstance(source_config, dict):
        return source_config
    try:
        current_data = ensure_config_is_dict(
            connection.src_config.data, "source_config"
        ) if connection.src_config.data else {}
    except Exception as error:
        logger.warning(
            "[FILE_MAPPING_SYNC] Could not parse source config | connection_id=%s error=%s",
            connection.connection_id,
            error,
        )
        return source_config

    target = {
        "file_mapping_mode": source_config.get("file_mapping_mode") or "single_table_per_file",
        "single_file_table_mapping": source_config.get("single_file_table_mapping") or {},
        "table_to_files_mapping": source_config.get("table_to_files_mapping") or {},
    }
    current = {
        "file_mapping_mode": current_data.get("file_mapping_mode") or "single_table_per_file",
        "single_file_table_mapping": current_data.get("single_file_table_mapping") or {},
        "table_to_files_mapping": current_data.get("table_to_files_mapping") or {},
    }
    if target == current:
        return source_config

    updated_data = dict(current_data)
    updated_data.update(target)
    connection.src_config.data = updated_data
    connection.src_config.save()
    logger.info(
        "[FILE_MAPPING_SYNC] source config synchronized | connection_id=%s mode=%s single=%s multi=%s",
        connection.connection_id,
        target["file_mapping_mode"],
        len(target["single_file_table_mapping"]),
        len(target["table_to_files_mapping"]),
    )
    return updated_data


def _normalize_pk_suggestion_response(result):
    """Ensure UI receives success=true when upstream returns status=success."""
    if not isinstance(result, dict):
        return {"success": False, "message": "Invalid PK suggestion response"}
    normalized = dict(result)
    if normalized.get("success") is True:
        return normalized
    if normalized.get("skipped"):
        normalized.setdefault("success", True)
        return normalized
    if normalized.get("status") == "success":
        normalized["success"] = True
        return normalized
    normalized.setdefault("success", False)
    return normalized


def _is_snowflake_destination(destination_name):
    return _normalize_destination_key(destination_name) == "snowflake"


def _connection_is_reverse_etl(connection) -> bool:
    """
    True for Snowflake -> non-warehouse destinations (Salesforce, SFTP, etc.).
    Snowflake -> Snowflake uses forward-ETL table selection (SourceTableSelection).
    """
    try:
        src = connection.src_config.src if connection.src_config else None
        if not src or not getattr(src, "is_rtl", False):
            return False
        dest_name = (
            connection.dst_config.dst.name
            if connection.dst_config and connection.dst_config.dst
            else None
        )
        return not _is_snowflake_destination(dest_name)
    except Exception:
        return False


def _resolve_auto_sync_table_selection(connection):
    """
    Resolve selected tables for scheduler registration and auto_sync runs.

    Rules (must stay aligned with task() auto_sync):
    - Snowflake -> Salesforce/Sandbox: table_mapping_retl [[src, dest], ...]
    - Snowflake -> Snowflake: SourceTableSelection (forward ETL despite is_rtl)
    - Snowflake -> file destinations (SFTP, SharePoint, etc.): SourceTableSelection
    """
    dest_platform = getattr(getattr(connection.dst_config, "dst", None), "name", None)
    connection_id = connection.connection_id
    is_reverse_etl = _connection_is_reverse_etl(connection)

    if is_reverse_etl and (not _is_file_based_destination(dest_platform)):
        selected_tables = get_table_mappings_by_connection(connection_id)
        selected_attributes_dict = {}
        last_checked_dates = {}
        if dest_platform == "GoogleDrive":
            rtl_queryset = SourceTableSelection.objects.filter(
                connection_id=connection_id, selected=True
            )
            selected_folder_path = _build_selected_table_folder_map(rtl_queryset, dest_platform)
        else:
            selected_folder_path = {}

        if not selected_tables:
            queryset = SourceTableSelection.objects.filter(
                connection_id=connection_id, selected=True
            ).order_by("sequence")
            selected_tables = list(queryset.values_list("table", flat=True))
            selected_attributes_dict = {row.table: row.json_path for row in queryset}
            selected_folder_path = _build_selected_table_folder_map(queryset, dest_platform)
            last_checked_dates = {row.table: row.last_synced for row in queryset}
    else:
        queryset = SourceTableSelection.objects.filter(
            connection_id=connection_id, selected=True
        )
        selected_tables = [row.table for row in queryset]
        selected_attributes_dict = {row.table: row.json_path for row in queryset}
        selected_folder_path = _build_selected_table_folder_map(queryset, dest_platform)
        last_checked_dates = {
            entry["table"]: entry["last_synced"]
            for entry in queryset.values("table", "last_synced")
        }

    return (
        selected_tables,
        selected_attributes_dict,
        selected_folder_path,
        last_checked_dates,
        is_reverse_etl,
    )


def is_sftp_source(source_name: str, actual_source_name: str = None) -> bool:
    """Return whether the source connector is SFTP."""
    return source_name == "SFTP" or actual_source_name == "SFTP"


def is_google_drive_source(source_name: str, actual_source_name: str = None) -> bool:
    """Return whether the source connector is Google Drive."""
    return source_name == "GoogleDrive" or actual_source_name == "GoogleDrive"


def is_adls_source(source_name: str, actual_source_name: str = None) -> bool:
    """Return whether the source connector is Azure Data Lake Storage."""
    source_values = {
        str(source_name or "").strip(),
        str(actual_source_name or "").strip(),
    }
    return bool(source_values & {"AzureDataLakeStorage", "ADLS"})


def is_file_based_source(source_name: str, actual_source_name: str = None) -> bool:
    """Return whether the connector uses file/table mapping configuration."""
    return (
        is_amazon_s3_source(source_name, actual_source_name)
        or is_sftp_source(source_name, actual_source_name)
        or is_google_drive_source(source_name, actual_source_name)
        or is_adls_source(source_name, actual_source_name)
    )


def parse_bool_like(value, default=False):
    """Parse bool-like payload values coming from dynamic forms."""
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        v = value.strip().lower()
        if v in {"true", "1", "yes", "y", "on"}:
            return True
        if v in {"false", "0", "no", "n", "off"}:
            return False
    return default


def prune_s3_mapping_for_removed_tables(connection, removed_table_names):
    """
    Remove mapping entries in s3_mapping for tables that were unselected/removed.
    Returns (removed_single_entries_count, removed_multi_tables_count).
    """
    if not removed_table_names:
        return 0, 0

    removed_set = {str(name).strip() for name in removed_table_names if str(name).strip()}
    removed_upper_set = {name.upper() for name in removed_set}
    if not removed_set:
        return 0, 0

    try:
        s3_mapping = connection.source_file_mapping
    except SourceFileMapping.DoesNotExist:
        return 0, 0

    file_mapping_mode = (s3_mapping.file_mapping_mode or "single_table_per_file").strip()
    single_map = s3_mapping.single_file_table_mapping if isinstance(s3_mapping.single_file_table_mapping, dict) else {}
    removed_single_count = 0
    removed_multi_count = 0

    if file_mapping_mode == "single_table_per_file":
        updated_single = {}
        for file_key, table_name in single_map.items():
            table_str = str(table_name).strip()
            if table_str in removed_set or table_str.upper() in removed_upper_set:
                removed_single_count += 1
                continue
            updated_single[file_key] = table_name

        if removed_single_count > 0:
            s3_mapping.single_file_table_mapping = updated_single
            s3_mapping.save(update_fields=["single_file_table_mapping", "updated_at"])
            logger.info(
                f"S3 mapping pruned for connection {connection.connection_id}: "
                f"removed {removed_single_count} single-file mapping entries"
            )

    return removed_single_count, removed_multi_count


def overlay_s3_mapping_from_source_file_mapping(connection, source_config):
    """
    Overlay S3 mapping fields in source_config using SourceFileMapping (DB source of truth).
    This prevents stale mapping values in source_config.data from being sent to migration service.
    """
    if not isinstance(source_config, dict):
        source_config = {}

    try:
        s3_mapping = connection.source_file_mapping
    except SourceFileMapping.DoesNotExist:
        return source_config

    file_mapping_mode = (s3_mapping.file_mapping_mode or "single_table_per_file").strip()
    single_map = (
        s3_mapping.single_file_table_mapping
        if isinstance(s3_mapping.single_file_table_mapping, dict)
        else {}
    )
    source_config["file_mapping_mode"] = file_mapping_mode
    source_config["single_file_table_mapping"] = single_map
    return source_config


def persist_s3_mapping_to_source_config_if_changed(connection, source_config):
    """
    Persist S3 mapping fields into SourceConfig.data only when values differ.
    Uses model-level encryption flow via SourceConfig.data setter + save().
    """
    if not isinstance(source_config, dict):
        return source_config

    try:
        current_data = ensure_config_is_dict(connection.src_config.data, "source_config") if connection.src_config.data else {}
    except Exception as e:
        logger.warning(
            "⚠️ [S3_MAPPING_SYNC] Skipping source_config mapping sync because existing source_config "
            "could not be parsed/decrypted | connection_id=%s error=%s",
            connection.connection_id,
            e,
        )
        return source_config

    target_mode = source_config.get("file_mapping_mode") or "single_table_per_file"
    target_single = source_config.get("single_file_table_mapping") or {}
    current_mode = current_data.get("file_mapping_mode") or "single_table_per_file"
    current_single = current_data.get("single_file_table_mapping") or {}

    mapping_changed = (
        current_mode != target_mode
        or current_single != target_single
    )
    if not mapping_changed:
        return source_config

    updated_data = dict(current_data)
    updated_data["file_mapping_mode"] = target_mode
    updated_data["single_file_table_mapping"] = target_single

    connection.src_config.data = updated_data
    connection.src_config.save()
    logger.info(
        "📝 [S3_MAPPING_SYNC] source_config mapping synced from SourceFileMapping | "
        "connection_id=%s mode=%s single_keys=%s",
        connection.connection_id,
        target_mode,
        len(target_single),
    )
    return updated_data


def clear_s3_multi_file_mapping_state(connection):
    """
    Prefix-driven multi-file mode no longer stores table/file mappings.
    Used when update-schema fails due to grouped-file structure mismatch.
    """
    return


def overlay_sftp_mapping_from_source_file_mapping(connection, source_config):
    """Overlay SFTP mapping fields from the persisted source mapping."""
    return overlay_file_mapping_from_source_file_mapping(connection, source_config)


