def persist_google_drive_mapping_to_source_config_if_changed(connection, source_config):
    """Persist Google Drive mapping fields into the source configuration."""
    return persist_file_mapping_to_source_config_if_changed(connection, source_config)


def overlay_adls_mapping_from_source_file_mapping(connection, source_config):
    """Overlay ADLS mapping fields from the persisted source mapping."""
    return overlay_file_mapping_from_source_file_mapping(connection, source_config)


def persist_adls_mapping_to_source_config_if_changed(connection, source_config):
    """Persist ADLS mapping fields into the source configuration."""
    return persist_file_mapping_to_source_config_if_changed(connection, source_config)


def create_error_response(message, error_code=None, status_code=status.HTTP_400_BAD_REQUEST, **extra_fields):
    """
    Create a standardized error response with "Error: " prefix.
    
    Args:
        message: Error message string (will be formatted with format_error_message)
        error_code: Optional error code (e.g., "MAPPING_MODE_IMMUTABLE")
        status_code: HTTP status code (default: 400)
        **extra_fields: Additional fields to include in response (e.g., table_name, removed_files)
    
    Returns:
        Response: DRF Response object with standardized error format
    """
    response_data = {
        "message": format_error_message(message),
    }
    
    if error_code:
        response_data["error"] = error_code
    
    # Add any extra fields (e.g., table_name, removed_files)
    response_data.update(extra_fields)
    
    return Response(response_data, status=status_code)


def create_success_response(message, data=None, status_code=status.HTTP_200_OK):
    """
    Create a standardized success response.
    
    Args:
        message: Success message string
        data: Optional additional data to include in response
        status_code: HTTP status code (default: 200)
    
    Returns:
        Response: DRF Response object with success message
    """
    response_data = {"message": message}
    if data:
        if isinstance(data, dict):
            response_data.update(data)
        else:
            response_data["data"] = data
    return Response(response_data, status=status_code)


def extract_backend_response_error(response, fallback_prefix="Authorization failed"):
    """
    Normalize backend API error from HTTP status and JSON payload style.

    Some backend endpoints return HTTP 200 with an inner {"status_code": <non-200>, "body": "..."}.
    This helper treats those as failures and extracts the most useful message.
    """
    http_status = getattr(response, "status_code", None)
    text_fallback = getattr(response, "text", "") or "Unknown error"

    payload = None
    try:
        payload = response.json()
    except Exception:
        payload = None

    inner_status = None
    detail = None
    if isinstance(payload, dict):
        inner_status = payload.get("status_code")
        detail = payload.get("body") or payload.get("message") or payload.get("detail")
        if isinstance(detail, dict):
            detail = detail.get("message") or str(detail)

    failed = (http_status != 200) or (isinstance(inner_status, int) and inner_status != 200)
    if not failed:
        return False, None

    effective_status = inner_status if isinstance(inner_status, int) else (http_status or 400)
    message = detail or text_fallback
    message = normalize_snowflake_connectivity_error_message(message)
    message = format_error_message(message)
    return True, f"{fallback_prefix} ({effective_status}): {message}"


def normalize_salesforce_auth_error_message(message, http_status=None):
    """Return backend error text as-is (no message substitution)."""
    return str(message or "").strip()


def validate_amazon_s3_form_for_save(
    source_form_data,
    allow_empty_mapping=False,
    connection=None,
    destination_config=None,
    destination_schema=None,
):
    """
    Validate mandatory S3 fields before create/update save flow.
    Returns (is_valid, error_message).
    """
    if not isinstance(source_form_data, dict):
        return False, "Invalid S3 configuration payload."

    required_fields = {
        "s3_bucket": source_form_data.get("s3_bucket"),
        "aws_access_key_id": source_form_data.get("aws_access_key_id"),
        "aws_secret_access_key": source_form_data.get("aws_secret_access_key"),
        "file_type": source_form_data.get("file_type"),
    }
    missing = []
    for k, v in required_fields.items():
        if v is None or not str(v).strip():
            missing.append(k)
    if missing:
        return False, f"Missing required S3 fields: {', '.join(missing)}"

    file_mapping_mode = (
        source_form_data.get("file_mapping_mode")
        or source_form_data.get("file_mapping_method")
        or "single_table_per_file"
    )
    single_map = source_form_data.get("single_file_table_mapping") or {}
    if file_mapping_mode == "single_table_per_file":
        if allow_empty_mapping and (not isinstance(single_map, dict) or not single_map):
            return True, None
        if not isinstance(single_map, dict) or not single_map:
            return False, "S3 mapping is required. Configure at least one file-to-table mapping."
        invalid_entries = [k for k, v in single_map.items() if not str(k).strip() or not str(v).strip()]
        if invalid_entries:
            return False, "S3 mapping has empty file/table names. Please configure valid mappings."

        # Prevent mapping multiple files to the same target table in single-file mode.
        normalized_table_to_file = {}
        duplicate_table_names = set()
        for raw_file_key, raw_table_name in single_map.items():
            file_key = str(raw_file_key).strip()
            table_name = str(raw_table_name).strip()
            if not file_key or not table_name:
                continue
            table_upper = table_name.upper()
            existing_file_for_table = normalized_table_to_file.get(table_upper)
            if existing_file_for_table and existing_file_for_table != file_key:
                duplicate_table_names.add(table_name)
            else:
                normalized_table_to_file[table_upper] = file_key

        if duplicate_table_names:
            duplicates_csv = ", ".join(sorted(duplicate_table_names))
            return (
                False,
                f"Duplicate table names are not allowed in single-file mapping: {duplicates_csv}. "
                "Each file must map to a unique table name."
            )

        # Pre-save guard: custom PK mode must provide PKs for mapped tables.
        incoming_load_method = str(source_form_data.get("load_method") or "upsert_file_row").strip()
        incoming_custom_pk_map = parse_s3_custom_pk_mapping(source_form_data.get("custom_primary_key"))
        incoming_custom_pk_upper = {
            str(table_name).strip().upper(): [str(col).strip().upper() for col in (pk_cols or []) if str(col).strip()]
            for table_name, pk_cols in incoming_custom_pk_map.items()
            if str(table_name).strip()
        }
        logger.info(
            "[S3][SAVE_VALIDATION] PK pre-check(single): load_method=%s, mapped_tables=%s, incoming_custom_pk_tables=%s",
            incoming_load_method,
            sorted(normalized_table_to_file.keys()),
            sorted(incoming_custom_pk_upper.keys()),
        )
        if incoming_load_method == "upsert_custom_key":
            if not incoming_custom_pk_upper:
                logger.warning(
                    "[S3][SAVE_VALIDATION] ❌ custom_primary_key missing/empty for upsert_custom_key"
                )
                return (
                    False,
                    "custom_primary_key is required when load_method is 'upsert_custom_key'."
                )
            missing_custom_pk_tables = [
                table_upper
                for table_upper in normalized_table_to_file.keys()
                if not incoming_custom_pk_upper.get(table_upper)
            ]
            if missing_custom_pk_tables:
                logger.warning(
                    "[S3][SAVE_VALIDATION] ❌ Missing custom PK for mapped table(s): %s",
                    sorted(set(missing_custom_pk_tables)),
                )
                return (
                    False,
                    "Custom primary key is required for mapped table(s): "
                    + ", ".join(sorted(set(missing_custom_pk_tables)))
                    + "."
                )

        # For existing connections, don't allow reusing an already-loaded table name
        # with a different file mapping. Keep existing loaded tables unchanged.
        if connection and getattr(connection, "connection_id", None):
            def _normalize_pk_list(pk_value):
                values = []
                if isinstance(pk_value, list):
                    values = [str(col).strip().upper() for col in pk_value if str(col).strip()]
                elif isinstance(pk_value, str):
                    try:
                        parsed = json.loads(pk_value)
                        if isinstance(parsed, list):
                            values = [str(col).strip().upper() for col in parsed if str(col).strip()]
                    except Exception:
                        values = []
                return sorted(set(values))

            existing_table_to_file_from_mapping = {}
            try:
                existing_s3_mapping = connection.source_file_mapping
                existing_mode = (existing_s3_mapping.file_mapping_mode or "single_table_per_file").strip()
                existing_single_map = (
                    existing_s3_mapping.single_file_table_mapping
                    if isinstance(existing_s3_mapping.single_file_table_mapping, dict)
                    else {}
                )
                if existing_mode == "single_table_per_file":
                    for existing_file_key, existing_table_name in existing_single_map.items():
                        table_name = str(existing_table_name).strip()
                        file_key = str(existing_file_key).strip()
                        if not table_name or not file_key:
                            continue
                        table_upper = table_name.upper()
                        if table_upper not in existing_table_to_file_from_mapping:
                            existing_table_to_file_from_mapping[table_upper] = file_key
            except SourceFileMapping.DoesNotExist:
                pass
            
            connection_id = getattr(connection, "connection_id", None)

            existing_table_rows = SourceTableSelection.objects.filter(
                connection_id=connection_id
            ).values_list("table", "folder_path", "primary_keys", "last_synced")

            existing_table_to_file = {}
            existing_table_to_pk = {}
            existing_migrated_tables = set()
            locked_file_to_table = {}
            locked_basename_to_table = {}
            locked_basename_counts = {}
            for raw_table_name, raw_folder_path, raw_primary_keys, raw_last_synced in existing_table_rows:
                table_name = str(raw_table_name).strip()
                folder_path = str(raw_folder_path or "").strip()
                if not table_name or not folder_path:
                    continue
                table_upper = table_name.upper()
                if table_upper not in existing_table_to_file:
                    existing_table_to_file[table_upper] = folder_path
                if table_upper not in existing_table_to_pk:
                    existing_table_to_pk[table_upper] = _normalize_pk_list(raw_primary_keys)
                if str(raw_last_synced or "").strip():
                    existing_migrated_tables.add(table_upper)
                    locked_file_to_table[folder_path] = table_upper
                    base_name = folder_path.split("/")[-1].strip()
                    if base_name:
                        locked_basename_counts[base_name] = locked_basename_counts.get(base_name, 0) + 1
                        if base_name not in locked_basename_to_table:
                            locked_basename_to_table[base_name] = table_upper

            # Prefer explicit S3 mapping as source-of-truth when available.
            for table_upper, file_key in existing_table_to_file_from_mapping.items():
                existing_table_to_file[table_upper] = file_key
            
            existing_src_data = (
                ensure_config_is_dict(connection.src_config.data, "source_config")
                if connection and connection.src_config
                else {}
            )
            incoming_tables = list(normalized_table_to_file.keys())
            incoming_file_mapping_mode = (
                source_form_data.get("file_mapping_method")
                or source_form_data.get("file_mapping_mode")
                or "single_table_per_file"
            )
            incoming_mode = (incoming_file_mapping_mode or "single_table_per_file").strip()
            existing_load_method = str(existing_src_data.get("load_method") or "").strip()
            incoming_load_method = str(source_form_data.get("load_method") or "").strip()
            load_method_changed = (
                bool(existing_load_method)
                and bool(incoming_load_method)
                and existing_load_method != incoming_load_method
            )

            # Guard: already-migrated file must keep its locked table name.
            # This backend check is mandatory even if frontend lock is bypassed.
            existing_sf_tables = None
            try:
                if destination_config and str(getattr(destination_config.dst, "name", "")).strip() == "Snowflake":
                    target_schema = str(getattr(connection, "dst_schema", "") or "").strip()
                    if target_schema:
                        existing_sf_tables = fetch_existing_snowflake_tables(
                            destination_config=destination_config,
                            destination_schema=target_schema,
                        )
                        logger.info(
                            "[S3][SAVE_VALIDATION] Snowflake existing-table check: %s, schema='%s', tables=%s",
                            "ok" if existing_sf_tables is not None else "failed",
                            target_schema,
                            len(existing_sf_tables) if existing_sf_tables is not None else 0,
                        )
            except Exception:
                existing_sf_tables = None
            locked_rename_conflicts = []
            for table_upper, incoming_file_key in normalized_table_to_file.items():
                incoming_file_key = str(incoming_file_key).strip()
                if not incoming_file_key:
                    continue
                locked_table = locked_file_to_table.get(incoming_file_key)
                if not locked_table and "/" not in incoming_file_key:
                    base_name = incoming_file_key.split("/")[-1].strip()
                    if base_name and locked_basename_counts.get(base_name, 0) == 1:
                        locked_table = locked_basename_to_table.get(base_name)
                if locked_table and locked_table != table_upper:
                    if existing_sf_tables is not None and locked_table not in existing_sf_tables:
                        continue
                    locked_rename_conflicts.append(
                        (incoming_file_key, locked_table, table_upper)
                    )

            if locked_rename_conflicts:
                conflict_lines = [
                    f"{file_key}: expected '{locked_table}', got '{incoming_table}'"
                    for file_key, locked_table, incoming_table in locked_rename_conflicts
                ]
                return (
                    False,
                    "Already migrated file(s) cannot be remapped to a different table. "
                    + " ; ".join(conflict_lines)
                )

            remap_conflicts = []
            for table_upper, incoming_file_key in normalized_table_to_file.items():
                existing_file_key = existing_table_to_file.get(table_upper)
                if existing_file_key and existing_file_key != incoming_file_key:
                    if existing_sf_tables is not None and table_upper not in existing_sf_tables:
                        continue
                    remap_conflicts.append(table_upper)

            if remap_conflicts:
                conflicts_csv = ", ".join(sorted(set(remap_conflicts)))
                return (
                    False,
                    f"Table name(s) already exist in schema and cannot be remapped to different files: {conflicts_csv}. "
                    "Keep existing loaded tables as-is or use new table names."
                )

            # PK strategy must stay consistent for already loaded tables.
            incoming_custom_pk_upper = {
                str(table_name).strip().upper(): _normalize_pk_list(pk_cols)
                for table_name, pk_cols in incoming_custom_pk_map.items()
                if str(table_name).strip()
            }
            existing_upper = set(existing_table_to_file.keys())
            logger.info(
                "[S3][SAVE_VALIDATION] PK lock scope(single): existing_mapped_tables=%s, migrated_tables=%s",
                sorted(existing_upper),
                sorted(existing_migrated_tables),
            )
            pk_conflicts = []
            for table_upper in normalized_table_to_file.keys():
                # Enforce PK immutability only for already migrated tables.
                if table_upper not in existing_migrated_tables:
                    continue
                if load_method_changed:
                    continue
                if existing_sf_tables is not None and table_upper not in existing_sf_tables:
                    continue
                existing_pk = existing_table_to_pk.get(table_upper)
                if existing_pk is None:
                    continue
                if incoming_load_method == "upsert_custom_key":
                    expected_pk = incoming_custom_pk_upper.get(table_upper, [])
                elif incoming_load_method == "append_file_modified":
                    expected_pk = ["_FILE", "_MODIFIED", "_ROW"]
                else:
                    expected_pk = ["_FILE", "_ROW"]
                logger.info(
                    "[S3][SAVE_VALIDATION] PK compare(single): table=%s, existing_pk=%s, expected_pk=%s",
                    table_upper,
                    existing_pk,
                    expected_pk,
                )
                if sorted(set(expected_pk)) != sorted(set(existing_pk)):
                    pk_conflicts.append(table_upper)

            if pk_conflicts:
                logger.warning(
                    "[S3][SAVE_VALIDATION] ❌ PK conflicts for migrated tables only: %s",
                    sorted(set(pk_conflicts)),
                )
                return (
                    False,
                    "Existing migrated table PK must remain same as source table selection. "
                    "PK mismatch for: "
                    + ", ".join(sorted(set(pk_conflicts)))
                    + "."
                )

            # If table no longer exists in Snowflake, clear last_synced so next run is full load.
            if (
                incoming_mode == "single_table_per_file"
                and existing_sf_tables is not None
            ):
                for table_name in incoming_tables:
                    table_upper = str(table_name).strip().upper()
                    if not table_upper:
                        continue
                    if table_upper in existing_migrated_tables and table_upper not in existing_sf_tables:
                        SourceTableSelection.objects.filter(
                            connection_id=connection_id,
                            table__iexact=table_name,
                        ).update(last_synced=None, status=None, selected=False)
                        logger.info(
                            "[S3][SAVE_VALIDATION] Cleared last_synced for '%s' (table missing in Snowflake; mode=%s; force full load)",
                            table_upper,
                            incoming_mode,
                        )

        # For Snowflake destination, also block new mappings that reuse table names
        # already present physically in destination schema.
        if destination_config and str(getattr(destination_config.dst, "name", "")).strip() == "Snowflake":
            target_schema = str(destination_schema or "").strip()
            if target_schema:
                is_existing_connection = bool(connection and getattr(connection, "connection_id", None))
                if not is_existing_connection:
                    logger.info(
                        "[S3][SAVE_VALIDATION] New connection flow: attempting read-only Snowflake existing-table check for schema '%s'",
                        target_schema,
                    )
                logger.info(
                    "[S3][SAVE_VALIDATION] Checking existing Snowflake tables in schema '%s' for mapping conflicts...",
                    target_schema,
                )
                try:
                    existing_sf_tables = fetch_existing_snowflake_tables(
                        destination_config=destination_config,
                        destination_schema=target_schema,
                    )
                    logger.info(
                        "[S3][SAVE_VALIDATION] Found %s table(s) in destination Snowflake schema '%s'",
                        len(existing_sf_tables),
                        target_schema,
                    )
                except Exception as sf_check_error:
                    if is_existing_connection:
                        logger.warning(
                            "[S3][SAVE_VALIDATION] Snowflake existing-table check failed: %s",
                            sf_check_error,
                        )
                        return (
                            False,
                            f"Unable to validate existing tables in destination Snowflake schema '{target_schema}': "
                            f"{sf_check_error}"
                        )
                    logger.warning(
                        "[S3][SAVE_VALIDATION] Snowflake existing-table check unavailable in creation flow: %s. "
                        "Continuing; destination authorization will validate schema next.",
                        sf_check_error,
                    )
                    return True, None

                allowed_existing_tables = set()
                if connection and getattr(connection, "connection_id", None):
                    # Keep already-loaded tables for this connection unchanged.
                    allowed_existing_tables = set(existing_table_to_file.keys())

                incoming_table_names = set(normalized_table_to_file.keys())
                sf_conflicts = sorted(
                    (incoming_table_names - allowed_existing_tables) & existing_sf_tables
                )
                if sf_conflicts:
                    conflict_csv = ", ".join(sf_conflicts)
                    logger.warning(
                        "[S3][SAVE_VALIDATION] 🚫 Snowflake schema conflict for mapped table(s): %s",
                        conflict_csv,
                    )
                    return (
                        False,
                        f"Table name(s) already exist in destination Snowflake schema '{target_schema}': {conflict_csv}. "
                        "Use different table names, or keep existing loaded mappings unchanged."
                    )
                logger.info("[S3][SAVE_VALIDATION] ✅ No Snowflake schema table-name conflicts found.")
    elif file_mapping_mode == "multi_files_single_table":
        if allow_empty_mapping:
            return True, None
        # multi_files_single_table must still resolve to a single target table name.
        configured_multi_table_name = sanitize_identifier(
            str(source_form_data.get("multi_files_table_name") or "").strip()
        )
        if not configured_multi_table_name:
            return (
                False,
                "multi_files_table_name is required for multi-file mode."
            )
        incoming_multi_tables = {configured_multi_table_name.upper()}
        if len(incoming_multi_tables) > 1:
            return (
                False,
                f"Multi-file mode supports exactly one target table. Found: {', '.join(sorted(incoming_multi_tables))}."
            )

        # Pre-save guard: custom PK mode must provide PK for target table.
        incoming_load_method = str(source_form_data.get("load_method") or "upsert_file_row").strip()
        if incoming_load_method == "upsert_custom_key":
            incoming_custom_pk_map = parse_s3_custom_pk_mapping(source_form_data.get("custom_primary_key"))
            incoming_custom_pk_upper = {
                str(table_name).strip().upper(): [str(col).strip().upper() for col in (pk_cols or []) if str(col).strip()]
                for table_name, pk_cols in incoming_custom_pk_map.items()
                if str(table_name).strip()
            }
            target_table_upper = next(iter(incoming_multi_tables)) if incoming_multi_tables else None
            logger.info(
                "[S3][SAVE_VALIDATION] PK pre-check(multi): load_method=%s, target_table=%s, incoming_custom_pk_tables=%s",
                incoming_load_method,
                target_table_upper,
                sorted(incoming_custom_pk_upper.keys()),
            )
            if not target_table_upper or not incoming_custom_pk_upper.get(target_table_upper):
                logger.warning(
                    "[S3][SAVE_VALIDATION] ❌ Missing custom PK for multi_files_table_name '%s'",
                    target_table_upper,
                )
                return (
                    False,
                    "custom_primary_key is required for multi_files_table_name when load_method is 'upsert_custom_key'."
                )

        # For existing connections, block remapping an already-loaded multi-file table name
        # to a different file set. Keep already loaded table mappings unchanged.
        existing_loaded_tables_upper = set()
        existing_migrated_tables_upper = set()
        if connection and getattr(connection, "connection_id", None):
            existing_table_rows = SourceTableSelection.objects.filter(
                connection_id=connection.connection_id
            ).values_list("table", "last_synced")
            for raw_table_name, raw_last_synced in existing_table_rows:
                table_upper = str(raw_table_name).strip().upper()
                if not table_upper:
                    continue
                existing_loaded_tables_upper.add(table_upper)
                if str(raw_last_synced or "").strip():
                    existing_migrated_tables_upper.add(table_upper)

        # For Snowflake destination, block creating/reusing target table names that already
        # physically exist in schema unless they are already loaded for this same connection.
        if destination_config and str(getattr(destination_config.dst, "name", "")).strip() == "Snowflake":
            target_schema = str(destination_schema or "").strip()
            if target_schema and incoming_multi_tables:
                is_existing_connection = bool(connection and getattr(connection, "connection_id", None))
                try:
                    existing_sf_tables = fetch_existing_snowflake_tables(
                        destination_config=destination_config,
                        destination_schema=target_schema,
                    )
                except Exception as sf_check_error:
                    if is_existing_connection:
                        return (
                            False,
                            f"Unable to validate existing tables in destination Snowflake schema '{target_schema}': "
                            f"{sf_check_error}"
                        )
                    return True, None

                # If table no longer exists in Snowflake, clear last_synced so next run is full load.
                target_table_upper = next(iter(incoming_multi_tables)) if incoming_multi_tables else None
                if (
                    target_table_upper
                    and target_table_upper in existing_migrated_tables_upper
                    and target_table_upper not in existing_sf_tables
                ):
                    SourceTableSelection.objects.filter(
                        connection_id=connection.connection_id,
                        table__iexact=target_table_upper,
                    ).update(last_synced=None, status=None, selected=False)
                    logger.info(
                        "[S3][SAVE_VALIDATION] Cleared last_synced for '%s' (table missing in Snowflake; mode=multi_files_single_table; force full load)",
                        target_table_upper,
                    )

                allowed_existing_tables = existing_loaded_tables_upper if is_existing_connection else set()
                sf_conflicts = sorted((incoming_multi_tables - allowed_existing_tables) & existing_sf_tables)
                if sf_conflicts:
                    return (
                        False,
                        f"Table name(s) already exist in destination Snowflake schema '{target_schema}': {', '.join(sf_conflicts)}. "
                        "Use a different multi_files_table_name."
                    )
    else:
        return False, f"Unsupported S3 file_mapping_mode: {file_mapping_mode}"

    return True, None


def validate_sftp_form_for_save(
    source_form_data,
    allow_empty_mapping=False,
    connection=None,
    destination_config=None,
    destination_schema=None,
):
    """
    Validate mandatory SFTP fields before create/update save flow.
    Returns (is_valid, error_message).
    """
    if not isinstance(source_form_data, dict):
        return False, "Invalid SFTP configuration payload."

    required_fields = {
        "sftp_host": source_form_data.get("sftp_host"),
        "sftp_username": source_form_data.get("sftp_username"),
        "file_type": source_form_data.get("file_type"),
    }
    missing = []
    for k, v in required_fields.items():
        if v is None or not str(v).strip():
            missing.append(k)
    if missing:
        return False, f"Missing required SFTP fields: {', '.join(missing)}"

    file_mapping_mode = (
        source_form_data.get("file_mapping_mode")
        or source_form_data.get("file_mapping_method")
        or "single_table_per_file"
    )
    single_map = source_form_data.get("single_file_table_mapping") or {}
    if file_mapping_mode == "single_table_per_file":
        if allow_empty_mapping and (not isinstance(single_map, dict) or not single_map):
            return True, None
        if not isinstance(single_map, dict) or not single_map:
            return False, "SFTP mapping is required. Configure at least one file-to-table mapping."
        invalid_entries = [k for k, v in single_map.items() if not str(k).strip() or not str(v).strip()]
        if invalid_entries:
            return False, "SFTP mapping has empty file/table names. Please configure valid mappings."

        # Prevent mapping multiple files to the same target table in single-file mode.
        normalized_table_to_file = {}
        duplicate_table_names = set()
        for raw_file_key, raw_table_name in single_map.items():
            file_key = str(raw_file_key).strip()
            table_name = str(raw_table_name).strip()
            if not file_key or not table_name:
                continue
            table_upper = table_name.upper()
            existing_file_for_table = normalized_table_to_file.get(table_upper)
            if existing_file_for_table and existing_file_for_table != file_key:
                duplicate_table_names.add(table_name)
            else:
                normalized_table_to_file[table_upper] = file_key

        if duplicate_table_names:
            duplicates_csv = ", ".join(sorted(duplicate_table_names))
            return (
                False,
                f"Duplicate table names are not allowed in single-file mapping: {duplicates_csv}. "
                "Each file must map to a unique table name."
            )

        # Pre-save guard: custom PK mode must provide PKs for mapped tables.
        incoming_load_method = str(source_form_data.get("load_method") or "upsert_file_row").strip()
        incoming_custom_pk_map = parse_s3_custom_pk_mapping(source_form_data.get("custom_primary_key"))
        incoming_custom_pk_upper = {
            str(table_name).strip().upper(): [str(col).strip().upper() for col in (pk_cols or []) if str(col).strip()]
            for table_name, pk_cols in incoming_custom_pk_map.items()
            if str(table_name).strip()
        }
        logger.info(
            "[SFTP][SAVE_VALIDATION] PK pre-check(single): load_method=%s, mapped_tables=%s, incoming_custom_pk_tables=%s",
            incoming_load_method,
            sorted(normalized_table_to_file.keys()),
            sorted(incoming_custom_pk_upper.keys()),
        )
        if incoming_load_method == "upsert_custom_key":
            if not incoming_custom_pk_upper:
                logger.warning(
                    "[SFTP][SAVE_VALIDATION] âŒ custom_primary_key missing/empty for upsert_custom_key"
                )
                return (
                    False,
                    "custom_primary_key is required when load_method is 'upsert_custom_key'."
                )
            missing_custom_pk_tables = [
                table_upper
                for table_upper in normalized_table_to_file.keys()
                if not incoming_custom_pk_upper.get(table_upper)
            ]
            if missing_custom_pk_tables:
                logger.warning(
                    "[SFTP][SAVE_VALIDATION] âŒ Missing custom PK for mapped table(s): %s",
                    sorted(set(missing_custom_pk_tables)),
                )
                return (
                    False,
                    "Custom primary key is required for mapped table(s): "
                    + ", ".join(sorted(set(missing_custom_pk_tables)))
                    + "."
                )

        # For existing connections, don't allow reusing an already-loaded table name
        # with a different file mapping. Keep existing loaded tables unchanged.
        if connection and getattr(connection, "connection_id", None):
            def _normalize_pk_list(pk_value):
                values = []
                if isinstance(pk_value, list):
                    values = [str(col).strip().upper() for col in pk_value if str(col).strip()]
                elif isinstance(pk_value, str):
                    try:
                        parsed = json.loads(pk_value)
                        if isinstance(parsed, list):
                            values = [str(col).strip().upper() for col in parsed if str(col).strip()]
                    except Exception:
                        values = []
                return sorted(set(values))

            existing_table_to_file_from_mapping = {}
            try:
                existing_sftp_mapping = connection.source_file_mapping
                existing_mode = (existing_sftp_mapping.file_mapping_mode or "single_table_per_file").strip()
                existing_single_map = (
                    existing_sftp_mapping.single_file_table_mapping
                    if isinstance(existing_sftp_mapping.single_file_table_mapping, dict)
                    else {}
                )
                if existing_mode == "single_table_per_file":
                    for existing_file_key, existing_table_name in existing_single_map.items():
                        table_name = str(existing_table_name).strip()
                        file_key = str(existing_file_key).strip()
                        if not table_name or not file_key:
                            continue
                        table_upper = table_name.upper()
                        if table_upper not in existing_table_to_file_from_mapping:
                            existing_table_to_file_from_mapping[table_upper] = file_key
            except SourceFileMapping.DoesNotExist:
                pass
            
            connection_id = getattr(connection, "connection_id", None)

            existing_table_rows = SourceTableSelection.objects.filter(
                connection_id=connection_id
            ).values_list("table", "folder_path", "primary_keys", "last_synced")

            existing_table_to_file = {}
            existing_table_to_pk = {}
            existing_migrated_tables = set()
            locked_file_to_table = {}
            locked_basename_to_table = {}
            locked_basename_counts = {}
            for raw_table_name, raw_folder_path, raw_primary_keys, raw_last_synced in existing_table_rows:
                table_name = str(raw_table_name).strip()
                folder_path = str(raw_folder_path or "").strip()
                if not table_name or not folder_path:
                    continue
                table_upper = table_name.upper()
                if table_upper not in existing_table_to_file:
                    existing_table_to_file[table_upper] = folder_path
                if table_upper not in existing_table_to_pk:
                    existing_table_to_pk[table_upper] = _normalize_pk_list(raw_primary_keys)
                if str(raw_last_synced or "").strip():
                    existing_migrated_tables.add(table_upper)
                    locked_file_to_table[folder_path] = table_upper
                    base_name = folder_path.split("/")[-1].strip()
                    if base_name:
                        locked_basename_counts[base_name] = locked_basename_counts.get(base_name, 0) + 1
                        if base_name not in locked_basename_to_table:
                            locked_basename_to_table[base_name] = table_upper

            # Prefer explicit SFTP mapping as source-of-truth when available.
            for table_upper, file_key in existing_table_to_file_from_mapping.items():
                existing_table_to_file[table_upper] = file_key
            
            existing_src_data = (
                ensure_config_is_dict(connection.src_config.data, "source_config")
                if connection and connection.src_config
                else {}
            )
            incoming_tables = list(normalized_table_to_file.keys())
            incoming_file_mapping_mode = (
                source_form_data.get("file_mapping_method")
                or source_form_data.get("file_mapping_mode")
                or "single_table_per_file"
            )
            incoming_mode = (incoming_file_mapping_mode or "single_table_per_file").strip()
            existing_load_method = str(existing_src_data.get("load_method") or "").strip()
            incoming_load_method = str(source_form_data.get("load_method") or "").strip()
            load_method_changed = (
                bool(existing_load_method)
                and bool(incoming_load_method)
                and existing_load_method != incoming_load_method
            )

            # Guard: already-migrated file must keep its locked table name.
            existing_sf_tables = None
            try:
                if destination_config and str(getattr(destination_config.dst, "name", "")).strip() == "Snowflake":
                    target_schema = str(getattr(connection, "dst_schema", "") or "").strip()
                    if target_schema:
                        existing_sf_tables = fetch_existing_snowflake_tables(
                            destination_config=destination_config,
                            destination_schema=target_schema,
                        )
                        logger.info(
                            "[SFTP][SAVE_VALIDATION] Snowflake existing-table check: %s, schema='%s', tables=%s",
                            "ok" if existing_sf_tables is not None else "failed",
                            target_schema,
                            len(existing_sf_tables) if existing_sf_tables is not None else 0,
                        )
            except Exception:
                existing_sf_tables = None
            locked_rename_conflicts = []
            for table_upper, incoming_file_key in normalized_table_to_file.items():
                incoming_file_key = str(incoming_file_key).strip()
                if not incoming_file_key:
                    continue
                locked_table = locked_file_to_table.get(incoming_file_key)
                if not locked_table and "/" not in incoming_file_key:
                    base_name = incoming_file_key.split("/")[-1].strip()
                    if base_name and locked_basename_counts.get(base_name, 0) == 1:
                        locked_table = locked_basename_to_table.get(base_name)
                if locked_table and locked_table != table_upper:
                    if existing_sf_tables is not None and locked_table not in existing_sf_tables:
                        continue
                    locked_rename_conflicts.append(
                        (incoming_file_key, locked_table, table_upper)
                    )

            if locked_rename_conflicts:
                conflict_lines = [
                    f"{file_key}: expected '{locked_table}', got '{incoming_table}'"
                    for file_key, locked_table, incoming_table in locked_rename_conflicts
                ]
                return (
                    False,
                    "Already migrated file(s) cannot be remapped to a different table. "
                    + " ; ".join(conflict_lines)
                )

            remap_conflicts = []
            for table_upper, incoming_file_key in normalized_table_to_file.items():
                existing_file_key = existing_table_to_file.get(table_upper)
                if existing_file_key and existing_file_key != incoming_file_key:
                    if existing_sf_tables is not None and table_upper not in existing_sf_tables:
                        continue
                    remap_conflicts.append(table_upper)

            if remap_conflicts:
                conflicts_csv = ", ".join(sorted(set(remap_conflicts)))
                return (
                    False,
                    f"Table name(s) already exist in schema and cannot be remapped to different files: {conflicts_csv}. "
                    "Keep existing loaded tables as-is or use new table names."
                )

            # PK strategy must stay consistent for already loaded tables.
            incoming_custom_pk_upper = {
                str(table_name).strip().upper(): _normalize_pk_list(pk_cols)
                for table_name, pk_cols in incoming_custom_pk_map.items()
                if str(table_name).strip()
            }
            existing_upper = set(existing_table_to_file.keys())
            logger.info(
                "[SFTP][SAVE_VALIDATION] PK lock scope(single): existing_mapped_tables=%s, migrated_tables=%s",
                sorted(existing_upper),
                sorted(existing_migrated_tables),
            )
            pk_conflicts = []
            for table_upper in normalized_table_to_file.keys():
                if table_upper not in existing_migrated_tables:
                    continue
                if load_method_changed:
                    continue
                if existing_sf_tables is not None and table_upper not in existing_sf_tables:
                    continue
                existing_pk = existing_table_to_pk.get(table_upper)
                if existing_pk is None:
                    continue
                if incoming_load_method == "upsert_custom_key":
                    expected_pk = incoming_custom_pk_upper.get(table_upper, [])
                elif incoming_load_method == "append_file_modified":
                    expected_pk = ["_FILE", "_MODIFIED", "_ROW"]
                else:
                    expected_pk = ["_FILE", "_ROW"]
                logger.info(
                    "[SFTP][SAVE_VALIDATION] PK compare(single): table=%s, existing_pk=%s, expected_pk=%s",
                    table_upper,
                    existing_pk,
                    expected_pk,
                )
                if sorted(set(expected_pk)) != sorted(set(existing_pk)):
                    pk_conflicts.append(table_upper)

            if pk_conflicts:
                logger.warning(
                    "[SFTP][SAVE_VALIDATION] âŒ PK conflicts for migrated tables only: %s",
                    sorted(set(pk_conflicts)),
                )
                return (
                    False,
                    "Existing migrated table PK must remain same as source table selection. "
                    "PK mismatch for: "
                    + ", ".join(sorted(set(pk_conflicts)))
                    + "."
                )

            # If table no longer exists in Snowflake, clear last_synced so next run is full load.
            if (
                incoming_mode == "single_table_per_file"
                and existing_sf_tables is not None
            ):
                for table_name in incoming_tables:
                    table_upper = str(table_name).strip().upper()
                    if not table_upper:
                        continue
                    if table_upper in existing_migrated_tables and table_upper not in existing_sf_tables:
                        SourceTableSelection.objects.filter(
                            connection_id=connection_id,
                            table__iexact=table_name,
                        ).update(last_synced=None, status=None, selected=False)
                        logger.info(
                            "[SFTP][SAVE_VALIDATION] Cleared last_synced for '%s' (table missing in Snowflake; mode=%s; force full load)",
                            table_upper,
                            incoming_mode,
                        )

        # For Snowflake destination, also block new mappings that reuse table names
        # already present physically in destination schema.
        if destination_config and str(getattr(destination_config.dst, "name", "")).strip() == "Snowflake":
            target_schema = str(destination_schema or "").strip()
            if target_schema:
                is_existing_connection = bool(connection and getattr(connection, "connection_id", None))
                if not is_existing_connection:
                    logger.info(
                        "[SFTP][SAVE_VALIDATION] New connection flow: attempting read-only Snowflake existing-table check for schema '%s'",
                        target_schema,
                    )
                logger.info(
                    "[SFTP][SAVE_VALIDATION] Checking existing Snowflake tables in schema '%s' for mapping conflicts...",
                    target_schema,
                )
                try:
                    existing_sf_tables = fetch_existing_snowflake_tables(
                        destination_config=destination_config,
                        destination_schema=target_schema,
                    )
                    logger.info(
                        "[SFTP][SAVE_VALIDATION] Found %s table(s) in destination Snowflake schema '%s'",
                        len(existing_sf_tables),
                        target_schema,
                    )
                except Exception as sf_check_error:
                    if is_existing_connection:
                        logger.warning(
                            "[SFTP][SAVE_VALIDATION] Snowflake existing-table check failed: %s",
                            sf_check_error,
                        )
                        return (
                            False,
                            f"Unable to validate existing tables in destination Snowflake schema '{target_schema}': "
                            f"{sf_check_error}"
                        )
                    logger.warning(
                        "[SFTP][SAVE_VALIDATION] Snowflake existing-table check unavailable in creation flow: %s. "
                        "Continuing; destination authorization will validate schema next.",
                        sf_check_error,
                    )
                    return True, None

                allowed_existing_tables = set()
                if connection and getattr(connection, "connection_id", None):
                    allowed_existing_tables = set(existing_table_to_file.keys())

                incoming_table_names = set(normalized_table_to_file.keys())
                sf_conflicts = sorted(
                    (incoming_table_names - allowed_existing_tables) & existing_sf_tables
                )
                if sf_conflicts:
                    conflict_csv = ", ".join(sf_conflicts)
                    logger.warning(
                        "[SFTP][SAVE_VALIDATION] ðŸš« Snowflake schema conflict for mapped table(s): %s",
                        conflict_csv,
                    )
                    return (
                        False,
                        f"Table name(s) already exist in destination Snowflake schema '{target_schema}': {conflict_csv}. "
                        "Use different table names, or keep existing loaded mappings unchanged."
                    )
                logger.info("[SFTP][SAVE_VALIDATION] âœ… No Snowflake schema table-name conflicts found.")
    elif file_mapping_mode == "multi_files_single_table":
        if allow_empty_mapping:
            return True, None
        configured_multi_table_name = sanitize_identifier(
            str(source_form_data.get("multi_files_table_name") or "").strip()
        )
        if not configured_multi_table_name:
            return (
                False,
                "multi_files_table_name is required for multi-file mode."
            )
        incoming_multi_tables = {configured_multi_table_name.upper()}
        if len(incoming_multi_tables) > 1:
            return (
                False,
                f"Multi-file mode supports exactly one target table. Found: {', '.join(sorted(incoming_multi_tables))}."
            )

        # Pre-save guard: custom PK mode must provide PK for target table.
        incoming_load_method = str(source_form_data.get("load_method") or "upsert_file_row").strip()
        if incoming_load_method == "upsert_custom_key":
            incoming_custom_pk_map = parse_s3_custom_pk_mapping(source_form_data.get("custom_primary_key"))
            incoming_custom_pk_upper = {
                str(table_name).strip().upper(): [str(col).strip().upper() for col in (pk_cols or []) if str(col).strip()]
                for table_name, pk_cols in incoming_custom_pk_map.items()
                if str(table_name).strip()
            }
            target_table_upper = next(iter(incoming_multi_tables)) if incoming_multi_tables else None
            logger.info(
                "[SFTP][SAVE_VALIDATION] PK pre-check(multi): load_method=%s, target_table=%s, incoming_custom_pk_tables=%s",
                incoming_load_method,
                target_table_upper,
                sorted(incoming_custom_pk_upper.keys()),
            )
            if not target_table_upper or not incoming_custom_pk_upper.get(target_table_upper):
                logger.warning(
                    "[SFTP][SAVE_VALIDATION] âŒ Missing custom PK for multi_files_table_name '%s'",
                    target_table_upper,
                )
                return (
                    False,
                    "custom_primary_key is required for multi_files_table_name when load_method is 'upsert_custom_key'."
                )

        # For existing connections, block remapping an already-loaded multi-file table name
        # to a different file set. Keep already loaded table mappings unchanged.
        existing_loaded_tables_upper = set()
        existing_migrated_tables_upper = set()
        if connection and getattr(connection, "connection_id", None):
            existing_table_rows = SourceTableSelection.objects.filter(
                connection_id=connection.connection_id
            ).values_list("table", "last_synced")
            for raw_table_name, raw_last_synced in existing_table_rows:
                table_upper = str(raw_table_name).strip().upper()
                if not table_upper:
                    continue
                existing_loaded_tables_upper.add(table_upper)
                if str(raw_last_synced or "").strip():
                    existing_migrated_tables_upper.add(table_upper)

        # For Snowflake destination, block creating/reusing target table names that already
        # physically exist in schema unless they are already loaded for this same connection.
        if destination_config and str(getattr(destination_config.dst, "name", "")).strip() == "Snowflake":
            target_schema = str(destination_schema or "").strip()
            if target_schema and incoming_multi_tables:
                is_existing_connection = bool(connection and getattr(connection, "connection_id", None))
                try:
                    existing_sf_tables = fetch_existing_snowflake_tables(
                        destination_config=destination_config,
                        destination_schema=target_schema,
                    )
                except Exception as sf_check_error:
                    if is_existing_connection:
                        return (
                            False,
                            f"Unable to validate existing tables in destination Snowflake schema '{target_schema}': "
                            f"{sf_check_error}"
                        )
                    return True, None

                # If table no longer exists in Snowflake, clear last_synced so next run is full load.
                target_table_upper = next(iter(incoming_multi_tables)) if incoming_multi_tables else None
                if (
                    target_table_upper
                    and target_table_upper in existing_migrated_tables_upper
                    and target_table_upper not in existing_sf_tables
                ):
                    SourceTableSelection.objects.filter(
                        connection_id=connection.connection_id,
                        table__iexact=target_table_upper,
                    ).update(last_synced=None, status=None, selected=False)
                    logger.info(
                        "[SFTP][SAVE_VALIDATION] Cleared last_synced for '%s' (table missing in Snowflake; mode=multi_files_single_table; force full load)",
                        target_table_upper,
                    )

                allowed_existing_tables = existing_loaded_tables_upper if is_existing_connection else set()
                sf_conflicts = sorted((incoming_multi_tables - allowed_existing_tables) & existing_sf_tables)
                if sf_conflicts:
                    return (
                        False,
                        f"Table name(s) already exist in destination Snowflake schema '{target_schema}': {', '.join(sf_conflicts)}. "
                        "Use a different multi_files_table_name."
                    )
    else:
        return False, f"Unsupported SFTP file_mapping_mode: {file_mapping_mode}"

    return True, None


def validate_google_drive_form_for_save(
    source_form_data,
    allow_empty_mapping=False,
    connection=None,
    destination_config=None,
    destination_schema=None,
):
    """
    Validate mandatory Google Drive fields and reuse the shared file-mapping
    lock/unlock rules already implemented for SFTP.
    """
    if not isinstance(source_form_data, dict):
        return False, "Invalid Google Drive configuration payload."

    if not str(source_form_data.get("file_type") or "").strip():
        return False, "Missing required Google Drive fields: file_type"

    folder_id = str(source_form_data.get("folder_id") or "").strip()
    folder_name = str(source_form_data.get("folder_name") or "").strip()
    if not folder_id and not folder_name:
        return False, "Missing required Google Drive fields: folder_id or folder_name"

    validation_payload = dict(source_form_data)
    validation_payload["sftp_host"] = "googledrive"
    validation_payload["sftp_username"] = "googledrive"

    is_valid, error_message = validate_sftp_form_for_save(
        validation_payload,
        allow_empty_mapping=allow_empty_mapping,
        connection=connection,
        destination_config=destination_config,
        destination_schema=destination_schema,
    )
    if error_message:
        error_message = str(error_message).replace("SFTP", "Google Drive")
    return is_valid, error_message


def sftp_schema_format_options(config):
    """Forward parsing options consistently for preview and save validation."""
    names = (
        "delimiter", "quotechar", "escape_char", "skipheaderlines",
        "skip_footer_lines", "line_separator", "null_sequence",
        "tsv_delimiter", "tsv_quotechar", "tsv_escape_char",
        "tsv_skipheaderlines", "tsv_skip_footer_lines", "json_mode", "xml_mode",
    )
    return {name: config[name] for name in names if name in config}


def validate_sftp_runtime_access_and_mappings(source_form_data, cmp_id, user_id):
    """
    Validate SFTP credentials, mapped file existence, and multi-file schemas
    by calling FastAPI listing endpoint before save/update.
    Returns (is_valid, error_message, status_code).
    """
    if not isinstance(source_form_data, dict):
        return False, "Invalid SFTP configuration payload.", 400

    mapping_mode = (
        source_form_data.get("file_mapping_method")
        or source_form_data.get("file_mapping_mode")
        or "single_table_per_file"
    ).strip()
    single_map_for_validation = source_form_data.get("single_file_table_mapping") or {}
    if mapping_mode == "multi_files_single_table":
        single_map_for_validation = {}

    payload = {
        "connection_id": 0,
        "SFTP": {
            "sftp_host": source_form_data.get("sftp_host"),
            "sftp_port": source_form_data.get("sftp_port"),
            "sftp_username": source_form_data.get("sftp_username"),
            "sftp_password": source_form_data.get("sftp_password"),
            "sftp_private_key": source_form_data.get("sftp_private_key"),
            "sftp_passphrase": source_form_data.get("sftp_passphrase"),
            "root_folder": source_form_data.get("root_folder") or source_form_data.get("base_folder_path") or "",
            "base_folder_path": (source_form_data.get("base_folder_path") or "") if source_form_data.get("root_folder") else "",
            "authentication_type": source_form_data.get("authentication_type") or "password",
            "file_type": source_form_data.get("file_type"),
            "include_subfolders": parse_bool_like(source_form_data.get("include_subfolders"), default=False),
            "file_mapping_mode": mapping_mode,
            "single_file_table_mapping": single_map_for_validation,
            "multi_files_prefix": source_form_data.get("multi_files_prefix") or "",
            "multi_files_table_name": source_form_data.get("multi_files_table_name") or "",
        },
        "cmp_id": int(cmp_id or 0),
        "user_id": int(user_id or 0),
        "job_name": "sftp_pre_save_validation",
        "last_checked_date": None,
    }

    try:
        payload["SFTP"].update(sftp_schema_format_options(source_form_data))
        # Preview validates schemas without persisting tables for connection_id=0.
        endpoint = "SFTP-preview-pattern" if mapping_mode == "multi_files_single_table" else "SFTP-listing-files"
        api_url = f"http://{FASTAPI_DOMAIN}/{endpoint}"
        response = requests.post(
            api_url,
            data=json.dumps(payload),
            headers=_fastapi_headers(),
            verify=False,
            timeout=60,
        )
        if response.status_code != 200:
            detail = extract_api_error_message(response)
            return False, detail or f"SFTP validation failed with HTTP {response.status_code}.", response.status_code

        result = response.json()
        listed_tables = ((result or {}).get("result") or {}).get("tables") or []
        existing_file_keys = {str(t.get("file_key")).strip() for t in listed_tables if t.get("file_key")}
        existing_basenames = {k.split("/")[-1] for k in existing_file_keys}

        missing_mapped_files = []

        if mapping_mode == "single_table_per_file":
            single_map = single_map_for_validation
            for mapped_file_key in single_map.keys():
                fk = str(mapped_file_key).strip()
                if not fk:
                    continue
                if fk not in existing_file_keys and fk.split("/")[-1] not in existing_basenames:
                    missing_mapped_files.append(fk)

        if missing_mapped_files:
            sample = ", ".join(sorted(set(missing_mapped_files))[:5])
            return False, (
                f"Mapped file(s) not found in SFTP folder for selected file type: {sample}. "
                "Please verify mapped file paths and folder path."
            ), 400

        return True, None, 200
    except requests.RequestException as e:
        return False, f"Failed to validate SFTP files against backend service: {str(e)}", 502
    except Exception as e:
        return False, f"SFTP validation error: {str(e)}", 500


