def validate_adls_form_for_save(
    source_form_data,
    allow_empty_mapping=False,
    connection=None,
    destination_config=None,
    destination_schema=None,
):
    """
    Validate mandatory ADLS fields and reuse the shared file-mapping
    lock/unlock rules already implemented for SFTP.
    """
    if not isinstance(source_form_data, dict):
        return False, "Invalid ADLS configuration payload."

    required_fields = [
        "account_name",
        "container_name",
        "tenant_id",
        "client_id",
        "client_secret",
        "file_type",
    ]
    missing = [field for field in required_fields if not str(source_form_data.get(field) or "").strip()]
    if missing:
        return False, f"Missing required ADLS fields: {', '.join(missing)}"

    validation_payload = dict(source_form_data)
    validation_payload["sftp_host"] = "adls"
    validation_payload["sftp_username"] = "adls"
    validation_payload["root_folder"] = validation_payload.get("folder_name") or ""
    validation_payload["base_folder_path"] = ""

    is_valid, error_message = validate_sftp_form_for_save(
        validation_payload,
        allow_empty_mapping=allow_empty_mapping,
        connection=connection,
        destination_config=destination_config,
        destination_schema=destination_schema,
    )
    if error_message:
        error_message = str(error_message).replace("SFTP", "ADLS")
    return is_valid, error_message


