def fetch_existing_snowflake_tables(destination_config, destination_schema):
    """
    Fetch existing table names from destination Snowflake schema via FastAPI service.
    Uses the same Snowflake-listing-tables backend path as the rest of the system,
    instead of opening a direct Snowflake connection from Django views.
    """
    if not destination_config or str(getattr(destination_config.dst, "name", "")).strip() != "Snowflake":
        return set()

    schema_name = str(destination_schema or "").strip()
    if not schema_name:
        return set()

    config_data = ensure_config_is_dict(destination_config.data, "destination_config") if destination_config.data else {}
    database = str(config_data.get("database") or "").strip()
    user = str(config_data.get("user") or "").strip()
    account = str(config_data.get("account") or "").strip()
    if not database or not user or not account:
        raise ValueError("Snowflake destination config is missing required fields (account/user/database).")

    try:
        use_direct_library = str(
            os.environ.get("USE_DATASYNCHER_CONNECTION_LIBRARY_DIRECT", "")
        ).lower() in {"1", "true", "yes", "on"}
        if use_direct_library:
            from apps.elttool.services.snowflake_readonly_listing import (
                fetch_existing_tables_from_snowflake,
            )

            return fetch_existing_tables_from_snowflake(config_data, schema_name)

        # Listing API fetches tables from Snowflake['schema']; force it to target schema.
        snowflake_payload = dict(config_data)
        snowflake_payload["schema"] = schema_name

        payload = {
            "connection_id": int(getattr(destination_config, "dst_config_id", 0) or 0),
            "Snowflake": snowflake_payload,
            "job_name": "s3_pre_save_schema_conflict_check",
            "last_checked_date": None,
            "destination_schema": schema_name,
        }

        api_url = get_migration_api_url("Snowflake-listing-tables-readonly")
        response = requests.post(
            api_url,
            data=json.dumps(payload),
            headers=_fastapi_headers(),
            verify=False,
            timeout=60,
        )
        if response.status_code != 200:
            detail = extract_api_error_message(response)
            raise ValueError(detail or f"Snowflake listing API failed with HTTP {response.status_code}.")

        body = response.json() if response.content else {}
        existing_tables = body.get("existing_tables")
        if isinstance(existing_tables, list):
            return {str(table_name).strip().upper() for table_name in existing_tables if str(table_name).strip()}

        updated_tables = body.get("updated_tables") or {}
        if isinstance(updated_tables, dict):
            return {str(table_name).strip().upper() for table_name in updated_tables.keys() if str(table_name).strip()}
        return set()
    except Exception as e:
        raise ValueError(f"Failed to fetch existing tables from Snowflake schema '{schema_name}': {e}")


def fetch_snowflake_schema_state(destination_config, destination_schema):
    """
    Fetch schema existence and existing table names from destination Snowflake schema.
    Returns a dict with keys: schema_exists (bool), existing_tables (set of upper-case names).
    """
    if not destination_config or str(getattr(destination_config.dst, "name", "")).strip() != "Snowflake":
        return {"schema_exists": False, "existing_tables": set()}

    schema_name = str(destination_schema or "").strip()
    if not schema_name:
        return {"schema_exists": False, "existing_tables": set()}

    config_data = ensure_config_is_dict(destination_config.data, "destination_config") if destination_config.data else {}
    database = str(config_data.get("database") or "").strip()
    user = str(config_data.get("user") or "").strip()
    account = str(config_data.get("account") or "").strip()
    if not database or not user or not account:
        raise ValueError("Snowflake destination config is missing required fields (account/user/database).")

    try:
        snowflake_payload = dict(config_data)
        snowflake_payload["schema"] = schema_name

        payload = {
            "connection_id": int(getattr(destination_config, "dst_config_id", 0) or 0),
            "Snowflake": snowflake_payload,
            "job_name": "s3_edit_schema_state_check",
            "last_checked_date": None,
            "destination_schema": schema_name,
        }

        api_url = get_migration_api_url("Snowflake-listing-tables-readonly")
        response = requests.post(
            api_url,
            data=json.dumps(payload),
            headers=_fastapi_headers(),
            verify=False,
            timeout=60,
        )
        if response.status_code != 200:
            detail = extract_api_error_message(response)
            raise ValueError(detail or f"Snowflake listing API failed with HTTP {response.status_code}.")

        body = response.json() if response.content else {}
        schema_exists = body.get("schema_exists")
        if schema_exists is None:
            schema_exists = True

        existing_tables = body.get("existing_tables")
        if isinstance(existing_tables, list):
            return {
                "schema_exists": bool(schema_exists),
                "existing_tables": {str(table_name).strip().upper() for table_name in existing_tables if str(table_name).strip()},
            }

        updated_tables = body.get("updated_tables") or {}
        if isinstance(updated_tables, dict):
            return {
                "schema_exists": bool(schema_exists),
                "existing_tables": {str(table_name).strip().upper() for table_name in updated_tables.keys() if str(table_name).strip()},
            }

        return {"schema_exists": bool(schema_exists), "existing_tables": set()}
    except Exception as e:
        raise ValueError(f"Failed to fetch schema state from Snowflake schema '{schema_name}': {e}")


def get_s3_snowflake_edit_policy(connection, destination_config, destination_schema, config_data):
    """
    Determine editability policy for AmazonS3 edit flow against Snowflake destination.
    """
    if not connection or not destination_config:
        return None
    if str(getattr(destination_config.dst, "name", "")).strip() != "Snowflake":
        return None

    state = fetch_snowflake_schema_state(destination_config, destination_schema)
    schema_exists = bool(state.get("schema_exists"))
    existing_tables = state.get("existing_tables") or set()
    existing_tables = {str(t).strip().upper() for t in existing_tables if str(t).strip()}
    any_tables_exist = bool(existing_tables)

    if not schema_exists:
        return {
            "schema_exists": False,
            "schema_read_only": False,
            "allow_full_edit": True,
            "allow_edit_except_schema": False,
            "keep_post_migration_lock": False,
            "missing_mapped_tables": set(),
        }

    mapped_tables = set()
    try:
        s3_mapping = connection.source_file_mapping
        mode = (s3_mapping.file_mapping_mode or "single_table_per_file").strip()
        if mode == "single_table_per_file":
            single_map = s3_mapping.single_file_table_mapping if isinstance(s3_mapping.single_file_table_mapping, dict) else {}
            mapped_tables = {
                sanitize_identifier(str(v).strip())
                for v in single_map.values()
                if str(v).strip()
            }
        elif mode == "multi_files_single_table":
            multi_table = (config_data or {}).get("multi_files_table_name")
            if str(multi_table or "").strip():
                mapped_tables = {sanitize_identifier(str(multi_table).strip())}
    except Exception:
        mapped_tables = set()

    mapped_upper = {str(t).strip().upper() for t in mapped_tables if str(t).strip()}

    connection_tables_upper = set()
    try:
        connection_tables_upper = {
            str(t).strip().upper()
            for t in SourceTableSelection.objects.filter(connection_id=connection.connection_id).values_list("table", flat=True)
            if str(t).strip()
        }
    except Exception:
        connection_tables_upper = set()

    tracked_tables_upper = mapped_upper | connection_tables_upper
    missing_mapped_tables = mapped_upper - existing_tables if mapped_upper else set()
    any_tracked_table_present = bool(existing_tables & tracked_tables_upper)

    # New rule: if any table exists in schema, lock all fields (except connection_name/keys handled elsewhere).
    allow_edit_except_schema = schema_exists and not any_tracked_table_present
    keep_post_migration_lock = schema_exists and any_tracked_table_present

    return {
        "schema_exists": True,
        "schema_read_only": True,
        "allow_full_edit": False,
        "allow_edit_except_schema": allow_edit_except_schema,
        "keep_post_migration_lock": keep_post_migration_lock,
        "missing_mapped_tables": missing_mapped_tables,
    }


def validate_s3_runtime_access_and_mappings(source_form_data, cmp_id, user_id):
    """
    Validate S3 credentials/bucket/prefix/file visibility and mapped file existence
    by calling FastAPI listing endpoint before save/update.
    Returns (is_valid, error_message, status_code).
    """
    if not isinstance(source_form_data, dict):
        return False, "Invalid S3 configuration payload.", 400

    mapping_mode = (
        source_form_data.get("file_mapping_method")
        or source_form_data.get("file_mapping_mode")
        or "single_table_per_file"
    ).strip()
    single_map_for_validation = source_form_data.get("single_file_table_mapping") or {}
    if mapping_mode == "multi_files_single_table":
        # Prefix-driven mode: never validate stale explicit per-file mappings.
        single_map_for_validation = {}

    payload = {
        "connection_id": 0,
        "AmazonS3": {
            "s3_bucket": source_form_data.get("s3_bucket"),
            "aws_access_key_id": source_form_data.get("aws_access_key_id"),
            "aws_secret_access_key": source_form_data.get("aws_secret_access_key"),
            "aws_region": source_form_data.get("aws_region") or "",
            "s3_base_prefix": source_form_data.get("s3_base_prefix") or "",
            "include_subfolders": parse_bool_like(source_form_data.get("include_subfolders"), default=False),
            "file_type": source_form_data.get("file_type"),
            "file_mapping_mode": mapping_mode,
            "single_file_table_mapping": single_map_for_validation,
            "multi_files_prefix": source_form_data.get("multi_files_prefix") or "",
            "multi_files_table_name": source_form_data.get("multi_files_table_name") or "",
        },
        "cmp_id": int(cmp_id),
        "user_id": int(user_id),
        "job_name": "s3_pre_save_validation",
        "last_checked_date": None,
    }

    try:
        api_url = get_migration_api_url("AmazonS3-listing-files")
        response = requests.post(
            api_url,
            data=json.dumps(payload),
            headers=_fastapi_headers(),
            verify=False,
            timeout=60,
        )
        if response.status_code != 200:
            detail = extract_api_error_message(response)
            return False, detail or f"S3 validation failed with HTTP {response.status_code}.", response.status_code

        result = response.json()
        listed_tables = ((result or {}).get("result") or {}).get("tables") or []
        existing_file_keys = {str(t.get("file_key")).strip() for t in listed_tables if t.get("file_key")}
        existing_basenames = {k.split("/")[-1] for k in existing_file_keys}

        missing_mapped_files = []

        if mapping_mode == "single_table_per_file":
            single_map = single_map_for_validation
            for mapped_file_key in single_map.keys():
                fk = str(mapped_file_key).strip()
                if not fk:
                    continue
                if fk not in existing_file_keys and fk.split("/")[-1] not in existing_basenames:
                    missing_mapped_files.append(fk)

        elif mapping_mode == "multi_files_single_table":
            # Prefix-driven mode has no explicit file-to-table mapping to validate here.
            pass

        if missing_mapped_files:
            sample = ", ".join(sorted(set(missing_mapped_files))[:5])
            return False, (
                f"Mapped file(s) not found in S3 bucket/prefix for selected file type: {sample}. "
                "Please verify mapped file paths and base folder path."
            ), 400

        return True, None, 200
    except requests.RequestException as e:
        return False, f"Failed to validate S3 files against backend service: {str(e)}", 502
    except Exception as e:
        return False, f"S3 validation error: {str(e)}", 500


def parse_s3_custom_pk_mapping(raw_value):
    """
    Normalize custom_primary_key to a dict[str, list[str]].
    """
    if isinstance(raw_value, str):
        raw_value = safe_parse_json(raw_value, default={}, field_name="custom_primary_key")
    if not isinstance(raw_value, dict):
        return {}

    normalized = {}
    for table_name, pk_cols in raw_value.items():
        table_key = str(table_name).strip()
        if not table_key:
            continue
        if isinstance(pk_cols, list):
            cols = [str(c).strip() for c in pk_cols if str(c).strip()]
        elif pk_cols is None:
            cols = []
        else:
            col = str(pk_cols).strip()
            cols = [col] if col else []
        normalized[table_key] = cols
    return normalized


def extract_mapped_tables_from_s3_config(
    file_mapping_mode,
    single_map,
    multi_map,
    multi_files_table_name=None,
):
    """
    Return mapped table names from S3 config mapping payload.
    """
    tables = []
    mode = (file_mapping_mode or "single_table_per_file").strip()
    if mode == "single_table_per_file":
        if isinstance(single_map, dict):
            for table_name in single_map.values():
                table = str(table_name).strip()
                if table:
                    tables.append(table)
    elif mode == "multi_files_single_table":
        if isinstance(multi_map, dict):
            for table_name in multi_map.keys():
                table = str(table_name).strip()
                if table:
                    tables.append(table)
        if not tables:
            fallback = str(multi_files_table_name or "").strip()
            if fallback:
                tables.append(fallback)
    return tables


def is_allowed_s3_custom_pk_additive_change(existing_pk_map, incoming_pk_map, allowed_new_tables):
    """
    Allow read-only bypass only when existing table PK definitions remain unchanged
    and new PK definitions are added only for allowed newly-mapped tables.
    """
    existing = parse_s3_custom_pk_mapping(existing_pk_map)
    incoming = parse_s3_custom_pk_mapping(incoming_pk_map)
    allowed_new_upper = {str(t).strip().upper() for t in (allowed_new_tables or []) if str(t).strip()}

    def _normalize_pk_cols(cols):
        # Compare PKs as a normalized set to avoid false failures due to order/case/format differences.
        return sorted({str(c).strip().upper() for c in (cols or []) if str(c).strip()})

    existing_upper = {k.upper(): _normalize_pk_cols(v) for k, v in existing.items()}
    incoming_upper = {k.upper(): _normalize_pk_cols(v) for k, v in incoming.items()}

    # Existing table PKs must remain exactly unchanged
    for table_name_upper, old_cols in existing_upper.items():
        if table_name_upper not in incoming_upper:
            return False
        if incoming_upper[table_name_upper] != old_cols:
            return False

    # Any new entries must belong only to newly added mapped tables
    for table_name_upper in incoming_upper.keys():
        if table_name_upper not in existing_upper and table_name_upper not in allowed_new_upper:
            return False

    return True


def describe_s3_custom_pk_change_details(existing_pk_map, incoming_pk_map, allowed_new_tables):
    """
    Return user-facing details for disallowed custom_primary_key updates.
    """
    existing = parse_s3_custom_pk_mapping(existing_pk_map)
    incoming = parse_s3_custom_pk_mapping(incoming_pk_map)
    allowed_new_upper = {str(t).strip().upper() for t in (allowed_new_tables or []) if str(t).strip()}

    def _normalize_pk_cols(cols):
        return sorted({str(c).strip().upper() for c in (cols or []) if str(c).strip()})

    existing_upper = {k.upper(): _normalize_pk_cols(v) for k, v in existing.items()}
    incoming_upper = {k.upper(): _normalize_pk_cols(v) for k, v in incoming.items()}

    changed_existing = []
    removed_existing = []
    invalid_new_tables = []

    for table_name_upper, old_cols in existing_upper.items():
        new_cols = incoming_upper.get(table_name_upper)
        if new_cols is None:
            removed_existing.append(table_name_upper)
            continue
        if new_cols != old_cols:
            changed_existing.append((table_name_upper, old_cols, new_cols))

    for table_name_upper, new_cols in incoming_upper.items():
        if table_name_upper not in existing_upper and table_name_upper not in allowed_new_upper:
            invalid_new_tables.append((table_name_upper, new_cols))

    detail_lines = []
    for table_name_upper, old_cols, new_cols in changed_existing:
        detail_lines.append(
            f"Table '{table_name_upper}' PK changed from {old_cols} to {new_cols}"
        )
    for table_name_upper in removed_existing:
        detail_lines.append(
            f"Table '{table_name_upper}' PK mapping was removed"
        )
    for table_name_upper, new_cols in invalid_new_tables:
        detail_lines.append(
            f"Table '{table_name_upper}' is not newly mapped (incoming PK: {new_cols})"
        )

    return detail_lines


def parse_config_data_safely(config_data, config_name="config", raise_on_error=False):
    """
    Safely parse configuration data from various formats (string, dict, bytes).
    
    Args:
        config_data: Configuration data (string, dict, bytes, or None)
        config_name: Name of config for error messages (default: "config")
        raise_on_error: If True, raise ValueError on parse failure (default: False)
    
    Returns:
        dict: Parsed configuration dictionary
    
    Raises:
        ValueError: If raise_on_error=True and parsing fails
    """
    if config_data is None:
        if raise_on_error:
            raise ValueError(f"{config_name} is None")
        return {}
    
    if isinstance(config_data, dict):
        return config_data
    
    if isinstance(config_data, bytes):
        try:
            config_data = config_data.decode('utf-8')
        except UnicodeDecodeError as e:
            if raise_on_error:
                raise ValueError(f"Failed to decode {config_name} (bytes): {e}")
            logger.warning(f"Failed to decode {config_name} (bytes): {e}")
            return {}
    
    if isinstance(config_data, str):
        try:
            parsed = json.loads(config_data)
            if isinstance(parsed, dict):
                return parsed
            if raise_on_error:
                raise ValueError(f"{config_name} parsed but not a dict: {type(parsed)}")
            logger.warning(f"{config_name} parsed but not a dict: {type(parsed)}")
            return {}
        except (json.JSONDecodeError, ValueError) as e:
            if raise_on_error:
                raise ValueError(f"Failed to parse {config_name} JSON: {e}")
            logger.warning(f"Failed to parse {config_name} JSON: {e}")
            return {}
    
    if raise_on_error:
        raise ValueError(f"{config_name} is unexpected type: {type(config_data)}")
    logger.warning(f"{config_name} is unexpected type: {type(config_data)}")
    return {}



