@login_required
def suggest_s3_table_name(request):
    """
    API endpoint to suggest a table name from common file names.
    Used for Multi Files → Single Table mode.
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Only POST method allowed'}, status=405)

    try:
        data = json.loads(request.body)
        file_keys = data.get('file_keys', [])

        if not file_keys or not isinstance(file_keys, list):
            return JsonResponse({
                'success': True,
                'suggested_table': 'merged_table',
            })

        # Extract stems (filename without extension) from file keys
        stems = []
        for key in file_keys:
            if isinstance(key, str):
                # Get filename from path
                filename = key.split('/')[-1]
                # Remove extension
                stem = filename.rsplit('.', 1)[0] if '.' in filename else filename
                stems.append(stem)

        if not stems:
            return JsonResponse({
                'success': True,
                'suggested_table': 'merged_table',
            })

        # Find common prefix
        prefix = stems[0]
        for stem in stems[1:]:
            common = os.path.commonprefix([prefix, stem])
            if not common:
                break
            prefix = common

        # Sanitize the prefix: only alphanumeric + underscore
        sanitized = re.sub(r'[^A-Za-z0-9_]', '_', prefix).strip('_')

        # Ensure it starts with a letter
        if not sanitized or not sanitized[0].isalpha():
            sanitized = f"t_{sanitized}" if sanitized else "merged_table"

        suggested = sanitized.lower() if sanitized else "merged_table"

        if len(suggested) < 2:
            suggested = "merged_table"

        return JsonResponse({
            'success': True,
            'suggested_table': suggested,
        })

    except json.JSONDecodeError:
        return JsonResponse({
            'success': False,
            'message': 'Invalid JSON in request body',
        }, status=400)
    except Exception as e:
        return JsonResponse({
            'success': False,
            'message': f'Error: {str(e)}',
        }, status=500)


@login_required
@csrf_exempt
def list_s3_files(request):
    """
    API endpoint to list files from S3 bucket.
    Called from the file mapping modal to fetch available files.
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Only POST method allowed'}, status=405)

    try:
        data = json.loads(request.body)
        s3_bucket = data.get('s3_bucket')
        aws_access_key_id = data.get('aws_access_key_id')
        aws_secret_access_key = data.get('aws_secret_access_key')
        aws_region = data.get('aws_region')
        base_folder_path = data.get('base_folder_path', '')
        file_type = data.get('file_type')
        include_subfolders = parse_bool_like(data.get('include_subfolders'), default=False)
        connection_id = data.get('connection_id') or 0
        file_mapping_mode = data.get('file_mapping_method') or data.get('file_mapping_mode') or "single_table_per_file"
        multi_files_prefix = data.get('multi_files_prefix', '')
        single_file_table_mapping = parse_s3_mapping_json(
            data.get('single_file_table_mapping'),
            mapping_type="single_file_table_mapping"
        )
        # Validate required fields
        if not all([s3_bucket, aws_access_key_id, aws_secret_access_key, file_type]):
            return JsonResponse({
                'success': False,
                'message': 'Missing required fields: s3_bucket, aws_access_key_id, aws_secret_access_key, file_type',
            }, status=400)

        normalized_base_prefix = normalize_s3_base_prefix(base_folder_path)
        s3_prefix_valid, s3_prefix_error = validate_s3_base_prefix(normalized_base_prefix)
        if not s3_prefix_valid:
            return JsonResponse({
                'success': False,
                'message': s3_prefix_error,
            }, status=400)

        payload = {
            "connection_id": connection_id,
            "AmazonS3": {
                "s3_bucket": s3_bucket,
                "aws_access_key_id": aws_access_key_id,
                "aws_secret_access_key": aws_secret_access_key,
                "aws_region": aws_region or "",
                "s3_base_prefix": normalized_base_prefix,
                "include_subfolders": include_subfolders,
                "file_type": file_type,
                "file_mapping_mode": file_mapping_mode,
                "multi_files_prefix": multi_files_prefix,
                "single_file_table_mapping": single_file_table_mapping,
            },
            "cmp_id": getattr(request.user, 'cmp_id', 0),
            "user_id": getattr(request.user, 'user_id', 0),
            "job_name": "s3_file_listing",
            "last_checked_date": None,
        }

        destination_config = None
        connection_dst_schema = None
        if connection_id:
            try:
                connection = Connection.objects.select_related("dst_config").get(connection_id=connection_id)
                dest_data = connection.dst_config.data if connection.dst_config else None
                connection_dst_schema = str(connection.dst_schema or "").strip() or None
                if isinstance(dest_data, str):
                    try:
                        dest_data = json.loads(dest_data)
                    except Exception:
                        dest_data = None
                if isinstance(dest_data, dict):
                    destination_config = dest_data
            except Connection.DoesNotExist:
                destination_config = None
            except Exception:
                destination_config = None

        if destination_config:
            if connection_dst_schema:
                destination_config = dict(destination_config)
                destination_config["schema"] = connection_dst_schema
            try:
                logger.info(
                    "[S3][LIST_FILES] Injecting destination_config into payload "
                    "(account=%s, database=%s, schema=%s, auth=%s)",
                    destination_config.get("account"),
                    destination_config.get("database"),
                    connection_dst_schema,
                    destination_config.get("authentication_type"),
                )
            except Exception:
                logger.info("[S3][LIST_FILES] Injecting destination_config into payload")
            payload["AmazonS3"]["destination_config"] = destination_config
        else:
            logger.info("[S3][LIST_FILES] destination_config not available; skipping injection")

        api_url = get_migration_api_url("AmazonS3-listing-files")
        headers = _fastapi_headers()

        try:
            response = requests.post(
                api_url,
                json=payload,
                headers=headers,
                verify=should_verify_s3_api_ssl(),
                timeout=30,
            )
            response.raise_for_status()
            result = response.json()
        except requests.HTTPError as e:
            upstream_response = e.response if e.response is not None else response
            return JsonResponse({
                'success': False,
                'message': extract_api_error_message(upstream_response),
            }, status=upstream_response.status_code if upstream_response is not None else 502)
        except requests.RequestException as e:
            return JsonResponse({
                'success': False,
                'message': f'Failed to connect to API: {str(e)}',
            }, status=502)

        if 'result' in result:
            tables = result['result'].get('tables', [])
            files_count = result['result'].get('files_count', 0)
            return JsonResponse({
                'success': True,
                'tables': tables,
                'files_count': files_count,
            })

        return JsonResponse({
            'success': False,
            'message': 'Unexpected response format from API',
        }, status=500)

    except json.JSONDecodeError:
        return JsonResponse({
            'success': False,
            'message': 'Invalid JSON in request body',
        }, status=400)
    except Exception as e:
        return JsonResponse({
            'success': False,
            'message': f'Error: {str(e)}',
        }, status=500)


@login_required
@csrf_exempt
def list_sftp_files(request):
    """
    API endpoint to list files from SFTP root folder.
    Called from the file mapping modal to fetch available files.
    Mirrors the S3 helper flow.
    """
    if request.method != 'POST':
        return JsonResponse(
            {'success': False, 'message': 'Only POST method allowed'},
            status=405
        )

    try:
        data = json.loads(request.body)

        connection_id = data.get('connection_id') or 0
        file_mapping_mode = (
            data.get('file_mapping_method')
            or data.get('file_mapping_mode')
            or "single_table_per_file"
        )

        source_config = {}

        # Optional connection lookup (same pattern as S3)
        if connection_id:
            try:
                connection = Connection.objects.select_related(
                    "src_config"
                ).get(connection_id=connection_id)

                source_config = (
                    connection.src_config.data
                    if connection.src_config
                    else {}
                )

            except Connection.DoesNotExist:
                source_config = {}
            except Exception:
                source_config = {}

        if isinstance(source_config, str):
            source_config = safe_parse_json(
                source_config,
                default={},
                field_name="source_config"
            )

        if not isinstance(source_config, dict):
            source_config = {}

        # Resolve values from request first, then stored config, allowing explicit overrides (like empty strings)
        sftp_host = data.get("sftp_host") if "sftp_host" in data and data.get("sftp_host") is not None else source_config.get("sftp_host")
        sftp_port = data.get("sftp_port") if "sftp_port" in data and data.get("sftp_port") is not None else source_config.get("sftp_port")
        sftp_username = data.get("sftp_username") if "sftp_username" in data and data.get("sftp_username") is not None else source_config.get("sftp_username")
        authentication_type = (
            data.get("authentication_type")
            if "authentication_type" in data and data.get("authentication_type") is not None
            else source_config.get("authentication_type")
        )
        sftp_password = data.get("sftp_password") if "sftp_password" in data and data.get("sftp_password") is not None else source_config.get("sftp_password")
        sftp_private_key = (
            data.get("sftp_private_key")
            if "sftp_private_key" in data and data.get("sftp_private_key") is not None
            else source_config.get("sftp_private_key")
        )
        sftp_passphrase = (
            data.get("sftp_passphrase")
            if "sftp_passphrase" in data and data.get("sftp_passphrase") is not None
            else source_config.get("sftp_passphrase")
        )

        if "root_folder" in data and data.get("root_folder") is not None:
            root_folder = data.get("root_folder")
        elif "folder_path" in data and data.get("folder_path") is not None:
            root_folder = data.get("folder_path")
        else:
            root_folder = source_config.get("root_folder") or source_config.get("folder_path")

        base_folder_path = (
            data.get("base_folder_path")
            if "base_folder_path" in data and data.get("base_folder_path") is not None
            else source_config.get("base_folder_path")
        )
        if base_folder_path is None:
            base_folder_path = ""

        raw_include = data.get("include_subfolders")
        if raw_include is None:
            raw_include = source_config.get("include_subfolders")
        include_subfolders = parse_bool_like(raw_include, default=False)

        file_type = data.get("file_type") if "file_type" in data and data.get("file_type") is not None else source_config.get("file_type")

        # Validate required fields
        if not all([
            sftp_host,
            sftp_username,
            file_type
        ]):
            return JsonResponse(
                {
                    "success": False,
                    "message": (
                        "Missing required fields: "
                        "sftp_host, sftp_username, file_type"
                    ),
                },
                status=400,
            )

        payload = {
            "connection_id": connection_id,
            "SFTP": {
                **source_config,
                "sftp_host": sftp_host,
                "sftp_port": sftp_port,
                "sftp_username": sftp_username,
                "authentication_type": authentication_type,
                "sftp_password": sftp_password,
                "sftp_private_key": sftp_private_key,
                "sftp_passphrase": sftp_passphrase,
                "root_folder": root_folder,
                "base_folder_path": base_folder_path,
                "include_subfolders": include_subfolders,
                "file_type": file_type,
                "file_mapping_method": file_mapping_mode,
                "file_mapping_mode": file_mapping_mode,  # alias: migration service reads this key
                "single_file_table_mapping": parse_s3_mapping_json(
                    data.get("single_file_table_mapping")
                    if "single_file_table_mapping" in data and data.get("single_file_table_mapping") is not None
                    else source_config.get("single_file_table_mapping"),
                    mapping_type="single_file_table_mapping",
                ),
                "table_to_files_mapping": (
                    data.get("table_to_files_mapping")
                    if "table_to_files_mapping" in data and data.get("table_to_files_mapping") is not None
                    else source_config.get("table_to_files_mapping") or {}
                ),
                "multi_files_prefix": (
                    data.get("multi_files_prefix")
                    if "multi_files_prefix" in data and data.get("multi_files_prefix") is not None
                    else source_config.get("multi_files_prefix") or ""
                ),
                "multi_files_table_name": (
                    data.get("multi_files_table_name")
                    if "multi_files_table_name" in data and data.get("multi_files_table_name") is not None
                    else source_config.get("multi_files_table_name") or ""
                ),
                "load_method": (
                    data.get("load_method")
                    if "load_method" in data and data.get("load_method") is not None
                    else source_config.get("load_method") or ""
                ),
                "custom_primary_key": (
                    data.get("custom_primary_key")
                    if "custom_primary_key" in data and data.get("custom_primary_key") is not None
                    else source_config.get("custom_primary_key") or {}
                ),
                "json_mode": (
                    data.get("json_mode")
                    if "json_mode" in data and data.get("json_mode") is not None
                    else source_config.get("json_mode") or ""
                ),
                "xml_mode": (
                    data.get("xml_mode")
                    if "xml_mode" in data and data.get("xml_mode") is not None
                    else source_config.get("xml_mode") or ""
                ),
            },
            "cmp_id": getattr(request.user, 'cmp_id', 0) or 0,
            "user_id": getattr(request.user, 'user_id', 0) or 0,
            "job_name": "sftp_file_listing",
            "last_checked_date": None,
        }

        # Optional destination config injection (same pattern as S3)
        destination_config = None
        connection_dst_schema = None

        if connection_id:
            try:
                connection = Connection.objects.select_related(
                    "dst_config"
                ).get(connection_id=connection_id)

                dest_data = (
                    connection.dst_config.data
                    if connection.dst_config
                    else None
                )

                connection_dst_schema = (
                    str(connection.dst_schema or "").strip()
                    or None
                )

                if isinstance(dest_data, str):
                    try:
                        dest_data = json.loads(dest_data)
                    except Exception:
                        dest_data = None

                if isinstance(dest_data, dict):
                    destination_config = dest_data

            except Exception:
                destination_config = None

        if destination_config:
            if connection_dst_schema:
                destination_config = dict(destination_config)
                destination_config["schema"] = connection_dst_schema

            payload["SFTP"]["destination_config"] = destination_config

        api_url = f"http://{FASTAPI_DOMAIN}/SFTP-listing-files"
        headers = _fastapi_headers()

        logger.info(
            "[SFTP][LIST_FILES] connection_id=%s host=%s root_folder=%s file_type=%s",
            connection_id,
            payload["SFTP"].get("sftp_host"),
            payload["SFTP"].get("root_folder"),
            payload["SFTP"].get("file_type"),
        )

        try:
            response = requests.post(
                api_url,
                json=payload,
                headers=headers,
                verify=False,
                timeout=30,
            )

            response.raise_for_status()
            result = response.json()

        except requests.HTTPError as e:
            upstream_response = e.response if e.response is not None else response

            return JsonResponse(
                {
                    'success': False,
                    'message': extract_api_error_message(upstream_response),
                },
                status=(
                    upstream_response.status_code
                    if upstream_response is not None
                    else 502
                )
            )

        except requests.RequestException as e:
            return JsonResponse(
                {
                    'success': False,
                    'message': f'Failed to connect to API: {str(e)}',
                },
                status=502
            )

        if 'result' in result:
            tables = result['result'].get('tables', [])
            files_count = result['result'].get('files_count', 0)

            return JsonResponse({
                'success': True,
                'tables': tables,
                'files_count': files_count,
            })

        return JsonResponse(
            {
                'success': False,
                'message': 'Unexpected response format from API',
            },
            status=500
        )

    except json.JSONDecodeError:
        return JsonResponse(
            {
                'success': False,
                'message': 'Invalid JSON in request body',
            },
            status=400
        )

    except Exception as e:
        logger.exception("[SFTP][LIST_FILES] Unexpected failure")

        return JsonResponse(
            {
                'success': False,
                'message': f'Error: {str(e)}',
            },
            status=500
        )

