@login_required
@csrf_exempt
def preview_s3_pattern(request):
    """
    API endpoint to preview which files match a regex pattern.
    Used for Multi Files → Single Table mode to validate patterns before migration.
    """
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Only POST method allowed'}, status=405)

    try:
        data = json.loads(request.body)
        s3_bucket = data.get('s3_bucket')
        aws_access_key_id = data.get('aws_access_key_id')
        aws_secret_access_key = data.get('aws_secret_access_key')
        aws_region = data.get('aws_region')
        base_folder_path = data.get('base_folder_path', '')
        file_type = data.get('file_type')
        include_subfolders = parse_bool_like(data.get('include_subfolders'), default=False)
        pattern = data.get('multi_files_prefix', '')
        max_results = data.get('max_results', 50)
        connection_id = data.get('connection_id') or 0

        # Validate required fields
        if not all([s3_bucket, aws_access_key_id, aws_secret_access_key, file_type, pattern]):
            return JsonResponse({
                'success': False,
                'message': 'Missing required fields: s3_bucket, aws_access_key_id, aws_secret_access_key, file_type, multi_files_prefix',
            }, status=400)

        normalized_base_prefix = normalize_s3_base_prefix(base_folder_path)
        s3_prefix_valid, s3_prefix_error = validate_s3_base_prefix(normalized_base_prefix)
        if not s3_prefix_valid:
            return JsonResponse({
                'success': False,
                'message': s3_prefix_error,
            }, status=400)

        # Validate pattern: allow regex and simple glob-style wildcards.
        try:
            re.compile(pattern)
        except re.error as e:
            if not any(token in pattern for token in ('*', '?', '[')):
                return JsonResponse({
                    'success': False,
                    'message': f'Invalid pattern: {str(e)}'
                }, status=400)

        payload = {
            "connection_id": connection_id,
            "AmazonS3": {
                "s3_bucket": s3_bucket,
                "aws_access_key_id": aws_access_key_id,
                "aws_secret_access_key": aws_secret_access_key,
                "aws_region": aws_region or "",
                "s3_base_prefix": normalized_base_prefix,
                "include_subfolders": include_subfolders,
                "file_type": file_type,
            },
            "multi_files_prefix": pattern,
            "max_results": max_results,
            "cmp_id": getattr(request.user, 'cmp_id', 0),
            "user_id": getattr(request.user, 'user_id', 0),
        }

        api_url = get_migration_api_url("AmazonS3-preview-pattern")
        headers = _fastapi_headers()

        try:
            response = requests.post(
                api_url,
                json=payload,
                headers=headers,
                verify=should_verify_s3_api_ssl(),
                timeout=30,
            )
            response.raise_for_status()
            result = response.json()
        except requests.HTTPError as e:
            upstream_response = e.response if e.response is not None else response
            return JsonResponse({
                'success': False,
                'message': extract_api_error_message(upstream_response),
            }, status=upstream_response.status_code if upstream_response is not None else 502)
        except requests.RequestException as e:
            return JsonResponse({
                'success': False,
                'message': f'Failed to connect to API: {str(e)}',
            }, status=502)

        # Return the result from FastAPI
        return JsonResponse(result)

    except json.JSONDecodeError:
        return JsonResponse({
            'success': False,
            'message': 'Invalid JSON in request body',
        }, status=400)
    except Exception as e:
        return JsonResponse({
            'success': False,
            'message': f'Error: {str(e)}',
        }, status=500)

@login_required
@csrf_exempt
def suggest_s3_primary_keys(request):
    """
    Proxy endpoint.
    Authenticates user and forwards request payload
    directly to FastAPI PK suggestion API.
    """

    if request.method != "POST":
        return JsonResponse(
            {"success": False, "message": "Only POST method allowed"},
            status=405,
        )

    try:
        # ------------------------------------------------------------------
        # 1. Parse frontend payload (DO NOT MODIFY STRUCTURE)
        # ------------------------------------------------------------------
        payload = json.loads(request.body)

        # Ensure sample_rows exists (optional safety)
        payload.setdefault("sample_rows", 1000)

        # ------------------------------------------------------------------
        # 1a. Short-circuit for packed JSON/XML (PK suggestion not supported)
        # ------------------------------------------------------------------
        s3_payload = payload
        if isinstance(payload.get("s3"), dict):
            s3_payload = payload.get("s3") or {}
        elif isinstance(payload.get("AmazonS3"), dict):
            s3_payload = payload.get("AmazonS3") or {}
        elif isinstance(payload.get("form_data"), dict):
            s3_payload = payload.get("form_data") or {}

        file_type = str(
            s3_payload.get("file_type") or payload.get("file_type") or ""
        ).strip().lower()
        json_mode = str(
            s3_payload.get("json_mode") or payload.get("json_mode") or ""
        ).strip().lower()
        xml_mode = str(
            s3_payload.get("xml_mode") or payload.get("xml_mode") or ""
        ).strip().lower()

        if file_type == "xml" and (not xml_mode or xml_mode == "packed"):
            return JsonResponse(
                {
                    "success": True,
                    "skipped": True,
                    "message": "Primary key suggestion is not required for packed XML.",
                    "tables": [],
                }
            )

        if file_type == "json" and json_mode == "packed":
            return JsonResponse(
                {
                    "success": True,
                    "skipped": True,
                    "message": "Primary key suggestion is not required for packed JSON.",
                    "tables": [],
                }
            )


        connection = None
        connection_id = payload.get("connection_id")
        if connection_id:
            try:
                connection = Connection.objects.select_related("src_config", "dst_config").get(
                    connection_id=connection_id, cmp_id=request.user.cmp_id,
                )
            except Connection.DoesNotExist:
                return JsonResponse({"success": False, "message": "Connection not found."}, status=404)

        mapping_method = (
            s3_payload.get("file_mapping_method") or s3_payload.get("file_mapping_mode")
            or payload.get("file_mapping_method") or payload.get("file_mapping_mode")
        )
        if mapping_method == "single_table_per_file":
            single_map = parse_s3_mapping_json(s3_payload.get("single_file_table_mapping"))
            if not single_map and connection is not None:
                saved_config = ensure_config_is_dict(connection.src_config.data, "source_config")
                same_bucket = str(saved_config.get("s3_bucket") or "").strip() == str(
                    s3_payload.get("s3_bucket") or payload.get("s3_bucket") or ""
                ).strip()
                saved_prefix = normalize_s3_base_prefix(
                    saved_config.get("base_folder_path") or saved_config.get("s3_base_prefix")
                )
                request_prefix = normalize_s3_base_prefix(
                    s3_payload.get("base_folder_path") or s3_payload.get("s3_base_prefix")
                )
                if same_bucket and saved_prefix == request_prefix:
                    saved_config = overlay_s3_mapping_from_source_file_mapping(connection, dict(saved_config))
                    saved_method = saved_config.get("file_mapping_mode") or saved_config.get("file_mapping_method")
                    if saved_method == "single_table_per_file":
                        single_map = parse_s3_mapping_json(saved_config.get("single_file_table_mapping"))
            if not single_map:
                return JsonResponse({
                    "success": False,
                    "message": "No file-to-table mapping is available. Select and map S3 files before choosing primary keys.",
                }, status=400)
            s3_payload["single_file_table_mapping"] = single_map

        # Inject destination_config for PK locking decisions (Snowflake existence check).
        try:
            if connection is not None:
                dest_data = connection.dst_config.data if connection.dst_config else None
                if isinstance(dest_data, str):
                    try:
                        dest_data = json.loads(dest_data)
                    except Exception:
                        dest_data = None
                if isinstance(dest_data, dict):
                    connection_dst_schema = str(connection.dst_schema or "").strip() or None
                    if connection_dst_schema:
                        dest_data = dict(dest_data)
                        dest_data["schema"] = connection_dst_schema
                    payload.setdefault("AmazonS3", {})
                    if isinstance(payload["AmazonS3"], dict):
                        payload["AmazonS3"]["destination_config"] = dest_data
        except Exception:
            pass

        # ------------------------------------------------------------------
        # 2. Forward payload to FastAPI
        # ------------------------------------------------------------------
        api_url = get_migration_api_url("AmazonS3-suggest-primary-keys")
        headers = _fastapi_headers()

        response = requests.post(
            api_url,
            json=payload,
            headers=headers,
            timeout=120,
            verify=False,  # keep if using self-signed certs
        )

        response.raise_for_status()

        return JsonResponse(_normalize_pk_suggestion_response(response.json()), safe=False)

    except json.JSONDecodeError:
        return JsonResponse(
            {"success": False, "message": "Invalid JSON payload"},
            status=400,
        )

    except requests.HTTPError as e:
        upstream = e.response
        message = extract_api_error_message(upstream) if upstream is not None else "PK suggestion service failed."
        return JsonResponse(
            {"success": False, "message": message},
            status=upstream.status_code if upstream is not None else 502,
        )

    except requests.RequestException as e:
        return JsonResponse(
            {
                "success": False,
                "message": f"Failed to reach PK suggestion service: {str(e)}",
            },
            status=502,
        )

    except Exception as e:
        return JsonResponse(
            {"success": False, "message": str(e)},
            status=500,
        )

@method_decorator(csrf_exempt, name='dispatch')
class RegistrationRequestAPIView(APIView):
    permission_classes = [AllowAny]

    def post(self, request, *args, **kwargs):
        serializer = RegistrationRequestSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        email = serializer.validated_data['email']
        if RegistrationRequest.objects.filter(email__iexact=email).exists():
            return Response(
                {'email': ['A registration request with this email already exists.']},
                status=status.HTTP_400_BAD_REQUEST,
            )

        registration_request = serializer.save()

        try:
            send_registration_request_email(serializer.validated_data)
        except Exception:
            logger.exception(
                'Failed to send registration request email for %s',
                serializer.validated_data['email'],
            )
            return Response(
                {
                    'error': 'Registration details were saved, but the email notification could not be sent.',
                    'registration_request_id': registration_request.registration_request_id,
                },
                status=status.HTTP_503_SERVICE_UNAVAILABLE,
            )

        return Response(
            {
                'message': 'Registration details saved and sent successfully.',
                'registration_request_id': registration_request.registration_request_id,
            },
            status=status.HTTP_201_CREATED,
        )


@method_decorator(csrf_exempt, name='dispatch')
class AuthAPIView(APIView):
    permission_classes = [AllowAny]
    def post(self, request, *args, **kwargs):
        data = request.data
        if 'company_name' in data:
            return self._do_signup(request, data)
        return self._do_signin(request, data)
 
    def _do_signup(self, request, data):
        import secrets
        from django.contrib.auth.hashers import make_password
        from django.core.cache import cache

        serializer = SignUpSerializer(data=data, context={'request': request})
        serializer.is_valid(raise_exception=True)
        user = serializer.create(serializer.validated_data)
        user.is_active = False
        user.save(update_fields=['is_active'])

        otp_code = f"{secrets.randbelow(900000) + 100000}"
        cache_key = f'otp_{user.company_email.lower()}'
        cache.set(cache_key, {
            'otp_hash': make_password(otp_code),
            'attempts': 0,
            'created_at': timezone.now().isoformat(),
        }, timeout=600)  # 10 minutes

        try:
            send_otp_email(user.company_email, otp_code)
        except Exception:
            logger.exception('Failed to send OTP email to %s', user.company_email)

        return Response({
            'message': 'Registration successful. A verification code has been sent to your email.',
            'email': user.company_email,
        }, status=status.HTTP_201_CREATED)

    def _do_signin(self, request, data):
        from django.core.cache import cache
        serializer = LoginSerializer(data=data)
        serializer.is_valid(raise_exception=True)
        cd = serializer.validated_data
        # USERNAME_FIELD is company_email — ModelBackend reads that key, not email=.
        user = authenticate(
            request,
            company_email=cd['username'],
            password=cd['password'],
        )
        if user is None:
            try:
                unverified = User.objects.get(company_email=cd['username'], is_active=False)
                cache_key = f'otp_{unverified.company_email.lower()}'
                if cache.get(cache_key):
                    return Response(
                        {'error': 'Please verify your email before logging in.'},
                        status=status.HTTP_403_FORBIDDEN
                    )
            except User.DoesNotExist:
                pass
            return Response({'error': 'Invalid credentials'}, status=status.HTTP_401_UNAUTHORIZED)

        if user.password_reset_required:
            return Response({
                'message': 'You must change your temporary password before continuing.',
                'password_change_required': True,
                'uid': urlsafe_base64_encode(force_bytes(user.pk)),
                'token': default_token_generator.make_token(user),
                'redirect_to': '/auth/change-initial-password',
            }, status=status.HTTP_200_OK)

        login(request, user, backend='django.contrib.auth.backends.ModelBackend')
        request.user = user
        create_new_session(request)
        log_function(request, f"User {user.first_name} logged in successfully", "S", None)
        refresh = RefreshToken.for_user(user)
        dest = 'home' if Connection.objects.filter(cmp_id=user.cmp).exists() else 'destination-home'
        return Response({
            'message': 'Login successful',
            'user': {
                'id': user.user_id,
                'role': user.roles.role_name if user.roles else None,
                'role_id': user.roles.role_id if user.roles else None,
                'account_id': user.cmp.cmp_id if user.cmp else None,
            },
            'access_token': str(refresh.access_token),
            'refresh_token': str(refresh),
            'redirect_to': dest
        }, status=status.HTTP_200_OK)
   
 
 
class VerifyOTPView(APIView):
    permission_classes = [AllowAny]

    def post(self, request):
        from django.contrib.auth.hashers import check_password
        from django.core.cache import cache

        serializer = VerifyOTPSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        email = serializer.validated_data['email'].lower()
        otp = serializer.validated_data['otp']

        try:
            user = User.objects.get(company_email__iexact=email)
        except User.DoesNotExist:
            return Response({'error': 'Invalid OTP.'}, status=status.HTTP_400_BAD_REQUEST)

        if user.is_active:
            return Response({'message': 'Email already verified. Please log in.'}, status=status.HTTP_200_OK)

        cache_key = f'otp_{email}'
        data = cache.get(cache_key)

        if not data:
            return Response({'error': 'OTP expired. Please request a new one.'}, status=status.HTTP_400_BAD_REQUEST)

        if data['attempts'] >= 5:
            cache.delete(cache_key)
            return Response({'error': 'Too many failed attempts. Please request a new OTP.'}, status=status.HTTP_400_BAD_REQUEST)

        if not check_password(otp, data['otp_hash']):
            data['attempts'] += 1
            cache.set(cache_key, data, timeout=600)
            remaining = 5 - data['attempts']
            return Response(
                {'error': f'Invalid OTP. {remaining} attempt(s) remaining.'},
                status=status.HTTP_400_BAD_REQUEST
            )

        cache.delete(cache_key)
        user.is_active = True
        user.save(update_fields=['is_active'])

        return Response({'message': 'Email verified successfully. You can now log in.'}, status=status.HTTP_200_OK)


class ResendOTPView(APIView):
    permission_classes = [AllowAny]

    def post(self, request):
        import secrets
        from django.contrib.auth.hashers import make_password
        from django.core.cache import cache

        serializer = ResendOTPSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        email = serializer.validated_data['email'].lower()

        try:
            user = User.objects.get(company_email__iexact=email)
        except User.DoesNotExist:
            return Response({'message': 'If a matching account exists, a new OTP has been sent.'}, status=status.HTTP_200_OK)

        if user.is_active:
            return Response({'message': 'Email already verified. Please log in.'}, status=status.HTTP_200_OK)

        # Rate-limit: separate key with 60s TTL
        rate_key = f'otp_resend_rate_{email}'
        if cache.get(rate_key):
            return Response({'error': 'Please wait before requesting a new OTP.'}, status=status.HTTP_429_TOO_MANY_REQUESTS)

        otp_code = f"{secrets.randbelow(900000) + 100000}"
        cache_key = f'otp_{email}'
        cache.set(cache_key, {
            'otp_hash': make_password(otp_code),
            'attempts': 0,
            'created_at': timezone.now().isoformat(),
        }, timeout=600)
        cache.set(rate_key, True, timeout=60)

        try:
            send_otp_email(user.company_email, otp_code)
        except Exception:
            logger.exception('Failed to resend OTP email to %s', user.company_email)

        return Response({'message': 'If a matching account exists, a new OTP has been sent.'}, status=status.HTTP_200_OK)


