class ConnectionListAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ✅ Admin and Analyst can view connections

    def get(self, request):
        cmp = request.user.cmp
        name = request.GET.get('name')
        source = request.GET.get('source')
        destination = request.GET.get('destination')
        status = request.GET.get('status')

        # 1. Filter connections with optimized queries using select_related and prefetch_related
        connections = Connection.objects.filter(cmp=cmp).exclude(status='D').select_related(
            'cmp',
            'cmp__created_by',
            'cmp__updated_by',
            'src_config',
            'src_config__src',
            'dst_config',
            'dst_config__dst',
            'dst_config__created_by',
            'dst_config__updated_by',
            'created_by',
            'updated_by',
        ).prefetch_related('scheduledjob_set')

        if name:
            connections = connections.filter(src_config__name__icontains=name)
        if source:
            connections = connections.filter(src_config__src__name__icontains=source)
        if destination:
            connections = connections.filter(dst_config__dst__name__icontains=destination)
        if status:
            connections = connections.filter(status=status)

        connections = connections.order_by('-updated_at')

        # 3. Paginate only if ?page is provided
        if 'page' in request.query_params:
            paginator = CustomPagination()  # or use api_settings.DEFAULT_PAGINATION_CLASS()
            page = paginator.paginate_queryset(connections, request)
            connection_ids = [conn.connection_id for conn in page]
            connections_to_serialize = page
        else:
            connection_ids = list(connections.values_list('connection_id', flat=True))
            connections_to_serialize = connections

        # 2. Last migration timestamps - optimized to query once for all connections (paginated or not)
        migration_data = (
            MigrationRecord.objects
            .filter(connection__cmp=cmp, connection_id__in=connection_ids)
            .values('connection')
            .annotate(max_created_on=Max('created_at'))
        )
        last_synced_times = {
            entry['connection']: entry['max_created_on'] for entry in migration_data
        }

        from apps.elttool.services.connection_migration_status import (
            bulk_connection_migration_status,
        )

        status_by_connection = bulk_connection_migration_status(connection_ids)
        migration_statuses = {
            cid: status_by_connection.get(cid, {}).get('migration_status')
            for cid in connection_ids
        }
        job_level_error_messages = {
            cid: status_by_connection.get(cid, {}).get('error_message')
            for cid in connection_ids
        }
        
        conn_serializer = ConnectionSerializer(
            connections_to_serialize, many=True,
            context={
                'last_synced_times': last_synced_times,
                'migration_statuses': migration_statuses,
                'job_level_error_messages': job_level_error_messages
            }
        )
        
        if 'page' in request.query_params:
            connection_data = paginator.get_paginated_response(conn_serializer.data).data
        else:
            connection_data = {
                'content': conn_serializer.data,
                'totalElements': len(conn_serializer.data),
                'size': len(conn_serializer.data)
            }

        # 4. Source Configs (Unpaginated) - optimized with select_related
        src_config_ids = connections.values_list('src_config_id', flat=True).distinct()
        source_configs = SourceConfig.objects.filter(
            cmp=cmp,
            src_config_id__in=src_config_ids
        ).select_related('src').distinct('src')
        src_config_serializer = SourceConfigSerializer(source_configs, many=True)

        # 5. Final Response
        connection_data.update({
            'sourceconfigslist': src_config_serializer.data,
            'cmp_id': cmp.cmp_id
        })

        return HttpResponse(orjson.dumps(connection_data), content_type="application/json")
  

class DestinationConfigListAPIView(ListAPIView):
    serializer_class = DestinationConfigSerializer
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ✅ Admin and Analyst can view destinations

    def get_queryset(self):
        """
        Return active DestinationConfig objects for the logged-in user's company,
        ordered by last update time.
        """
        queryset = DestinationConfig.objects.filter(
            cmp=self.request.user.cmp,
            is_active=True
        ).select_related(
            'dst',
            'cmp',
            'cmp__created_by',
            'cmp__updated_by',
            'created_by',
            'updated_by',
        ).order_by('-updated_at')

        name = self.request.GET.get('name')
        if name:
            queryset = queryset.filter(name__icontains=name)
        
        return queryset


    def list(self, request, *args, **kwargs):
        """
        If ?page param is present, use pagination.
        Otherwise return full data list without pagination.
        """
        if 'page' in request.query_params:
            response = super().list(request, *args, **kwargs)
        else:
            queryset = self.filter_queryset(self.get_queryset())
            serializer = self.get_serializer(queryset, many=True)
            response = Response({
                'content': serializer.data,
                'totalElements': len(serializer.data),
                'size': len(serializer.data)
            })

        # Add extra fields no matter which path is taken
        response.data.update({
            'show_add_destination_prompt': True,
            'cmp_id': request.user.cmp.cmp_id
        })
        return response

def create_new_session(request):
    # Find the maximum session number
    max_session_number = Log.objects.aggregate(Max('session'))['session__max']
 
    # Calculate the new session number
    session_number = max_session_number + 1 if max_session_number is not None else 1
   
    # Create a new session entry in the log table
   
    request.session['session_number'] = session_number

