class DestinationSchemaView(APIView):
    """
    API view to return the dynamic form schema for a given destination model.

    GET /<destination_name> returns:
    - static destination type (e.g. Snowflake)
    - list of form fields including destination_name
    
    Also stores the selected destination in session for later use during config creation.
    """
    permission_classes = [IsAuthenticated]  # Removed CheckTrialPeriod

    def get(self, request, destination_name):
        print("=" * 80)
        print(f"📋 DESTINATION SCHEMA REQUEST")
        print(f"   Requested destination: {destination_name}")
        print(f"   User: {request.user}")
        
        try:
            destination = DestinationModel.objects.get(name=destination_name)
            print(f"   ✅ Found destination: {destination.name} (ID: {destination.dst_id})")
        except DestinationModel.DoesNotExist:
            print(f"   ❌ Destination '{destination_name}' not found in database")
            print("=" * 80)
            return create_error_response("Destination not found", status_code=status.HTTP_404_NOT_FOUND)

        # ✅ Store destination in session for later use in DestinationConfigSaveAPIView
        request.session['selected_destination_name'] = destination_name
        request.session['selected_destination_id'] = destination.dst_id
        print(f"   💾 Stored in session:")
        print(f"      - selected_destination_name: {destination_name}")
        print(f"      - selected_destination_id: {destination.dst_id}")
        print("=" * 80)

        attributes = DestinationAttribute.objects.filter(dst=destination).order_by('dst_attr_id')
        fields = []

        for attr in attributes:
            field = {
                "name": attr.attribute_name,
                "label": attr.label,
                "type": attr.input_type,
                "required": attr.required,
                "widget": attr.widget,
                "is_visible": attr.is_visible,
            }

            _apply_destination_attribute_field_rules(field, attr)

            fields.append(field)

        # ✅ Inject destination_name field (for creating config later)
        fields.insert(0, {
            "name": "destination_name",
            "label": "Destination Name",
            "type": DestinationAttribute.CHAR_FIELD,
            "required": True,
            "widget": DestinationAttribute.TEXT_INPUT,
        })

        return Response({
            "destination": destination.name,  # static model name, like Snowflake
            "fields": fields
        })


class DestinationConfigFormView(APIView):
    permission_classes = [IsAuthenticated]

    """
    APIView to retrieve the details of a DestinationConfig for a given destination.

    - If dst_config_id is provided, loads existing configuration data to prefill the form.
    - Checks if there is a migration present for the given config.
    - Returns the destination name, list of form fields with current values,
    the dst_config_id, and a flag indicating migration presence.

    """

    def get(self, request, destination_name, dst_config_id=None):
        print("=" * 80)
        print(f"🔵 DESTINATION CONFIG FORM VIEW - GET REQUEST")
        print(f"   Destination: {destination_name}")
        print(f"   dst_config_id: {dst_config_id}")
        print("=" * 80)
        
        destination_model_instance = get_object_or_404(DestinationModel, name=destination_name)
        attributes = DestinationAttribute.objects.filter(dst=destination_model_instance).order_by('dst_attr_id')
    
        initial_data = {}
        migration_present = False
        has_data_transfers = False
        has_connections = False
        
        if dst_config_id:
            cmp_id = request.user.cmp.cmp_id
            print(f"📋 Edit Mode - Loading existing destination config (ID: {dst_config_id})")
            # Load DestinationConfig if editing
            destination_config = get_object_or_404(DestinationConfig, dst_config_id=dst_config_id, cmp_id=cmp_id)
            
            config_data = destination_config.data

            # Step 1: If it's a string, parse it
            if isinstance(config_data, str):
                try:
                    config_data = json.loads(config_data)
                    print("✅ Parsed config_data from JSON string")
                except json.JSONDecodeError:
                    print("⚠️ Failed to parse config_data JSON string")
                    config_data = {}

            # Step 2: Ensure it's a dictionary (expected format)
            if isinstance(config_data, dict):
                initial_data = _sanitize_destination_config_for_response(
                    config_data,
                    destination_name=destination_model_instance.name,
                )
                print(f"✅ Config data loaded: {list(initial_data.keys())}")
            else:
                print("⚠️ destination_config.data is not a dictionary. Got:", type(config_data))
                initial_data = {}  # fallback to empty dict to prevent crashing

            # ✅ Check for DataTransfer records
            print(f"\n🔍 Checking for connections and DataTransfer records...")
            connections = Connection.objects.filter(dst_config_id=dst_config_id)
            has_connections = connections.exists()
            print(f"   - Has connections: {has_connections}")
            
            if has_connections:
                # Check if any connection has DataTransfer records
                has_data_transfers = Data_Transfer.objects.filter(
                    connection__in=connections
                ).exists()
                print(f"   - Has DataTransfer records: {has_data_transfers}")
                
                # Check if migration exists (for backward compatibility)
                connection = connections.first()
                if connection:
                    selected_tables = SourceTableSelection.objects.filter(
                        connection_id=connection.connection_id, selected=True
                    ).order_by('sequence').values_list('table', flat=True)
                    migration_present = bool(list(selected_tables))
                    print(f"   - Migration present: {migration_present}")
            else:
                print(f"   - No connections found for this destination config")
        else:
            print(f"📋 Create Mode - No existing config")
        
        # Build fields with editable flags
        print(f"\n🔧 Building fields with editable flags...")
        fields = []
        for attr in attributes:
            # Calculate read_only flag first
            is_read_only = _get_destination_field_read_only(
                destination_model_instance.name,
                attr,
                has_data_transfers,
            )
            
            # Google Drive folder creation confirmation is only needed in create/OAuth flow.
            if _should_hide_destination_field_on_edit(
                destination_model_instance.name,
                attr.attribute_name,
                is_edit=bool(dst_config_id),
            ):
                continue
                
            value = initial_data.get(attr.attribute_name)
            field_info = {
                "name": attr.attribute_name,
                "label": attr.label,
                "type": attr.input_type,
                "required": attr.required,
                "widget": attr.widget,
                "value": value,
                "is_visible": attr.is_visible,
            }
            
            # ✅ Use calculated read_only flag
            field_info["read_only"] = is_read_only
            if dst_config_id and has_data_transfers:
                print(f"   🔒 Field '{attr.attribute_name}': read_only={field_info['read_only']} (DataTransfer exists)")
            elif dst_config_id:
                print(f"   ✅ Field '{attr.attribute_name}': read_only=False (no DataTransfer records)")
            
            _apply_destination_attribute_field_rules(field_info, attr)
            fields.append(field_info)

        # ✅ Add destination_name field (not in DestinationAttribute, but always editable)
        destination_name_value = initial_data.get('destination_name', '')
        destination_name_field = {
            "name": "destination_name",
            "label": "Destination Name",
            "type": "CharField",
            "required": True,
            "widget": "TextInput",
            "value": destination_name_value,
            "is_visible": True,
            "read_only": False,  # Always editable
        }
        fields.insert(0, destination_name_field)
        print(f"  ✅ destination_name: read_only=False (always editable)")

        print(f"\n✅ Returning response with {len(fields)} fields")
        print(f"   - has_data_transfers: {has_data_transfers}")
        print(f"   - has_connections: {has_connections}")
        print("=" * 80)

        return Response({
            "destination": destination_model_instance.name,
            "fields": fields,
            "dst_config_id": dst_config_id,
            "migration_present": migration_present,
            "has_data_transfers": has_data_transfers,
            "has_connections": has_connections,
        }, status=status.HTTP_200_OK)

class DestinationConfigStatusView(APIView):
    """
    Returns JSON details for a DestinationConfig including its parsed data
    and whether it has an associated connection.
    """
    permission_classes = [IsAuthenticated]
    def get(self, request, dst_config_id):
        
        # Get destination config - optimized with select_related for consistency
        destination = get_object_or_404(
            DestinationConfig.objects.select_related('dst'),
            dst_config_id=dst_config_id
        )

        # Try to decode JSON string from .data
        # ✅ DRY: Use helper function for JSON parsing
        config_data = parse_config_data_safely(destination.data, config_name="destination_config")
        if not config_data:
            return create_error_response(
                "Destination config data is invalid JSON.",
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR
            )
        config_data = _sanitize_destination_config_for_response(
            config_data,
            destination_name=getattr(getattr(destination, "dst", None), "name", None),
        )

        # Check if a non-deleted connection exists
        connection_exists = Connection.objects.filter(
            dst_config_id=dst_config_id
        ).exclude(status='D').exists()
      
        # Return JSON response
        return Response({
            "destination": {
                "id": destination.dst_config_id,
                "name": destination.name,
                "is_active": destination.is_active,
                "created_at": destination.created_at,
                "config_data": config_data
            },
            "cmp_id": request.user.cmp.cmp_id,
            "connection_exists": connection_exists
        }, status=status.HTTP_200_OK)

