class ConnectionTableStatusAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ? Admin and Analyst only
    def get(self, request):
        connection_id = request.GET.get('connection_id')
        table_name = request.GET.get('table')  # Optional

        if not connection_id:
            return Response(
                {
                    'message': format_error_message(
                        'connection_id parameter is required'
                    )
                },
                status=status.HTTP_400_BAD_REQUEST
            )

        from apps.elttool.services.connection_table_status_builder import (
            build_connection_table_status
        )

        data, error = build_connection_table_status(
            connection_id=connection_id,
            table_name=table_name
        )

        if error:
            return Response(
                {'message': format_error_message(error['message'])},
                status=status.HTTP_404_NOT_FOUND
            )

        return Response(data)

