class ConnectionLogsAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ? Admin and Analyst only  # Removed CheckTrialPeriod
    def get(self, request, connection_id):
        try:
            # Get connection - optimized with select_related
            connection = Connection.objects.select_related('src_config', 'dst_config', 'cmp').get(pk=connection_id)

            # --- PRESERVED FILTER LOGIC (2 days, 7 days, 30 days, etc.) ---
            # Default to 2 days if no filter explicitly provided
            start_date = timezone.now() - timedelta(days=2)
            
            # Check 'days' filter
            days = request.GET.get('days', None)
            if days:
                try:
                    days = int(days)
                    start_date = timezone.now() - timedelta(days=days)
                except ValueError:
                    return create_error_response('Invalid days parameter')

            # Check 'hour' filter (override days if provided)
            hour = request.GET.get('hour')
            if hour:
                try:
                    hour = int(hour)
                    start_date = timezone.now() - timedelta(hours=hour)
                except ValueError:
                    return Response({'message': format_error_message('Invalid hours parameter')}, status=400)

            # Get status filter parameter
            status_filter = request.GET.get('status', None)
            valid_statuses = ['completed', 'failed', 'all']
            if status_filter and status_filter.lower() not in valid_statuses:
                return Response({'message': format_error_message(f'Invalid status parameter. Valid values: {valid_statuses}')}, status=400)


            # Retrieve log entries within the selected date range
            # Base filters common to all views (connection + time)
            filter_kwargs = {
                'connection_id': connection_id,
                'time__gte': start_date,
                'migration_record_id__isnull': True  # Always filter out table-level logs (high-level only)
            }
            
            # Apply specific filters based on status
            # User requirement:
            # - Failed: job_name IS NOT NULL AND status IN ('P', 'F')
            # - Completed: job_name IS NOT NULL AND status = 'S'
            # - All: Show all high-level logs (existing behavior)
            
            if status_filter == 'failed':
                filter_kwargs['job_name__isnull'] = False
                filter_kwargs['status__in'] = ['P', 'F']
            elif status_filter == 'completed':
                filter_kwargs['job_name__isnull'] = False
                filter_kwargs['status'] = 'S'
            # else: status is 'all' or None -> use base filters only
            
            all_logs = Log.objects.filter(**filter_kwargs).select_related('user', 'migration_record').order_by('-time')

            # One row per migration session on the left — duplicate job-level
            # failure rows from fan-out finalization share the same session.
            deduped_logs = []
            seen_sessions = set()
            for log in all_logs:
                if log.job_name and log.session is not None:
                    if log.session in seen_sessions:
                        continue
                    seen_sessions.add(log.session)
                deduped_logs.append(log)

            logs_data = [
                serialize_connection_activity_log(
                    log,
                    timestamp_format="native",
                )
                for log in deduped_logs
            ]
            # Time frequencies for the connection
            time_frequencies = {
                'None': 'None',
                '1': '1 minute',
                '5': '5 minutes',
                '15': '15 minutes',
                '30': '30 minutes',
                '60': '1 hour',
                '120': '2 hours',
                '180': '3 hours',
                '360': '6 hours',
                '480': '8 hours',
                '720': '12 hours',
                '1440': '24 hours'
            }
            
            readable_time_frequency = time_frequencies.get(connection.time_frequency, 'Unknown')

            return HttpResponse(orjson.dumps({
                'logs': logs_data,
                'connection': {
                    'connection_id': connection.connection_id,
                    'readable_time_frequency': readable_time_frequency,
                    'time_frequency': connection.time_frequency,
                    'status': connection.status
                },
                'cmp_id': request.user.cmp.cmp_id if request.user.cmp else None
            }), content_type="application/json")

        except Connection.DoesNotExist:
            return Response({'message': format_error_message('Invalid connection ID')}, status=404)

class SessionDetailAPIView(APIView):
    permission_classes = [IsAuthenticated]  # Removed CheckTrialPeriod
    """
    API to get detailed information about a specific migration session
    """
    def get(self, request, connection_id, session_id):
        try:
            # Validate connection exists - optimized with select_related for consistency
            connection = Connection.objects.select_related('src_config', 'dst_config').get(pk=connection_id)
            
            # Check if session has logs
            if not Log.objects.filter(session=session_id, connection_id=connection_id).exists():
                return Response({
                    'message': f'Session {session_id} not found or has no logs'
                }, status=404)
            
            # Get all table-specific logs for this session (just the messages)
            session_logs = Log.objects.filter(
                session=session_id,
                connection_id=connection_id,
                migration_record__isnull=False  # Only logs with table names
            ).order_by('time')
            
            # Return just the log messages
            # ✅ Pass timestamp directly from DB (like HOME API) - Django will serialize it automatically
            logs = [{
                'message': log.message,
                'timestamp': log.time,  # ✅ Pass directly from DB - same as HOME API
                'status': log.status,
                'table': log.migration_record.table_name if log.migration_record else "Unknown"
            } for log in session_logs]
            
            return Response({
                'session_id': session_id,
                'logs': logs  # Just the messages
            })

        except Connection.DoesNotExist:
            return Response({'message': format_error_message('Invalid connection ID')}, status=404)
        except Exception as e:
            return Response({
                'message': f'Error retrieving session details: {str(e)}'
            }, status=500)


class ConnectionToggleAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAdministrator]  # ✅ Only Admins can toggle connections
    def post(self, request, connection_id):
        # Optimize query with select_related for consistency (even though only direct fields are accessed)
        connection = get_object_or_404(
            Connection.objects.select_related('src_config', 'dst_config'),
            connection_id=connection_id
        )

        safety_interval = connection.safety_interval
        start_date = connection.sync_start_date

        if connection.status == 'A':
            connection.status = 'P'  # Pause
            new_sync_frequency = "None"
            log_message = "Connection Paused"
        else:
            connection.status = 'A'  # Activate
            new_sync_frequency = connection.time_frequency
            log_message = "Connection Activated"

        update_sync_frequency(request, connection_id, new_sync_frequency, safety_interval, start_date)
        log_function(request, log_message, 'S', connection_id)
        connection.updated_by = request.user
        connection.save()

        # ✅ Trigger WebSocket status update to reflect status change (e.g., sync frequency)
        try:
            from apps.elttool.websocket.ws_utils import push_connection_table_status_update
            from apps.elttool.services.connection_table_status_builder import build_connection_table_status
            payload, error = build_connection_table_status(connection_id)
            if not error:
                push_connection_table_status_update(connection_id, payload)
        except Exception as ws_err:
            print(f"⚠️ WebSocket trigger failed in ConnectionToggle: {ws_err}")

        return Response({
            'connection_id': connection.connection_id,
            'new_status': connection.status,
            'message': log_message
        }, status=status.HTTP_200_OK)
    
class DiscardSchemaChangesAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAdministrator]  # ✅ Only Admins can discard schema changes
    def post(self, request, connection_id):
        connection = get_object_or_404(Connection, connection_id=connection_id)
        
        # Reset selected tables to last saved state
        from apps.elttool.models import SourceTableSelection
        selected_tables = SourceTableSelection.objects.filter(connection=connection)
        for table in selected_tables:
            table.selected = False  # or reload last saved version
            table.status = None
            table.save()
        
        # ✅ Trigger WebSocket status update to reflect cleared selection
        try:
            from apps.elttool.websocket.ws_utils import push_connection_table_status_update
            from apps.elttool.services.connection_table_status_builder import build_connection_table_status
            payload, error = build_connection_table_status(connection_id)
            if not error:
                push_connection_table_status_update(connection_id, payload)
        except Exception as ws_err:
            print(f"⚠️ WebSocket trigger failed in DiscardSchemaChanges: {ws_err}")
        
        log_function(request, "Unsaved schema changes discarded", "S", connection_id)
        return Response({"message": "Unsaved changes discarded."}, status=200)



class SalesforceCallbackAPIView(APIView):
    permission_classes = [AllowAny]  # OAuth callbacks don't have auth tokens
    authentication_classes = [SessionAuthentication]  # Load user from session cookie
    
    def get(self, request, *args, **kwargs):
        def redirect_destination_page(error_message=None):
            destination_url = 'https://gcp.datasyncher.com/dashboard/destinations'
            if not error_message:
                return redirect(destination_url)
            query = urllib.parse.urlencode({
                "oauth_status": "error",
                "oauth_error": error_message,
            })
            return redirect(f"{destination_url}?{query}")

        print("=" * 80)
        print("🔵 SALESFORCE DESTINATION CALLBACK API CALLED")
        print(f"🔵 Request path: {request.path}")
        print(f"🔵 Query params: {dict(request.GET)}")
        print("=" * 80)
        
        # ✅ Match Django: Retrieve session data
        source_config_id = request.session.get('source_config_id')
        temp_data = request.session.get('oauth_temp_data', {})
        
        print(f"\n📦 Session data check:")
        print(f"   - source_config_id (direct from session): {source_config_id}")
        print(f"   - temp_data present: {bool(temp_data)}")
        
        # ✅ FIX: Check if source_config_id exists in oauth_temp_data (for connection creation flow)
        if not source_config_id and temp_data:
            source_config_id = temp_data.get('source_config_id')
            print(f"   - source_config_id (from oauth_temp_data): {source_config_id}")
        
        # ✅ FIX: Get destination_schema from oauth_temp_data (for connection creation flow)
        destination_schema = temp_data.get('destination_schema')
        if not destination_schema:
            destination_schema = request.session.get('destination_schema')
        print(f"   - destination_schema: {destination_schema}")
        
        # ✅ Match Django: If no temp_data, redirect to destination-list
        if not temp_data:
            print("   ❌ Session expired - no temp_data found")
            request.session['oauth_error'] = "Session expired. Please start authorization again."
            return redirect_destination_page("Session expired. Please start authorization again.")



        # ✅ Match Django: Extract query parameters
        error = request.GET.get('error')
        code = request.GET.get('code')
        state = request.GET.get('state')
        
        print(f"\n🔍 OAuth callback parameters:")
        print(f"   - error: {error or 'None'}")
        print(f"   - code: {'Present' if code else 'Missing'}")
        print(f"   - state: {state or 'Missing'}")

        # ✅ Match Django: Handle OAuth errors
        if error:
            error_description = request.GET.get('error_description', error)
            print(f"   ❌ Authorization failed: {error_description}")
            request.session['oauth_error'] = f"Authorization failed: {error_description}"
            return redirect_destination_page(f"Authorization failed: {error_description}")

        # ✅ Match Django: Validate state
        if not code or state != temp_data.get('state'):
            print(f"   ❌ Invalid parameters or CSRF attack")
            print(f"      Expected state: {temp_data.get('state')}")
            print(f"      Received state: {state}")
            request.session['oauth_error'] = "Invalid request parameters. Possible CSRF attack."
            return redirect_destination_page("Invalid request parameters. Possible CSRF attack.")

        # ✅ Match Django: Encode session form data
        callback_payload = dict(temp_data.get('form_data', {}))
        if temp_data.get('redirect_uri'):
            callback_payload['redirect_uri'] = temp_data.get('redirect_uri')
        data = json.dumps(callback_payload)
        encoded_data = urllib.parse.quote(data)

        # ✅ Match Django: Determine API endpoint (Salesforce vs SalesforceSandbox)
        dst_name = temp_data['dst']
        if dst_name == "SalesforceSandbox":
            api_path = 'salesforcesandbox/callback'
        elif dst_name == "GoogleDrive":
            api_path = 'google-drive/callback'
        else:
            api_path = 'salesforce/callback'
        api_url = get_migration_api_url(api_path)

        # ✅ Match Django: Exchange authorization code for tokens
        print(f"\n🔄 Exchanging authorization code for access token...")
        print(f"   API URL: {api_url}")
        try:
            url = f'{api_url}?code={code}&state={state}&data_new={encoded_data}'
            token_response = requests.get(url, verify=False)
            token_response.raise_for_status()
            tokens = token_response.json()
            if isinstance(tokens, str):
                tokens = json.loads(tokens)

            print(f"   ✅ Token exchange successful")
        except requests.RequestException as e:
            print(f"   ❌ Token exchange failed: {str(e)}")
            error_message = None
            response = getattr(e, "response", None)
            if response is not None:
                try:
                    error_payload = response.json()
                except ValueError:
                    error_payload = None

                if isinstance(error_payload, dict):
                    detail = error_payload.get("detail")
                    if isinstance(detail, dict):
                        error_message = (
                            detail.get("message")
                            or detail.get("detail")
                            or detail.get("error_description")
                        )
                    elif isinstance(detail, str):
                        error_message = detail

                    if not error_message:
                        error_message = (
                            error_payload.get("message")
                            or error_payload.get("body")
                            or error_payload.get("error_description")
                        )

                if not error_message:
                    error_message = response.text.strip() or None

            request.session['oauth_error'] = error_message or f"Token exchange failed: {e}"
            return redirect_destination_page(request.session['oauth_error'])

        # ✅ Match Django: Get destination model and existing config (if any)
        destination_model = get_object_or_404(DestinationModel, name=dst_name)
        existing_config = DestinationConfig.objects.filter(
            cmp=request.user.cmp,
            dst=destination_model,
            name=temp_data.get('destination_name'),
            is_active=True
        ).first()

        # ✅ Match Django: Prepare updated data
        updated_data = {
            'state': state,
        }
        persisted_form_data = dict(temp_data.get('form_data', {}))
        persisted_form_data.pop('create_folder_if_missing', None)
        if dst_name == "GoogleDrive":
            updated_data.update({
                'access_token': tokens.get('access_token'),
                'refresh_token': tokens.get('refresh_token'),
                'token_expires_at': tokens.get('token_expires_at'),
                'folder_id': tokens.get('folder_id') or temp_data.get('form_data', {}).get('folder_id'),
                'folder_name': tokens.get('folder_name') or temp_data.get('form_data', {}).get('folder_name'),
            })
        else:
            updated_data.update({
                'access_token': tokens.get('access_token'),
                'refresh_token': tokens.get('refresh_token'),
                'instance_url': tokens.get('instance_url'),
            })

        connection = None
        destination_config = None

        # ✅ Match Django: If existing_config exists, update it
        if existing_config:
            # ✅ Match Django: Update existing DestinationConfig
            # ✅ DRY: Use helper function for JSON parsing
            existing_data = safe_parse_json(existing_config.data if existing_config.data else {}, default={}, field_name="existing_config_data")
            existing_data.pop('create_folder_if_missing', None)
            existing_data.update(updated_data)
            existing_config.data = json.dumps(existing_data)
            existing_config.is_active = True
            existing_config.save()
            print(f"   ✅ Updated existing destination config (ID: {existing_config.dst_config_id})")

            # ✅ Match Django: messages.success(request, f"{dst_name} authorization updated successfully!")
            request.session['oauth_success'] = f"{dst_name} destination configuration updated and authorized successfully!"

            # ✅ Match Django: Check for connection if source_config_id exists
            if source_config_id:
                source_model_instance = get_object_or_404(SourceConfig, src_config_id=source_config_id)
                connection = Connection.objects.filter(
                    dst_config=existing_config, 
                    src_config=source_model_instance
                ).first()

            # ✅ Match Django: If connection exists, redirect to destination_detail
            if connection:
                print(f"\n✅ SUCCESS - Updated existing configuration and connection exists")
                print(f"   → Redirecting to destination detail (Django: destination_detail)")
                # Django redirects to 'destination_detail' → React: '/dashboard/connectors' (connection creation flow)
                return redirect('/dashboard/connectors')

        else:
            # ✅ Match Django: Create new DestinationConfig
            destination_config = DestinationConfig.objects.create(
                cmp=request.user.cmp,
                created_by=request.user,
                updated_by=request.user,
                dst=destination_model,
                name=temp_data.get('destination_name'),
                data=json.dumps({**persisted_form_data, **updated_data}),
                is_active=True
            )
            print(f"   ✅ Destination config created (ID: {destination_config.dst_config_id})")

            # ✅ Match Django: messages.success(request, f"{dst_name} authorization completed successfully!")
            request.session['oauth_success'] = f"{dst_name} authorization completed successfully!"

            # ✅ Match Django: If no source_config_id, redirect to source-list
            if not source_config_id:
                print(f"   → Redirecting to source-list (Django: source-list)")
                return redirect_destination_page()

        # ✅ Match Django: Create new Connection if needed
        if source_config_id:
            source_model_instance = get_object_or_404(SourceConfig, src_config_id=source_config_id)
            # ✅ FIX: destination_schema already retrieved from oauth_temp_data above

            connection = Connection.objects.create(
                cmp=request.user.cmp,
                created_by=request.user,
                updated_by=request.user,
                src_config=source_model_instance,
                dst_config=existing_config if existing_config else destination_config,
                dst_schema=destination_schema,
                status="A"
            )
            print(f"   ✅ Connection created (ID: {connection.connection_id})")
            # Note: Schema is created during destination authorization, no need to create here

            # ✅ Match Django: Log message
            log_message = f"Source {source_model_instance.name} connection established successfully"
            log_function(request, log_message, 'S', connection=connection.connection_id)
            trigger_initial_schema_listing_if_needed(request, connection)

        # ✅ Match Django: Final redirect to 'home'
        print(f"\n✅ SUCCESS - {dst_name} authorization completed!")
        print(f"   → Redirecting to home (Django: home)")
        # Django redirects to 'home' → React: '/dashboard/connectors' (if source_config_id) or '/dashboard/destinations' (if not)
        if source_config_id:
            return redirect('/dashboard/connectors')
        else:
            return redirect_destination_page()
    


