class ConnectionUsageChartAPIView(APIView):
    permission_classes = [IsAuthenticated, IsBillingOrAdmin]  # ✅ Only Admin and Billing roles

    """
    API endpoint to update connection usage stats for a given month and company.
    """

    def post(self, request, cmp_id):
        try:
            selected_year = int(request.data.get('selected_year', 0))
            selected_month = int(request.data.get('selected_month', 0))
        except ValueError:
            return Response({'message': 'Invalid year or month'}, status=status.HTTP_400_BAD_REQUEST)

        selected_connection_ids = request.data.get('connection_ids', '')
        if selected_connection_ids:
            if isinstance(selected_connection_ids, str):
                connection_ids_list = [cid for cid in selected_connection_ids.split(',') if cid.isdigit()]
                connection_ids = list(map(int, connection_ids_list))
            elif isinstance(selected_connection_ids, list):
                connection_ids = [int(cid) for cid in selected_connection_ids if isinstance(cid, int) or str(cid).isdigit()]
            else:
                connection_ids = []
        else:
            connection_ids = []

        # Query the data transfers
        data_transfers = Data_Transfer.objects.filter(
            start_time__year=selected_year,
            start_time__month=selected_month,
            connection__cmp_id=cmp_id,
            connection_id__in=connection_ids
        )


        # Compute daily totals
        days_in_month = calendar.monthrange(selected_year, selected_month)[1]
        daily_totals = {day: 0 for day in range(1, days_in_month + 1)}

        for transfer in data_transfers:
            daily_totals[transfer.start_time.day] += transfer.total_rec

        # Format response
        daily_labels = [str(day) for day in range(1, days_in_month + 1)]
        total_rec_values = [daily_totals[day] for day in range(1, days_in_month + 1)]

        return Response({
            'daily_labels': daily_labels,
            'total_rec': total_rec_values
        }, status=status.HTTP_200_OK)



class DeleteConnectionAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAdministrator]  # ✅ Only Admins can delete connections

    """
    DRF view to soft-delete a connection (mark as deleted).
    Blocked while any migration batch for this connection is on a pipeline canvas.
    """

    def delete(self, request, connection_id):
        connection = get_object_or_404(Connection, connection_id=connection_id)

        from apps.elttool.services.pipeline_batch_guards import (
            CONNECTION_BATCHES_IN_PIPELINE_DELETE_MSG,
            list_connection_pipeline_batch_usage,
        )

        pipeline_batches = list_connection_pipeline_batch_usage(connection)
        if pipeline_batches:
            summary = ", ".join(
                f"{row['batch_name']} ({row['pipeline_name']})"
                for row in pipeline_batches[:5]
            )
            if len(pipeline_batches) > 5:
                summary = f"{summary}, and {len(pipeline_batches) - 5} more"
            return Response(
                {
                    "message": CONNECTION_BATCHES_IN_PIPELINE_DELETE_MSG,
                    "batches_in_pipeline": pipeline_batches,
                    "detail": summary,
                },
                status=status.HTTP_400_BAD_REQUEST,
            )

        # Soft-delete
        connection.status = "D"
        connection.updated_by = request.user
        connection.save()

        # If this source config is no longer used by any non-deleted connection,
        # mark it inactive so its name can be reused.
        try:
            has_active_connections = Connection.objects.filter(
                src_config=connection.src_config
            ).exclude(status='D').exists()
            if not has_active_connections and connection.src_config:
                connection.src_config.is_active = False
                connection.src_config.save(update_fields=['is_active'])
        except Exception as deactivate_err:
            print(f"⚠️ Failed to update source config active state after connection delete: {deactivate_err}")

        # Log the deletion
        log_message = "Connection Deleted"
        log_function(request, log_message, 'S', connection_id)

        return Response(
            {"message": "Connection deleted successfully."},
            status=status.HTTP_204_NO_CONTENT
        )

    def get(self, request, connection_id):
        """
        Optional: Return connection details for confirmation before deletion.
        """
        # Optimize query with select_related to avoid N+1 queries
        connection = get_object_or_404(
            Connection.objects.select_related('src_config', 'dst_config'),
            connection_id=connection_id
        )
        data = {
            "connection_id": connection.connection_id,
            "src": connection.src_config.name,
            "dst": connection.dst_config.name,
            "status": connection.status,
            "cmp_id": request.user.cmp.cmp_id
        }
        return Response(data, status=status.HTTP_200_OK)
    



class FullConnectionDetailsAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ? Admin and Analyst only
    """
    GET /rest_api/full-connections/           → List all connection details
    GET /rest_api/full-connections/<id>/      → Get detail of specific connection
    """

    def get(self, request, connection_id=None):
        cmp_id = request.user.cmp.cmp_id

        if connection_id:
            # Optimize query with select_related to avoid N+1 queries
            connection = get_object_or_404(
                Connection.objects.select_related(
                    'src_config',
                    'src_config__src',
                    'dst_config',
                    'dst_config__dst'
                ),
                connection_id=connection_id,
                cmp_id=cmp_id
            )
            serializer = FullConnectionDetailsSerializer(connection)
            return HttpResponse(orjson.dumps(serializer.data), content_type="application/json")

        # Optimize query with select_related to avoid N+1 queries
        connections = Connection.objects.filter(cmp_id=cmp_id).select_related(
            'src_config',
            'src_config__src',
            'dst_config',
            'dst_config__dst'
        ).order_by('-updated_at')

        # Apply custom/global pagination

        paginator = CustomPagination()

        #  Paginate queryset
        page = paginator.paginate_queryset(connections, request)

        # Use paginated queryset if available
        if page is not None:
            serializer = FullConnectionDetailsSerializer(page, many=True)
            # Replicate CustomPagination logic for orjson
            response_data = {
                'content': serializer.data,
                'totalElements': paginator.page.paginator.count,
                'size': paginator.get_page_size(request)
            }
            return HttpResponse(orjson.dumps(response_data), content_type="application/json")

        # Fallback (if pagination not applied)
        serializer = FullConnectionDetailsSerializer(connections, many=True)
        return HttpResponse(orjson.dumps(serializer.data), content_type="application/json")

