class FetchSourceTablesAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ✅ Admin and Analyst can fetch tables

    def post(self, request, connection_id):
        # Optimize query with select_related to avoid N+1 queries
        connection = get_object_or_404(
            Connection.objects.select_related('src_config'),
            pk=connection_id
        )
        
        # ✅ Check if connection is paused
        if connection.status != "A":
            log_function(
                request,
                "Attempted to update schema while connection paused",
                "E",
                connection_id
            )
            return Response(
                {"message": "Connection is paused. Activate it to update schema."},
                status=status.HTTP_400_BAD_REQUEST
            )

        # ✅ NEW: Check if a listing_tables job is already in progress for this connection
        # This prevents multiple schema refresh jobs from being triggered simultaneously
        schema_refresh_in_progress = MigrationRecord.objects.filter(
            connection=connection,
            job_name__contains='listing_tables',
            status='in_progress'
        ).exists()
        print("##### Update schema in progress check",schema_refresh_in_progress)
        if schema_refresh_in_progress:
            log_function(
                request,
                "Update schema already in progress for this connection",
                "W",
                connection_id
            )
            return Response(
                {"message": "Update schema is already in progress. Please wait for it to complete."},
                status=status.HTTP_409_CONFLICT
            )

        status_code, result = fetch_tables_from_api(request, connection.src_config.src_config_id, connection.last_synced)

        if status_code != 200:
            return Response({
                "message": "Failed to fetch tables.",
                "error": result
            }, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

        return Response({
            "message": "Tables fetch initiated successfully.",
            "data": result
        }, status=status.HTTP_201_CREATED)


