# ===========================================================================================
# ✅ NEW IMPLEMENTATION - Split API for Better Performance
# Returns lightweight table list without fields, fields fetched separately on demand
# ===========================================================================================
import time
class ListSourceTablesAPIView(APIView):
    """
    Lightweight API endpoint to list tables for a connection.
    Returns only table names and basic metadata (no table_fields).
    
    GET /api/v1/connection/<connection_id>/tables/
    
    Query Parameters:
        - search: Optional search query to filter table names
    
    Returns:
        {
            "tables": [
                {
                    "table": "Account",
                    "selected": false,
                    "sequence": null,
                    "is_delta": false,
                    "delta_timestamp_field": null,
                    "truncate_data": false
                },
                ...
            ]
        }
    """
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ✅ Admin and Analyst can list tables

    def get(self, request, connection_id):
        start_time = time.perf_counter()  # ⏱️ START TIMER

        # ✅ OPTIMIZATION: Only fetch connection_id and src_config to minimize data transfer
        # select_related("src_config__src") is kept for validation but we use only() to limit fields
        # Note: src_config must be included in only() to allow select_related traversal
        connection = get_object_or_404(
            Connection.objects.only(
                "connection_id",
                "src_config",
                "dst_config",
                "src_config__src",
                "dst_config__dst",
            ).select_related("src_config__src", "dst_config__dst"),
            connection_id=connection_id,
        )

        search_query = request.query_params.get("search")
        include_unmapped = parse_bool_like(request.query_params.get("include_unmapped"), default=False)
        source_name = (
            getattr(getattr(connection, "src_config", None), "src", None).name
            if getattr(getattr(connection, "src_config", None), "src", None)
            else ""
        )
        destination_name = (
            getattr(getattr(connection, "dst_config", None), "dst", None).name
            if getattr(getattr(connection, "dst_config", None), "dst", None)
            else ""
        )
        # ✅ OPTIMIZATION: Use values() to exclude heavy JSONField (table_fields)
        # This prevents loading 1600 large JSON objects into memory
        FILE_BASED_SOURCES = {"AmazonS3", "SFTP","GoogleDrive","AzureDataLakeStorage"}
        base_qs = SourceTableSelection.objects.filter(connection_id=connection_id)
        if source_name in FILE_BASED_SOURCES and not include_unmapped:
            base_qs = base_qs.filter(is_mapping_checked=True)

        fields_to_select = [
            "table",
            "selected",
            "is_mapping_checked",
            "sequence",
            "is_delta",
            "delta_timestamp_field",
            "truncate_data",
        ]

        # SAP lifecycle fields are needed by both SAP destinations.
        if source_name == "SAPOData":
            sap_lifecycle_fields = [
                "service_name",
                "load_method",
                "first_sync_timestamp",
                "initial_completed_flag",
                "load_method_locked",
                "last_delta_run_timestamp",
            ]
            fields_to_select.extend(sap_lifecycle_fields)

            # File/export settings are only relevant to SAP -> ADLS.
            if destination_name in {"AzureDataLakeStorage", "ADLS"}:
                fields_to_select.extend([
                    "output_file_name",
                    "partition_delta_by_date",
                    "file_format",
                    "compression_method",
                    "delete_and_load",
                ])

        tables_qs = base_qs.values(*fields_to_select).order_by("table")

        if search_query:
            tables_qs = tables_qs.filter(table__icontains=search_query)

        # PgBouncer uses transaction pooling; PostgreSQL server-side cursors from
        # QuerySet.iterator() are invalid across pooled server connections (500 on
        # /connection/<id>/tables/ for large connections). values() already excludes
        # heavy table_fields JSON, so materializing rows here is safe.
        data = []
        for table_dict in tables_qs:
            row = dict(table_dict)
            # JSON clients expect a real boolean (MySQL/Django may expose 0/1).
            row["selected"] = bool(row.get("selected"))
            data.append(row)

        if source_name == "SAPOData" and data:
            from django.db.models import BooleanField, Case, Value, When
            from django.db.utils import ProgrammingError

            from apps.elttool.models import EntityTransform
            from apps.elttool.services.entity_transform_service import (
                serialize_transform_summary_flags,
            )

            empty_summary = serialize_transform_summary_flags()
            try:
                active_transforms = EntityTransform.objects.filter(
                    connection_id=connection_id,
                    is_active=True,
                ).annotate(
                    has_mapping=Case(
                        When(mapping_json__isnull=False, then=Value(True)),
                        default=Value(False),
                        output_field=BooleanField(),
                    ),
                    has_script=Case(
                        When(script_text__isnull=True, then=Value(False)),
                        When(script_text="", then=Value(False)),
                        default=Value(True),
                        output_field=BooleanField(),
                    ),
                ).values(
                    "table_name",
                    "version",
                    "has_mapping",
                    "has_script",
                    "entry_point",
                    "run_order",
                    "destination_table_name",
                    "destination_name_source",
                    "json_table_name",
                )
                transform_by_table = {t["table_name"]: t for t in active_transforms}
            except ProgrammingError:
                logger.warning(
                    "[ListSourceTablesAPIView] entity_transform table missing; "
                    "skipping transform_summary for connection_id=%s",
                    connection_id,
                )
                transform_by_table = {}
            except Exception:
                logger.exception(
                    "[ListSourceTablesAPIView] failed to load transform summaries"
                )
                transform_by_table = {}

            for row in data:
                tmeta = transform_by_table.get(row.get("table"))
                if tmeta:
                    row["transform_summary"] = serialize_transform_summary_flags(
                        version=tmeta.get("version"),
                        has_mapping=bool(tmeta.get("has_mapping")),
                        has_script=bool(tmeta.get("has_script")),
                        entry_point=tmeta.get("entry_point"),
                        run_order=tmeta.get("run_order"),
                        destination_table_name=tmeta.get("destination_table_name"),
                        destination_name_source=tmeta.get("destination_name_source"),
                        json_table_name=tmeta.get("json_table_name"),
                    )
                else:
                    row["transform_summary"] = empty_summary

        if settings.DEBUG:
            logger.debug(
                "[ListSourceTablesAPIView] connection_id=%s count=%s search=%s",
                connection_id,
                len(data),
                search_query,
            )
        total_time = time.perf_counter() - start_time  # ⏱️ END TIMER

        logger.info(
            "[ListSourceTablesAPIView] connection_id=%s count=%s search=%s time=%.3f sec",
            connection_id,
            len(data),
            search_query,
            total_time,
        )

        # ✅ OPTIMIZATION: Use orjson for blazing fast serialization (10x faster than DRF/json)
        # This solves the "Serializing 1670 tables to JSON is slow" issue
        json_bytes = orjson.dumps({
            "tables": data,
            "pagination_limit": 50  # Recommended items per page for frontend pagination
        })
        return HttpResponse(json_bytes, content_type="application/json")


class TableFieldsDetailAPIView(APIView):
    """
    API endpoint to get detailed field information for a specific table.
    Called when user clicks the arrow to expand table fields.
    
    GET /api/v1/connection/<connection_id>/tables/<table_name>/fields/
    
    Returns:
        {
            "table": "Account",
            "table_fields": {
                "Id": {"data_type": "ID", "is_primary_key": true},
                "Name": {"data_type": "STRING", "is_primary_key": false},
                ...
            },
            "primary_keys": ["Id"]
        }
    """
    permission_classes = [IsAuthenticated]

    def get(self, request, connection_id, table_name):
        total_start = time.perf_counter()  # ⏱️ TOTAL TIMER
        connection = get_object_or_404(
            Connection.objects.select_related("src_config__src"),
            connection_id=connection_id,
        )
        # =========================
        # ⏱️ DB TIME START
        # =========================
        db_start = time.perf_counter()

        table = get_object_or_404(
            SourceTableSelection.objects.filter(
                connection_id=connection_id,
                table__iexact=table_name,
            )
        )

        db_time = time.perf_counter() - db_start
        # =========================
        # ⏱️ DB TIME END
        # =========================

        # Cache the warehouse source check once per request
        is_warehouse_source = (
            connection.src_config
            and connection.src_config.src
            and connection.src_config.src.name in ("Snowflake", "Databricks")
        )
        is_sap_odata = (
            connection.src_config
            and connection.src_config.src
            and connection.src_config.src.name == "SAPOData"
        )

        # =========================
        # ⏱️ PARSE TIME START
        # =========================
        parse_start = time.perf_counter()

        def _parse_table_fields(raw_fields):
            """
            Parse table_fields without changing the shape of the existing response.
            Supports dict / JSON string / list while keeping backwards compatibility.
            Preserves column order using ordinal_position if available.
            """
            if isinstance(raw_fields, dict):
                parsed = raw_fields
            elif isinstance(raw_fields, str):
                try:
                    parsed = json.loads(raw_fields or "{}")
                except json.JSONDecodeError:
                    parsed = {}
            elif isinstance(raw_fields, list):
                parsed = {field: "VARCHAR(255)" for field in raw_fields}
            else:
                parsed = {}

            # Sort by ordinal_position if available to preserve original column order
            # PostgreSQL JSONB does not preserve key order, so we use ordinal_position
            if parsed:
                has_ordinal = any(
                    isinstance(v, dict) and v.get("ordinal_position") is not None
                    for v in parsed.values()
                )
                if has_ordinal:
                    sorted_items = sorted(
                        parsed.items(),
                        key=lambda x: _ordinal_position_sort_key(x[1]),
                    )
                    parsed = dict(sorted_items)

            if is_warehouse_source and parsed:
                formatted = {}
                for field_name, field_details in parsed.items():
                    if isinstance(field_details, dict):
                        data_type = field_details.get("data_type", "Unknown")
                        is_primary_key = field_details.get("is_primary_key", False)
                        ordinal_position = field_details.get("ordinal_position")
                    else:
                        data_type = "Unknown"
                        is_primary_key = False
                        ordinal_position = None
                    formatted[field_name] = {
                        "data_type": data_type,
                        "is_primary_key": is_primary_key,
                        "ordinal_position": ordinal_position,
                    }
                return formatted
            if is_sap_odata and parsed:
                formatted = {}
                for field_name, field_details in parsed.items():
                    if isinstance(field_details, dict):
                        data_type = field_details.get("data_type", "Unknown")
                        is_primary_key = field_details.get("is_primary_key", False)
                        edm_type = field_details.get("edm_type")
                        filterable = field_details.get("filterable", True)
                        filter_restriction = field_details.get("filter_restriction")
                        display_format = field_details.get("display_format")
                        precision = field_details.get("precision")
                    else:
                        data_type = "Unknown"
                        is_primary_key = False
                        edm_type = None
                        filterable = True
                        filter_restriction = None
                        display_format = None
                        precision = None
                    formatted[field_name] = {
                        "data_type": data_type,
                        "is_primary_key": is_primary_key,
                        "edm_type": edm_type,
                        "filterable": filterable,
                        "filter_restriction": filter_restriction,
                        "display_format": display_format,
                        "precision": precision,
                    }
                return formatted
            return parsed

        parsed_fields = _parse_table_fields(table.table_fields)
        parse_time = time.perf_counter() - parse_start
        # =========================
        # ⏱️ PARSE TIME END
        # =========================
        stored_primary_keys = getattr(table, "primary_keys", None) or []
        derived_primary_keys = [
            field_name
            for field_name, meta in (parsed_fields or {}).items()
            if isinstance(meta, dict) and meta.get("is_primary_key")
        ]
        primary_keys = stored_primary_keys or derived_primary_keys

        total_time = time.perf_counter() - total_start

        # =========================
        # 📊 STRUCTURED LOG
        # =========================
        logger.info(
            "[TableFieldsDetailAPIView] conn=%s table=%s fields=%s db=%.3f sec parse=%.3f sec total=%.3f sec",
            connection_id,
            table_name,
            len(parsed_fields or {}),
            db_time,
            parse_time,
            total_time,
        )

        return HttpResponse(orjson.dumps({
            "table": table.table,
            "table_fields": parsed_fields,
            "primary_keys": primary_keys,
            "selected_fields": table.selected_fields or [],
            "excel_sheet_name": table.excel_sheet_name,
            "excel_options": table.excel_options or {},
            "excel_conditional_formats": table.excel_conditional_formats or [],
            _NOTIFICATION_EMAIL_GROUP_IDS_FIELD: table.notification_email_group_ids or [],
            "email_custom_fields": table.email_custom_fields or {},
        }), content_type="application/json")

    def patch(self, request, connection_id, table_name):
        connection = get_object_or_404(
            Connection.objects.select_related("src_config__src"),
            connection_id=connection_id,
        )
        table = get_object_or_404(
            SourceTableSelection.objects.filter(connection_id=connection_id),
            table=table_name
        )

        incoming = request.data if isinstance(request.data, dict) else {}
        allowed_fields = (
            "table_fields",
            "selected_fields",
            "primary_keys",
            "delta_timestamp_field",
            "truncate_data",
            "combination_formula",
            "is_delta",
        )
        update_fields = []

        for field_name in allowed_fields:
            if field_name not in incoming:
                continue

            value = incoming.get(field_name)

            if field_name == "selected_fields":
                if value is None:
                    value = []
                if not isinstance(value, list):
                    return Response({"detail": "selected_fields must be a list."}, status=400)

                normalized_selected_fields = [str(col).strip() for col in value if str(col).strip()]
                table_fields = table.table_fields
                if not isinstance(table_fields, dict):
                    table_fields = safe_parse_json(table_fields, default={}, field_name="table_fields")
                if not isinstance(table_fields, dict):
                    table_fields = {}

                selected_upper = {col.upper() for col in normalized_selected_fields}
                filtered_table_fields = {
                    col_name: meta
                    for col_name, meta in table_fields.items()
                    if str(col_name).strip().upper() in selected_upper
                }

                # Preserve requested order when metadata exists for the field.
                ordered_table_fields = {}
                for col_name in normalized_selected_fields:
                    for existing_name, meta in filtered_table_fields.items():
                        if str(existing_name).strip().upper() == col_name.upper():
                            ordered_table_fields[existing_name] = meta
                            break

                table.table_fields = ordered_table_fields
                update_fields.append("table_fields")

                existing_primary_keys = getattr(table, "primary_keys", None) or []
                filtered_primary_keys = [
                    pk for pk in existing_primary_keys
                    if str(pk).strip().upper() in selected_upper
                ]
                table.primary_keys = filtered_primary_keys
                if "primary_keys" not in update_fields:
                    update_fields.append("primary_keys")
                continue

            if field_name == "primary_keys":
                if value is None:
                    value = []
                if not isinstance(value, list):
                    return Response({"detail": "primary_keys must be a list."}, status=400)

                normalized_pk_list = [str(col).strip() for col in value if str(col).strip()]
                table.primary_keys = normalized_pk_list
                update_fields.append("primary_keys")

                table_fields = table.table_fields
                if not isinstance(table_fields, dict):
                    table_fields = safe_parse_json(table_fields, default={}, field_name="table_fields")
                if not isinstance(table_fields, dict):
                    table_fields = {}

                pk_upper = {col.upper() for col in normalized_pk_list}
                for col_name, meta in table_fields.items():
                    if isinstance(meta, dict):
                        meta["is_primary_key"] = str(col_name).strip().upper() in pk_upper

                table.table_fields = table_fields
                if "table_fields" not in update_fields:
                    update_fields.append("table_fields")
                continue

            if field_name == "table_fields":
                if not isinstance(value, (dict, list, str)):
                    return Response({"detail": "table_fields must be a dict, list, or JSON string."}, status=400)
                table.table_fields = value
                update_fields.append("table_fields")
                continue

            if field_name == "truncate_data":
                table.truncate_data = bool(value)
                update_fields.append("truncate_data")
                continue

            if field_name == "is_delta":
                table.is_delta = bool(value)
                update_fields.append("is_delta")
                continue

            if field_name == "delta_timestamp_field":
                table.delta_timestamp_field = str(value).strip() if value else None
                update_fields.append("delta_timestamp_field")
                continue

            if field_name == "combination_formula":
                table.combination_formula = str(value).strip() if value else None
                update_fields.append("combination_formula")

        if not update_fields:
            return Response({"detail": "No valid fields provided for update."}, status=400)

        table.save(update_fields=list(dict.fromkeys(update_fields)))

        is_snowflake = (
            connection.src_config
            and connection.src_config.src
            and connection.src_config.src.name == "Snowflake"
        )

        if isinstance(table.table_fields, dict):
            parsed_fields = table.table_fields
        elif isinstance(table.table_fields, str):
            try:
                parsed_fields = json.loads(table.table_fields or "{}")
            except json.JSONDecodeError:
                parsed_fields = {}
        elif isinstance(table.table_fields, list):
            parsed_fields = {field: "VARCHAR(255)" for field in table.table_fields}
        else:
            parsed_fields = {}

        if is_snowflake and parsed_fields:
            formatted = {}
            for field_name, field_details in parsed_fields.items():
                if isinstance(field_details, dict):
                    data_type = field_details.get("data_type", "Unknown")
                    is_primary_key = field_details.get("is_primary_key", False)
                else:
                    data_type = "Unknown"
                    is_primary_key = False
                formatted[field_name] = {
                    "data_type": data_type,
                    "is_primary_key": is_primary_key,
                }
            parsed_fields = formatted

        stored_primary_keys = getattr(table, "primary_keys", None) or []
        derived_primary_keys = [
            field_name
            for field_name, meta in (parsed_fields or {}).items()
            if isinstance(meta, dict) and meta.get("is_primary_key")
        ]
        primary_keys = stored_primary_keys or derived_primary_keys

        return Response({
            "table": table.table,
            "table_fields": parsed_fields,
            "primary_keys": primary_keys,
            "delta_timestamp_field": table.delta_timestamp_field,
            "truncate_data": table.truncate_data,
            "combination_formula": table.combination_formula,
            "is_delta": table.is_delta,
        }, status=200)


