class UpdateTableSftpFieldsAPIView(APIView):
    """
    Save the selected export fields (and their order) for a single table on
    a file-based destination such as SFTP or SharePoint.
    Called on every drag-and-drop reorder or field toggle in the UI.

    PATCH /api/v1/connection/<connection_id>/tables/<table_name>/sftp-fields/
    Body:
        { "selected_fields": ["COL_A", "COL_C", "COL_B"] }
        Pass [] or null to reset to "export all fields" (default).
    """
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]

    def patch(self, request, connection_id, table_name):
        try:
            connection = Connection.objects.get(
                connection_id=connection_id,
                cmp=request.user.cmp
            )
        except Connection.DoesNotExist:
            return create_error_response("Connection not found", status_code=status.HTTP_404_NOT_FOUND)

        try:
            table_record = SourceTableSelection.objects.get(
                connection=connection,
                table=table_name
            )
        except SourceTableSelection.DoesNotExist:
            return create_error_response(
                f"Table '{table_name}' not found for this connection",
                status_code=status.HTTP_404_NOT_FOUND
            )

        raw = request.data.get("selected_fields")

        if raw is None or raw == []:
            table_record.selected_fields = None  # null = export all fields
        elif isinstance(raw, list):
            if not all(isinstance(f, str) and f.strip() for f in raw):
                return create_error_response("selected_fields must be a list of non-empty strings")
            table_record.selected_fields = raw
        else:
            return create_error_response("selected_fields must be a list or null")

        table_record.save(update_fields=["selected_fields"])

        return Response({
            "table": table_name,
            "selected_fields": table_record.selected_fields or [],
        }, status=status.HTTP_200_OK)


class UpdateTableNotificationEmailGroupsAPIView(APIView):
    """
    Save the selected notification email groups for a single supported file-based table.

    PATCH /api/v1/connection/<connection_id>/tables/<table_name>/email-groups/
    Body:
        { "notification_email_group_ids": [1, 2] }
        Pass [] or null to clear the table's selected email groups.
    """

    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]

    def patch(self, request, connection_id, table_name):
        try:
            connection = Connection.objects.select_related(
                "src_config__src",
                "dst_config__dst",
            ).get(
                connection_id=connection_id,
                cmp=request.user.cmp,
            )
        except Connection.DoesNotExist:
            return create_error_response(
                "Connection not found",
                status_code=status.HTTP_404_NOT_FOUND,
            )

        destination_name = getattr(
            getattr(getattr(connection, "dst_config", None), "dst", None),
            "name",
            None,
        )
        if not _supports_notification_groups(destination_name):
            return create_error_response(
                f"{_NOTIFICATION_EMAIL_GROUP_IDS_FIELD} is not supported for this destination"
            )

        try:
            table_record = SourceTableSelection.objects.get(
                connection=connection,
                table=table_name,
            )
        except SourceTableSelection.DoesNotExist:
            return create_error_response(
                f"Table '{table_name}' not found for this connection",
                status_code=status.HTTP_404_NOT_FOUND,
            )

        try:
            normalized_group_ids = _validate_company_email_group_ids(
                connection.cmp,
                request.data.get(_NOTIFICATION_EMAIL_GROUP_IDS_FIELD),
            )
        except ValueError as exc:
            return create_error_response(str(exc))

        if "email_custom_fields" in request.data:
            try:
                table_record.email_custom_fields = _merge_email_custom_fields(
                    table_record.email_custom_fields,
                    request.data.get("email_custom_fields"),
                )
            except ValueError as exc:
                return create_error_response(str(exc))
        if "email_template_id" in request.data:
            raw_template_id = request.data.get("email_template_id")
            if raw_template_id in (None, ""):
                table_record.email_template = None
            else:
                try:
                    template_id = int(raw_template_id)
                except (TypeError, ValueError):
                    return create_error_response("email_template_id must be an integer")
                try:
                    table_record.email_template = EmailTemplate.objects.get(
                        id=template_id,
                        cmp=connection.cmp,
                    )
                except EmailTemplate.DoesNotExist:
                    return create_error_response(
                        "email_template_id was not found for this company",
                        status_code=status.HTTP_404_NOT_FOUND,
                    )

        table_record.notification_email_group_ids = normalized_group_ids
        table_record.updated_by_id = getattr(request.user, "user_id", None)
        update_fields = ["notification_email_group_ids", "updated_by_id"]
        if "email_custom_fields" in request.data:
            update_fields.append("email_custom_fields")
        if "email_template_id" in request.data:
            update_fields.append("email_template")
        table_record.save(update_fields=update_fields)

        selected_template = table_record.email_template

        return Response(
            {
                "table": table_name,
                **_build_company_email_group_payload(
                    connection.cmp,
                    normalized_group_ids,
                ),
                "email_custom_fields": table_record.email_custom_fields or {},
                "email_template_id": selected_template.id if selected_template else None,
                "email_template": (
                    EmailTemplateSerializer(selected_template).data
                    if selected_template else None
                ),
            },
            status=status.HTTP_200_OK,
        )



class UpdateTableExportSettingsAPIView(APIView):
    """
    Save file export settings for a single file-based table.

    PATCH /api/v1/connection/<connection_id>/tables/<table_name>/export-settings/
    PUT   /api/v1/connection/<connection_id>/tables/<table_name>/export-settings/
    """

    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]

    def _save_settings(self, request, connection_id, table_name):
        try:
            connection = Connection.objects.select_related("dst_config__dst").get(
                connection_id=connection_id,
                cmp=request.user.cmp,
            )
        except Connection.DoesNotExist:
            return create_error_response(
                "Connection not found",
                status_code=status.HTTP_404_NOT_FOUND,
            )

        destination_name = getattr(
            getattr(getattr(connection, "dst_config", None), "dst", None),
            "name",
            None,
        )
        is_sap_odata = (
            connection.src_config and connection.src_config.src and connection.src_config.src.name == "SAPOData"
        )
        if not is_sap_odata and not _is_file_based_destination(destination_name):
            return create_error_response(
                "Export settings are supported for file-based destinations only"
            )

        try:
            table_record = SourceTableSelection.objects.get(
                connection=connection,
                table=table_name,
            )
        except SourceTableSelection.DoesNotExist:
            return create_error_response(
                f"Table '{table_name}' not found for this connection",
                status_code=status.HTTP_404_NOT_FOUND,
            )

        if not isinstance(request.data, dict):
            return create_error_response("Request body must be an object/dict")

        if is_sap_odata:
            settings_obj = dict(request.data)
            if "load_method" in settings_obj:
                requested_load_method = settings_obj.get("load_method")
            else:
                requested_load_method = table_record.load_method or "initial"

            if "partition_delta_by_date" in settings_obj:
                partition_delta_by_date = bool(settings_obj.get("partition_delta_by_date"))
            else:
                partition_delta_by_date = bool(table_record.partition_delta_by_date)

            if "compression_method" in settings_obj:
                compression_method = settings_obj.get("compression_method") or "none"
            else:
                compression_method = table_record.compression_method or "none"

            if "output_file_name" in settings_obj:
                output_file_name = settings_obj.get("output_file_name")
            else:
                output_file_name = table_record.output_file_name

            if "file_format" in settings_obj:
                file_format = settings_obj.get("file_format") or "parquet"
            else:
                file_format = table_record.file_format or "parquet"
            
            # delete_and_load is stored as a BooleanField in DB.
            # It accepts True, False, or None. Default is None.
            if "delete_and_load" in settings_obj:
                raw_delete_and_load = settings_obj.get("delete_and_load")
                if raw_delete_and_load is not None:
                    delete_and_load = bool(raw_delete_and_load)
                else:
                    delete_and_load = None
            else:
                delete_and_load = table_record.delete_and_load

            # Validate load_method — accept both canonical values and the frontend alias.
            # 'initial_delta' is the DB / pipeline value; 'delta' maps to DELTA_ONLY.
            valid_load_methods = ("initial", "initial_delta", "delta")
            if requested_load_method and requested_load_method not in valid_load_methods:
                return create_error_response(
                    "Invalid load_method; expected one of: initial, initial_delta, delta"
                )
            if compression_method and compression_method not in ("none", "gzip", "snappy"):
                return create_error_response("Invalid compression_method; expected none, gzip, or snappy")

            # ── Load-method lock guard ─────────────────────────────────────────
            # Once delta tracking has started (INITIAL_DELTA or DELTA_ONLY first run
            # committed), load_method_locked is set to True by the pipeline.
            # When locked, ignore the incoming load_method and preserve the stored value
            # so that the active delta token and sync timestamps remain consistent.
            if table_record.load_method_locked:
                logger.info(
                    "[UpdateTableExportSettings] load_method is locked for table '%s'; "
                    "ignoring incoming load_method='%s', keeping stored='%s'",
                    table_name, requested_load_method, table_record.load_method,
                )
                load_method = table_record.load_method  # preserve locked value
            else:
                load_method = requested_load_method

            # Parse row_filter_config from payload
            row_filter_in_payload = "row_filter_config" in settings_obj
            row_filter_val = settings_obj.get("row_filter_config")

            save_row_filter = False
            if row_filter_in_payload:
                if row_filter_val is not None:
                    if isinstance(row_filter_val, str):
                        try:
                            row_filter_val = json.loads(row_filter_val)
                        except Exception:
                            pass
                    
                    try:
                        from .utils import validate_sap_row_filter_dict
                        if isinstance(table_record.table_fields, dict):
                            raw_schema = table_record.table_fields
                        elif isinstance(table_record.table_fields, str):
                            try:
                                raw_schema = json.loads(table_record.table_fields or "{}")
                            except Exception:
                                raw_schema = {}
                        else:
                            raw_schema = {}

                        row_filter_val = validate_sap_row_filter_dict(row_filter_val, raw_schema)
                    except Exception as err:
                        return create_error_response(f"Row filter validation failed: {str(err)}")

                    if table_record.load_method_locked and table_record.row_filter_config != row_filter_val:
                        delete_and_load = True

                    table_record.row_filter_config = row_filter_val
                else:
                    # Clearing filter
                    if table_record.load_method_locked and table_record.row_filter_config is not None:
                        delete_and_load = True
                    table_record.row_filter_config = None
                save_row_filter = True

            table_record.output_file_name = output_file_name
            table_record.load_method = load_method
            table_record.partition_delta_by_date = bool(partition_delta_by_date)
            table_record.file_format = file_format
            table_record.compression_method = compression_method
            # delete_and_load only applies to INITIAL load method.
            table_record.delete_and_load = delete_and_load if load_method == "initial" else None
            table_record.updated_by_id = getattr(request.user, "user_id", None)
            
            update_fields = [
                "output_file_name",
                "load_method",
                "partition_delta_by_date",
                "file_format",
                "compression_method",
                "delete_and_load",
                "updated_by_id",
            ]
            if save_row_filter:
                update_fields.append("row_filter_config")
                
            table_record.save(update_fields=update_fields)

            return Response({
                "success": True,
                "message": f"Export settings for table '{table_name}' updated successfully.",
                "table": table_name,
                "output_file_name": table_record.output_file_name,
                "load_method": table_record.load_method,
                "load_method_locked": bool(table_record.load_method_locked),
                "partition_delta_by_date": table_record.partition_delta_by_date,
                "file_format": table_record.file_format,
                "compression_method": table_record.compression_method,
                "delete_and_load": table_record.delete_and_load,
                "row_filter_config": table_record.row_filter_config,
            }, status=status.HTTP_200_OK)

        settings_obj = dict(request.data)
        raw_group_ids = settings_obj.get(_NOTIFICATION_EMAIL_GROUP_IDS_FIELD)
        if raw_group_ids not in (None, "", []):
            if not _supports_notification_groups(destination_name):
                return create_error_response(
                    f"{_NOTIFICATION_EMAIL_GROUP_IDS_FIELD} is not supported for this destination"
                )
            try:
                settings_obj[_NOTIFICATION_EMAIL_GROUP_IDS_FIELD] = _validate_company_email_group_ids(
                    connection.cmp,
                    raw_group_ids,
                )
            except ValueError as exc:
                return create_error_response(str(exc))
        elif _NOTIFICATION_EMAIL_GROUP_IDS_FIELD in settings_obj:
            settings_obj[_NOTIFICATION_EMAIL_GROUP_IDS_FIELD] = []

        try:
            _apply_file_export_settings_to_table_record(table_record, settings_obj)
        except ValueError as exc:
            return create_error_response(str(exc))

        effective_settings = _get_effective_file_export_settings(table_record) or {}
        current_file_format = effective_settings.get("file_format")
        current_csv_delimiter = effective_settings.get("csv_delimiter")
        current_csv_quote_char = effective_settings.get("csv_quote_char")

        if current_file_format and current_file_format not in ("csv", "json", "parquet", "excel"):
            return create_error_response(
                f"Invalid file_format for table '{table_name}'; expected csv, json, parquet, or excel"
            )

        allowed_escapes = ("\\t", "\\r", "\\n", "\\s", "\\\\t", "\\\\r", "\\\\n", "\\\\s")
        if current_csv_delimiter and len(str(current_csv_delimiter)) != 1:
            if str(current_csv_delimiter) not in allowed_escapes:
                return create_error_response(
                    f"csv_delimiter must be 1 character or a common escape sequence (\\t, \\r, \\n) for table '{table_name}'"
                )

        if current_csv_quote_char and len(str(current_csv_quote_char)) != 1:
            if str(current_csv_quote_char) not in allowed_escapes:
                return create_error_response(
                    f"csv_quote_char must be 1 character for table '{table_name}'"
                )

        table_record.updated_by_id = getattr(request.user, "user_id", None)
        table_record.save(
            update_fields=[
                "output_file_name",
                "target_folder",
                "file_format",
                "csv_delimiter",
                "csv_quote_char",
                "excel_sheet_name",
                "excel_options",
                "excel_conditional_formats",
                "add_utc_timestamp",
                "filename_date_format",
                "notification_email_group_ids",
                "email_custom_fields",
                "email_template",
                "updated_by_id",
            ]
        )

        response_payload = {
            "success": True,
            "message": f"Export settings for table '{table_name}' updated successfully.",
            "table": table_name,
            **(_get_effective_file_export_settings(table_record) or {}),
        }
        if _supports_notification_groups(destination_name):
            response_payload.update(
                _build_company_email_group_payload(
                    connection.cmp,
                    table_record.notification_email_group_ids or [],
                )
            )
        else:
            response_payload[_NOTIFICATION_EMAIL_GROUP_IDS_FIELD] = []
        return Response(response_payload, status=status.HTTP_200_OK)

    def patch(self, request, connection_id, table_name):
        return self._save_settings(request, connection_id, table_name)

    def put(self, request, connection_id, table_name):
        return self._save_settings(request, connection_id, table_name)


class DeleteDeltaTableAPIView(APIView):
    """Reset SAP OData initial/delta state for one table."""

    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]

    def post(self, request):
        connection_id = request.data.get("connection_id")
        table_name = request.data.get("table_name")
        if not connection_id or not table_name:
            return Response(
                {"success": False, "message": "connection_id and table_name are required."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            connection = Connection.objects.get(
                connection_id=connection_id,
                cmp=request.user.cmp,
            )
        except Connection.DoesNotExist:
            return Response(
                {"success": False, "message": "Connection not found."},
                status=status.HTTP_404_NOT_FOUND,
            )

        source_name = getattr(
            getattr(getattr(connection, "src_config", None), "src", None),
            "name",
            None,
        )
        if source_name != "SAPOData":
            return Response(
                {"success": False, "message": "Delta state reset is supported only for SAP OData."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            table_record = SourceTableSelection.objects.get(
                connection_id=connection_id,
                table=table_name,
            )
        except SourceTableSelection.DoesNotExist:
            return Response(
                {"success": False, "message": f"Table '{table_name}' not found for this connection."},
                status=status.HTTP_404_NOT_FOUND,
            )

        if table_record.status == "in_progress":
            return Response(
                {
                    "success": False,
                    "message": (
                        f"Table '{table_name}' is currently syncing. "
                        "Please wait for the active run to complete before resetting."
                    ),
                },
                status=status.HTTP_400_BAD_REQUEST,
            )

        table_record.delta_token = None
        table_record.first_sync_timestamp = None
        table_record.initial_completed_flag = False
        table_record.load_method_locked = False
        table_record.last_delta_run_timestamp = None
        table_record.status = None
        table_record.save(update_fields=[
            "delta_token",
            "first_sync_timestamp",
            "initial_completed_flag",
            "load_method_locked",
            "last_delta_run_timestamp",
            "status",
        ])

        return Response(
            {
                "success": True,
                "message": (
                    f"Delta state for '{table_name}' has been reset successfully. "
                    "The load method is now unlocked."
                ),
            },
            status=status.HTTP_200_OK,
        )


class UpdateSourceTableSelectionAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ✅ Admin and Analyst can update table selection  # Removed CheckTrialPeriod

    """API to update table selection for a connection.

    This endpoint is generic for any connection source and can be used for
    Google Drive connections as well as S3, databases, and other sources.
    """

    def _calculate_table_changes(self, connection_id, new_selected_tables):
        """
        Calculate detailed changes between current and new table selection
        Returns list of changes to be logged in audit table
        """
        from apps.elttool.models import SourceTableSelection, TableSelectionAudit
        
        # Get current state - ordered by sequence to maintain proper order
        current_selection = list(SourceTableSelection.objects.filter(
            connection_id=connection_id, selected=True
        ).order_by('sequence').values_list('table', 'sequence'))
        
        current_table_dict = {table: seq for table, seq in current_selection}
        current_tables_ordered = [table for table, seq in current_selection]
        
        # Identify truly added tables (not in current selection)
        added_tables = set(new_selected_tables) - set(current_table_dict.keys())
        
        # Identify tables that were removed
        removed_tables = set(current_table_dict.keys()) - set(new_selected_tables)
        
        # For remaining tables, check if there was actual reordering
        # (not just sequential renumbering due to add/remove operations)
        remaining_tables = set(current_table_dict.keys()) & set(new_selected_tables)
        
        # Get the order of remaining tables in both current and new selections
        current_remaining_order = [table for table in current_tables_ordered if table in remaining_tables]
        new_remaining_order = [table for table in new_selected_tables if table in remaining_tables]
        
        # Only consider it a reorder if the relative order of remaining tables changed
        reordered_tables = []
        if current_remaining_order != new_remaining_order:
            # Actual reordering occurred - find which tables moved
            for table in remaining_tables:
                old_pos = current_remaining_order.index(table) if table in current_remaining_order else -1
                new_pos = new_remaining_order.index(table) if table in new_remaining_order else -1
                if old_pos != new_pos and old_pos >= 0 and new_pos >= 0:
                    reordered_tables.append(table)
        
        changes = []
        
        # Find added tables
        for table in added_tables:
            changes.append({
                'action_type': 'ADD',
                'table_name': table,
                'old_sequence': None,
                'new_sequence': new_selected_tables.index(table) + 1,
                'old_selected': False,
                'new_selected': True
            })
        
        # Find removed tables
        for table in removed_tables:
            changes.append({
                'action_type': 'REMOVE',
                'table_name': table,
                'old_sequence': current_table_dict[table],
                'new_sequence': None,
                'old_selected': True,
                'new_selected': False
            })
        
        # Find reordered tables (only those that were actually moved)
        for table in reordered_tables:
            old_seq = current_table_dict[table]
            new_seq = new_selected_tables.index(table) + 1
            changes.append({
                'action_type': 'REORDER',
                'table_name': table,
                'old_sequence': old_seq,
                'new_sequence': new_seq,
                'old_selected': True,
                'new_selected': True
            })
        
        return changes

    def post(self, request, connection_id):
        selected_tables = request.data.get("selected_tables", [])
        truncate_flags = request.data.get("truncate_flags", {})  # {table: bool}
        table_export_settings = request.data.get("table_export_settings", {})  # {table: {file export settings}}

        if not isinstance(selected_tables, list):
            return create_error_response("selected_tables must be a list")
        if table_export_settings is not None and not isinstance(table_export_settings, dict):
            return create_error_response("table_export_settings must be an object/dict")

        try:
            connection = Connection.objects.get(
                connection_id=connection_id,
                cmp=request.user.cmp
            )
        except Connection.DoesNotExist:
            return create_error_response(
                "Connection not found",
                status_code=status.HTTP_404_NOT_FOUND
            )

        destination_name = getattr(getattr(getattr(connection, "dst_config", None), "dst", None), "name", None)
        supports_notification_groups = _supports_notification_groups(destination_name)

        normalized_table_export_settings = {}
        for table_name, settings_obj in (table_export_settings or {}).items():
            if not isinstance(settings_obj, dict):
                return create_error_response(f"table_export_settings['{table_name}'] must be an object/dict")

            normalized_settings_obj = dict(settings_obj)
            raw_group_ids = normalized_settings_obj.get(_NOTIFICATION_EMAIL_GROUP_IDS_FIELD)
            if raw_group_ids not in (None, "", []):
                if not supports_notification_groups:
                    return create_error_response(
                        f"{_NOTIFICATION_EMAIL_GROUP_IDS_FIELD} is not supported for this destination"
                    )
                try:
                    normalized_settings_obj[_NOTIFICATION_EMAIL_GROUP_IDS_FIELD] = _validate_company_email_group_ids(
                        connection.cmp,
                        raw_group_ids,
                    )
                except ValueError as exc:
                    return create_error_response(f"table_export_settings['{table_name}']: {str(exc)}")
            elif _NOTIFICATION_EMAIL_GROUP_IDS_FIELD in normalized_settings_obj:
                normalized_settings_obj[_NOTIFICATION_EMAIL_GROUP_IDS_FIELD] = []
            if normalized_settings_obj.get("email_template_id") not in (None, ""):
                try:
                    template_id = int(normalized_settings_obj["email_template_id"])
                except (TypeError, ValueError):
                    return create_error_response(
                        f"table_export_settings['{table_name}'].email_template_id must be an integer"
                    )
                if not EmailTemplate.objects.filter(id=template_id, cmp=connection.cmp).exists():
                    return create_error_response(
                        f"table_export_settings['{table_name}'].email_template_id was not found for this company",
                        status_code=status.HTTP_404_NOT_FOUND,
                    )
                normalized_settings_obj["email_template_id"] = template_id


            normalized_table_export_settings[table_name] = normalized_settings_obj

        # -------------------------------
        # Free plan check (MATCHES Django)
        # -------------------------------
        company = connection.cmp
        warning_message = None

        if company.plan == "Free":
            if len(selected_tables) > 10:
                selected_tables = selected_tables[:10]
                warning_message = (
                    "Free plan allows only 10 tables. "
                    "Only the first 10 tables have been saved."
                )

        # -------------------------------
        # Calculate detailed changes BEFORE updating
        # Use the actual order from the request
        # -------------------------------
        final_order = selected_tables
        changes_to_audit = self._calculate_table_changes(connection_id, final_order)

        # -------------------------------
        # Update selected tables with proper sequence
        # -------------------------------
        # Get existing settings to use as defaults for new tables
        template_record = SourceTableSelection.objects.filter(
            connection=connection,
            file_format__isnull=False,
        ).order_by('-added_on').first()

        for index, table_name in enumerate(final_order):
            table_record = SourceTableSelection.objects.filter(
                connection=connection,
                table=table_name
            ).first()

            if not table_record:
                continue

            table_record.selected = True
            table_record.sequence = index + 1  # ✅ Start from 1
            table_record.truncate_data = truncate_flags.get(table_name, False)
            if isinstance(normalized_table_export_settings, dict) and table_name in normalized_table_export_settings:
                settings_obj = normalized_table_export_settings.get(table_name) or {}
                try:
                    _apply_file_export_settings_to_table_record(table_record, settings_obj)
                except ValueError as exc:
                    return create_error_response(f"table_export_settings['{table_name}']: {str(exc)}")
            else:
                # If no settings provided in request, and it's a new selection or missing settings,
                # use defaults from template_record if available
                current_settings = _get_effective_file_export_settings(table_record)
                template_settings = _get_effective_file_export_settings(template_record) if template_record else None
                if template_settings and not current_settings:
                    _apply_file_export_settings_to_table_record(
                        table_record,
                        template_settings,
                        include_notification_groups=False,
                    )

            # Light validation (full validation can be stricter if you want)
            effective_settings = _get_effective_file_export_settings(table_record) or {}
            current_file_format = effective_settings.get("file_format")
            current_csv_delimiter = effective_settings.get("csv_delimiter")
            current_csv_quote_char = effective_settings.get("csv_quote_char")

            if current_file_format and current_file_format not in ("csv", "json", "parquet", "excel"):
                return create_error_response(
                    f"Invalid file_format for table '{table_name}'; expected csv, json, parquet, or excel"
                )
            # Allow \t, \r, \n, \s even if length > 1
            allowed_escapes = ("\\t", "\\r", "\\n", "\\s", "\\\\t", "\\\\r", "\\\\n", "\\\\s")
            if current_csv_delimiter and len(str(current_csv_delimiter)) != 1:
                if str(current_csv_delimiter) not in allowed_escapes:
                    return create_error_response(f"csv_delimiter must be 1 character or a common escape sequence (\\t, \\r, \\n) for table '{table_name}'")
            
            if current_csv_quote_char and len(str(current_csv_quote_char)) != 1:
                    if str(current_csv_quote_char) not in allowed_escapes:
                        return create_error_response(f"csv_quote_char must be 1 character for table '{table_name}'")
            table_record.updated_by_id = getattr(request.user, "user_id", None)
            table_record.save()

        # -------------------------------
        # Unselect tables not in list
        # -------------------------------
        if selected_tables:
            tables_to_unselect = SourceTableSelection.objects.filter(
                connection=connection,
                selected=True
            ).exclude(table__in=selected_tables)
        else:
            tables_to_unselect = SourceTableSelection.objects.filter(
                connection=connection,
                selected=True
            )

        removed_table_names = list(tables_to_unselect.values_list("table", flat=True))

        for table_record in tables_to_unselect:
            table_record.selected = False
            table_record.sequence = None
            table_record.status = None
            table_record.truncate_data = False
            table_record.output_file_name = None
            table_record.target_folder = None
            table_record.file_format = None
            table_record.csv_delimiter = None
            table_record.csv_quote_char = None
            table_record.excel_sheet_name = None
            table_record.excel_options = None
            table_record.excel_conditional_formats = []
            table_record.add_utc_timestamp = True
            table_record.filename_date_format = None
            table_record.selected_fields = None
            table_record.notification_email_group_ids = []
            table_record.updated_by_id = getattr(request.user, "user_id", None)
            table_record.save()

        # Keep S3/SFTP file/table mapping consistent with table selection changes.
        source_name = getattr(getattr(getattr(connection, "src_config", None), "src", None), "name", None)
        if removed_table_names and (is_amazon_s3_source(source_name) or is_sftp_source(source_name) or is_google_drive_source(source_name) or is_adls_source(source_name)):
            prune_s3_mapping_for_removed_tables(connection, removed_table_names)

        # -------------------------------
        # Reschedule job (MATCHES Django)
        # -------------------------------
        job_id = f"{request.user.cmp.cmp_id}_{connection_id}_{connection.src_config.name}"

        scheduler_warning = None
        try:
            job = SchedulerClient.get_job(job_id)
            if job:
                update_sync_frequency(
                    request,
                    connection_id,
                    connection.time_frequency,
                    connection.safety_interval,
                    connection.sync_start_date
                )
        except requests.exceptions.RequestException as scheduler_err:
            scheduler_warning = (
                "Table selection was saved, but scheduler sync could not be updated "
                f"because the scheduler service is unavailable: {scheduler_err}"
            )
            logger.warning(
                "[UpdateSourceTableSelectionAPIView] Scheduler unavailable for job lookup/reschedule | "
                "connection_id=%s job_id=%s error=%s",
                connection_id,
                job_id,
                scheduler_err,
            )

        # -------------------------------
        # Create main log entry FIRST
        # -------------------------------
        from apps.elttool.models import TableSelectionAudit
        
        main_log = Log.objects.create(
            message=f"Table selection updated: {len(final_order)} tables selected",
            cmp=request.user.cmp,
            user=request.user,
            connection_id=connection_id,
            status="S"
        )

        # -------------------------------
        # Create detailed audit records linked to the main log
        # -------------------------------
        for change in changes_to_audit:
            TableSelectionAudit.objects.create(
                connection_id=connection_id,
                log=main_log,  # 🔗 Link to main log
                action_type=change['action_type'],
                table_name=change['table_name'],
                old_sequence=change['old_sequence'],
                new_sequence=change['new_sequence'],
                old_selected=change['old_selected'],
                new_selected=change['new_selected'],
                changed_by=request.user
            )

        # -------------------------------
        # Response (UNCHANGED FORMAT)
        # -------------------------------
        response_data = {
            "message": "Table selection and order updated successfully.",
            "tables_saved": final_order
        }
        if scheduler_warning:
            response_data["warning"] = scheduler_warning

        # ✅ Trigger WebSocket update for connection_table_status
        try:
            from apps.elttool.services.connection_table_status_builder import build_connection_table_status
            from apps.elttool.websocket.ws_utils import push_connection_table_status_update

            data, error = build_connection_table_status(connection_id)
            if not error:
                push_connection_table_status_update(connection_id, data)
                logger.info(f"🔔 WS push triggered for connection_id={connection_id} (table selection update)")
        except Exception as ws_err:
            logger.warning(f"⚠️ WS push failed in UpdateSourceTableSelectionAPIView: {ws_err}")

        if warning_message:
            response_data["warning"] = warning_message

        return Response(response_data, status=status.HTTP_200_OK)

class TableSelectionHistoryAPIView(APIView):
    permission_classes = [IsAuthenticated]
    
    def get(self, request, connection_id):
        """
        Get detailed history of table selection changes for a connection
        Returns logs with their associated detailed audit records
        """
        from apps.elttool.models import TableSelectionAudit
        
        # Validate connection exists and user has access
        try:
            connection = Connection.objects.get(
                connection_id=connection_id,
                cmp=request.user.cmp
            )
        except Connection.DoesNotExist:
            return create_error_response(
                "Connection not found",
                status_code=status.HTTP_404_NOT_FOUND
            )
        
        # Get all logs related to table selection for this connection
        selection_logs = Log.objects.filter(
            connection_id=connection_id,
            message__icontains="Table selection updated"
        ).order_by('-time')
        
        history = []
        for log in selection_logs:
            # Get audit records for this specific log
            audit_records = TableSelectionAudit.objects.filter(
                log=log
            ).order_by('changed_at')
            
            # Format detailed changes
            changes = []
            for audit in audit_records:
                change_detail = {
                    'table': audit.table_name,
                    'action': audit.action_type,
                    'timestamp': audit.changed_at.isoformat(),
                    'changed_by': audit.changed_by.username if audit.changed_by else None
                }
                
                # Add sequence information based on action type
                if audit.action_type == 'ADD':
                    change_detail['sequence'] = audit.new_sequence
                elif audit.action_type == 'REMOVE':
                    change_detail['sequence'] = audit.old_sequence
                elif audit.action_type == 'REORDER':
                    change_detail['old_sequence'] = audit.old_sequence
                    change_detail['new_sequence'] = audit.new_sequence
                
                changes.append(change_detail)
            
            # Only include logs that have actual changes
            if changes:
                history.append({
                    'log_id': log.log_id,
                    'timestamp': log.time.isoformat(),
                    'message': log.message,
                    'user': log.user.username,
                    'changes': changes
                })
        
        return Response({
            'connection_id': connection_id,
            'history': history
        }, status=status.HTTP_200_OK)


class LogDetailAPIView(APIView):
    """
    Unified endpoint to get detailed information for any clickable log.
    Handles both migration session details and table selection audit details.
    
    GET /api/v1/connection/<connection_id>/log/<log_id>/
    """
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]
    
    def get(self, request, connection_id, log_id):
        from apps.elttool.models import TableSelectionAudit
        
        # Validate connection exists and user has access
        try:
            connection = Connection.objects.get(
                connection_id=connection_id,
                cmp=request.user.cmp
            )
        except Connection.DoesNotExist:
            return create_error_response(
                "Connection not found",
                status_code=status.HTTP_404_NOT_FOUND
            )
        
        # Get the specific log
        try:
            log = Log.objects.get(
                log_id=log_id,
                connection_id=connection_id
            )
        except Log.DoesNotExist:
            return create_error_response(
                "Log not found",
                status_code=status.HTTP_404_NOT_FOUND
            )
        
        # Determine log type and fetch appropriate details
        response_data = {
            'log_id': log.log_id,
            'message': log.message,
            'timestamp': log.time.isoformat(),
            'user': log.user.username if log.user else None,
            'type': 'unknown'
        }
        
        # Case 1: Table selection log
        if "table selection updated" in log.message.lower():
            response_data['type'] = 'table_selection'
            
            # Get audit records for this log
            audit_records = TableSelectionAudit.objects.filter(
                log=log
            ).order_by('changed_at')
            
            changes = []
            for audit in audit_records:
                change_detail = {
                    'table': audit.table_name,
                    'action': audit.get_action_type_display(),  # Get human-readable action
                    'timestamp': audit.changed_at.isoformat(),
                    'changed_by': audit.changed_by.first_name if audit.changed_by else None
                }
                
                # Add sequence information
                if audit.action_type == 'ADD':
                    change_detail['sequence'] = audit.new_sequence
                elif audit.action_type == 'REMOVE':
                    change_detail['sequence'] = audit.old_sequence
                elif audit.action_type == 'REORDER':
                    change_detail['old_sequence'] = audit.old_sequence
                    change_detail['new_sequence'] = audit.new_sequence
                elif audit.action_type == 'BULK_UPDATE':
                    change_detail['selected'] = audit.new_selected
                
                changes.append(change_detail)
            
            response_data['changes'] = changes
            response_data['summary'] = f"{len(changes)} table changes made"
        
        # Case 2: Migration log (has session_id)
        elif log.session and log.session > 1:
            response_data['type'] = 'migration'
            response_data['session_id'] = log.session
            
            # Get migration records for this session
            migration_records = MigrationRecord.objects.filter(
                connection=connection,
                migration_session_id=log.session
            ).prefetch_related('data_transfers').order_by('table_name')
            
            tables = []
            for record in migration_records:
                latest_transfer = record.data_transfers.order_by('-end_time').first()
                end_time = getattr(record, 'end_time', None) or (latest_transfer.end_time if latest_transfer else None)
                records_inserted = getattr(record, 'records_inserted', None)
                records_updated = getattr(record, 'records_updated', None)
                records_deleted = getattr(record, 'records_deleted', None)

                if records_inserted is None:
                    records_inserted = latest_transfer.new_rec if latest_transfer else 0
                if records_updated is None:
                    records_updated = latest_transfer.mod_rec if latest_transfer else 0
                if records_deleted is None:
                    records_deleted = latest_transfer.del_rec if latest_transfer else 0

                tables.append({
                    'table_name': record.table_name,
                    'status': record.status,
                    'start_time': record.start_time.isoformat() if record.start_time else None,
                    'end_time': end_time.isoformat() if end_time else None,
                    'records_inserted': records_inserted,
                    'records_updated': records_updated,
                    'records_deleted': records_deleted,
                    'staging_records_count': getattr(record, 'staging_records_count', 0),
                })
            
            response_data['tables'] = tables
            response_data['summary'] = f"{len(tables)} tables processed in session {log.session}"
        
        # Case 3: Other clickable logs (schema refresh, drop/reload, etc.)
        else:
            response_data['type'] = 'other'
            response_data['details'] = "Detailed information not available for this log type"
        
        return Response(response_data, status=status.HTTP_200_OK)


class RefreshSchemaAndMigrateAPIView(APIView):
    permission_classes = [IsAuthenticated]  # Removed CheckTrialPeriod

    def post(self, request, connection_id):
        # Optimize query with select_related to avoid N+1 queries
        connection = get_object_or_404(
            Connection.objects.select_related('src_config', 'src_config__src', 'dst_config', 'dst_config__dst'),
            pk=connection_id
        )
        
        # ✅ Check if connection is paused
        if connection.status != "A":
            log_function(
                request,
                "Attempted to refresh schema while connection paused",
                "E",
                connection_id
            )
            return Response(
                {"message": "Connection is paused. Activate it to refresh schema."},
                status=status.HTTP_400_BAD_REQUEST
            )
        
        time_frequency_once = "Once"
        session = request.session.get('session_number')
        
        # Handle reverse ETL vs regular ETL (using is_rtl flag).
        # Snowflake -> file-based reverse ETL uses SourceTableSelection
        # (files, not destination tables/mappings).
        dest_platform = getattr(getattr(connection.dst_config, "dst", None), "name", None)
        is_reverse_etl = bool(connection.src_config and connection.src_config.src and connection.src_config.src.is_rtl)
        if is_reverse_etl:
            existing_selected_tables = get_table_mappings_by_connection(connection_id)
            selected_json_path = {}
            # ✅ For Snowflake→GoogleDrive, fetch folder paths from DB
            if connection.dst_config.dst.name == "GoogleDrive":
                rtl_queryset = SourceTableSelection.objects.filter(
                    connection_id=connection_id, selected=True
                )
                selected_folder_path = _build_selected_table_folder_map(rtl_queryset, connection.dst_config.dst.name)
            else:
                selected_folder_path = {}
            last_checked_dates = {}

            # Fallback: if no mappings found, use SourceTableSelection (UI may have saved selections)
            if not existing_selected_tables:
                selected_tables_qs = SourceTableSelection.objects.filter(
                    connection_id=connection_id,
                    selected=True
                ).order_by('sequence')
                existing_selected_tables = list(selected_tables_qs.values_list('table', flat=True))
                selected_json_path = {tbl.table: tbl.json_path for tbl in selected_tables_qs}
                selected_folder_path = _build_selected_table_folder_map(selected_tables_qs, connection.dst_config.dst.name)
                last_checked_dates = {tbl.table: tbl.last_synced for tbl in selected_tables_qs}
        else:
            selected_tables_qs = SourceTableSelection.objects.filter(
                connection_id=connection_id, 
                selected=True
            ).order_by('sequence')
            existing_selected_tables = list(selected_tables_qs.values_list('table', flat=True))
            selected_json_path = {tbl.table: tbl.json_path for tbl in selected_tables_qs}
            selected_folder_path = _build_selected_table_folder_map(selected_tables_qs, connection.dst_config.dst.name)
            last_checked_dates = {tbl.table: tbl.last_synced for tbl in selected_tables_qs}
        
        if not existing_selected_tables:
            return create_error_response("No tables selected for migration.")
        
        # Ensure configs are dictionaries (handle bytes/strings from decryption)
        try:
            source_config = ensure_config_is_dict(connection.src_config.data, "source_config")
            destination_config = ensure_config_is_dict(connection.dst_config.data, "destination_config")
        except ValueError as e:
            return Response({
                "message": str(e)
            }, status=status.HTTP_500_INTERNAL_SERVER_ERROR)
        
        response = migration_function(
            request,
            source_config,
            destination_config,
            existing_selected_tables,
            selected_json_path,
            selected_folder_path,
            connection_id,
            time_frequency_once,
            session,
            _get_connection_source_platform(connection),
            connection.DELETED,
            connection.SYNCED,
            connection.safety_interval,
            last_checked_dates
        )
        
        status_code = response.pop("status_code", status.HTTP_200_OK)
        message = response.pop("message", "")
        
        # Update sequence for non-reverse ETL connections
        if status_code in {200, 206} and not (connection.src_config and connection.src_config.src and connection.src_config.src.is_rtl):
            tables = SourceTableSelection.objects.filter(connection_id=connection_id)
            selected_table_seq = {}
            seq = 1
            for table_name in existing_selected_tables:
                selected_table_seq[table_name] = seq
                seq += 1
            
            success_tables = response.get("success_tables", [])
            for table in tables:
                if table.table in success_tables:
                    table.selected = True
                    table.sequence = selected_table_seq.get(table.table, table.sequence)
            
            SourceTableSelection.objects.bulk_update(tables, ['selected', 'sequence'])
        
        return Response({
            "message": message,
            "status_code": status_code,
            "response": response
        }, status=status_code)


class UpdateConnectionSyncFrequencyAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAdministrator]  # ✅ Only Admins can update sync frequency

    def post(self, request, connection_id):
        print("=" * 80)
        print(f"🔧 [UpdateConnectionSyncFrequencyAPIView.post] Updating sync frequency")
        print(f"   Connection ID: {connection_id}")
        print(f"   Request data: {request.data}")
        print("=" * 80)
        
        new_frequency = request.data.get('new_sync_frequency')
        safety_interval = request.data.get('safety_interval')
        start_date = request.data.get('start_date')

        if not new_frequency:
            return create_error_response("new_sync_frequency required")

        # ✅ Handle start_date: if empty, "0", or not provided, use current UTC time
        # This endpoint doesn't use serializer, so we handle it here
        print(f"\n📅 [start_date Pre-Processing]")
        print(f"   Original value: {start_date}")
        print(f"   Type: {type(start_date)}")
        
        if not start_date or (isinstance(start_date, str) and start_date.strip() in ['', '0', 'None', 'null']):
            print(f"   ⚠️ start_date is empty/invalid ('{start_date}'), using current UTC time")
            start_date = datetime.now(pytz.utc)
            print(f"   ✅ Set to current UTC time: {start_date}")
        elif isinstance(start_date, str):
            # Parse ISO format from frontend (e.g., "2025-12-08T06:55:00Z")
            try:
                iso_string = start_date.replace('Z', '+00:00')
                start_date = datetime.fromisoformat(iso_string)
                if start_date.tzinfo is None:
                    start_date = pytz.utc.localize(start_date)
                print(f"   ✅ Parsed ISO format: {start_date}")
            except (ValueError, AttributeError) as e:
                print(f"   ⚠️ Could not parse start_date '{start_date}': {e}, using current UTC time")
                start_date = datetime.now(pytz.utc)
        else:
            print(f"   ✅ start_date has value: {start_date}")
        
        print("=" * 80)

        result = update_sync_frequency(request, connection_id, new_frequency, safety_interval, start_date)

        return Response({
            "message": "Sync frequency updated.",
            "result": str(result)
        }, status=status.HTTP_200_OK)


