class SelectedTablesListAPIView(APIView):
    permission_classes = [IsAuthenticated, IsAnalystOrAdmin]  # ? Admin and Analyst only  # Removed CheckTrialPeriod

    def _parse_timestamp(self, value):
        if not value:
            return None
        if hasattr(value, "tzinfo"):
            return value
        try:
            raw_value = str(value).strip()
            if raw_value.endswith("Z"):
                raw_value = raw_value[:-1] + "+00:00"
            raw_value = re.sub(
                r"(\d{2})\.(\d{2})\.(\d{2})(?=(?:[+\-]\d{2}:\d{2})?$)",
                r"\1:\2:\3",
                raw_value,
            )
            parsed = datetime.fromisoformat(raw_value)
        except Exception:
            return None
        if getattr(parsed, "tzinfo", None) is None:
            parsed = timezone.make_aware(parsed, timezone=pytz.UTC)
        return parsed.astimezone(pytz.UTC)

    def _format_timestamp(self, value):
        if not value:
            return None
        if getattr(value, "tzinfo", None) is None:
            value = timezone.make_aware(value, timezone=pytz.UTC)
        return value.astimezone(pytz.UTC).strftime("%Y-%m-%dT%H:%M:%SZ")

    def _parse_offset_duration(self, value):
        if value is None or value == "":
            return timedelta(0)

        if isinstance(value, (int, float)):
            return timedelta(hours=float(value))

        raw_value = str(value).strip()
        if not raw_value:
            return timedelta(0)

        if ":" in raw_value:
            parts = raw_value.split(":")
            if len(parts) != 3:
                raise ValueError("offset must be in HH:MM:SS format")
            hours, minutes, seconds = (int(part) for part in parts)
            return timedelta(hours=hours, minutes=minutes, seconds=seconds)

        return timedelta(hours=float(raw_value))

    def get(self, request, connection_id):
        """
        Return selected tables for a given connection_id.
        For reverse ETL (Salesforce), returns table mappings.
        For regular ETL, returns selected source tables.
        """
        # Optimize query with select_related to avoid N+1 queries
        connection = get_object_or_404(
            Connection.objects.select_related('src_config', 'src_config__src'),
            connection_id=connection_id
        )
        
        # Check if reverse ETL using is_rtl flag
        if connection.src_config and connection.src_config.src and connection.src_config.src.is_rtl:
            # Return table mappings for reverse ETL
            mappings = TableMapping.objects.filter(
                connection_id=connection_id
            ).select_related('source_table', 'destination_table').order_by('added_on')
            
            mapping_data = []
            for mapping in mappings:
                mapping_data.append({
                    "source_table": mapping.source_table.table,
                    "destination_table": mapping.destination_table.table,
                    "status": mapping.source_table.status,
                    "sequence": mapping.source_table.sequence,
                    "added_on": mapping.added_on.strftime("%Y-%m-%d %H:%M:%S") if mapping.added_on else None
                })
            
            return Response({
                "is_reverse_etl": True,
                "mappings": mapping_data
            }, status=status.HTTP_200_OK)
        else:
            # Regular ETL: Return selected source tables
            tables = SourceTableSelection.objects.filter(
                connection_id=connection_id,
                selected=True
            ).order_by('sequence')
            
            serializer = SelectedSourceTableSerializer(tables, many=True)
            return Response({
                "tables": serializer.data
            }, status=status.HTTP_200_OK)

    def post(self, request, connection_id):
        """
        Preview or confirm a sync-time shift for selected tables.
        The change is applied only when confirm=true.
        """
        connection = get_object_or_404(
            Connection.objects.select_related('src_config', 'src_config__src', 'cmp'),
            connection_id=connection_id
        )

        if connection.src_config and connection.src_config.src and connection.src_config.src.is_rtl:
            return Response(
                {"message": "Sync-time updates are not supported for reverse ETL connections."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        offset_value = request.data.get("offset_hours", 0)
        try:
            offset_delta = self._parse_offset_duration(offset_value)
        except (TypeError, ValueError):
            return Response({"message": "offset_hours must be a number or HH:MM:SS duration."}, status=status.HTTP_400_BAD_REQUEST)

        direction = str(request.data.get("direction", "subtract")).strip().lower()
        if direction not in ("subtract", "add"):
            return Response({"message": "direction must be 'subtract' or 'add'."}, status=status.HTTP_400_BAD_REQUEST)

        table_id = request.data.get("table_id")
        table_ids = request.data.get("table_ids", [])
        if isinstance(table_ids, str):
            table_ids = [item.strip() for item in table_ids.split(",") if item.strip()]

        target_table_ids = []
        if table_id not in (None, ""):
            try:
                target_table_ids = [int(table_id)]
            except (TypeError, ValueError):
                return Response({"message": "table_id must be an integer."}, status=status.HTTP_400_BAD_REQUEST)
        elif table_ids:
            try:
                target_table_ids = [int(item) for item in table_ids]
            except (TypeError, ValueError):
                return Response({"message": "table_ids must be a list of integers."}, status=status.HTTP_400_BAD_REQUEST)
        else:
            return Response(
                {"message": "table_id or table_ids is required.", "error_type": "table_ids_required"},
                status=status.HTTP_400_BAD_REQUEST,
            )

        selected_tables = list(
            SourceTableSelection.objects.filter(connection_id=connection_id, selected=True)
            .order_by("sequence", "tbl_id")
        )

        if not selected_tables:
            return Response(
                {
                    "message": "No selected tables found for this connection.",
                    "selected_tables": [],
                },
                status=status.HTTP_200_OK,
            )

        selected_table_map = {tbl.tbl_id: tbl for tbl in selected_tables}
        target_tables = [selected_table_map.get(tbl_id) for tbl_id in target_table_ids if tbl_id in selected_table_map]
        missing_ids = sorted(set(target_table_ids) - set(selected_table_map.keys()))
        if missing_ids:
            return Response(
                {
                    "message": "Selected table(s) not found for this connection.",
                    "error_type": "selected_table_not_found",
                    "missing_table_ids": missing_ids,
                },
                status=status.HTTP_404_NOT_FOUND,
            )

        confirm_raw = request.data.get("confirm", False)
        if isinstance(confirm_raw, str):
            confirm = confirm_raw.strip().lower() in ("1", "true", "yes", "y", "on")
        else:
            confirm = bool(confirm_raw)

        response_field_name = "last_synced" if confirm else "updated_sync_time"
        preview_rows = []
        for table_obj in target_tables:
            parsed_last_synced = self._parse_timestamp(table_obj.last_synced)
            if not parsed_last_synced:
                preview_rows.append(
                    {
                        "tbl_id": table_obj.tbl_id,
                        "table": table_obj.table,
                        response_field_name: table_obj.last_synced,
                    }
                )
                continue

            shifted_last_synced = (parsed_last_synced + offset_delta) if direction == "add" else (parsed_last_synced - offset_delta)
            preview_rows.append(
                {
                    "tbl_id": table_obj.tbl_id,
                    "table": table_obj.table,
                    response_field_name: self._format_timestamp(shifted_last_synced),
                }
            )

        if confirm:
            for table_obj in target_tables:
                parsed_last_synced = self._parse_timestamp(table_obj.last_synced)
                if not parsed_last_synced:
                    continue
                shifted_last_synced = (parsed_last_synced + offset_delta) if direction == "add" else (parsed_last_synced - offset_delta)
                table_obj.last_synced = self._format_timestamp(shifted_last_synced)
                table_obj.account_type = "user"
                table_obj.updated_by_id = getattr(request.user, "user_id", None)
                table_obj.save(update_fields=["last_synced", "account_type", "updated_by_id"])

        return Response(
            {
                "selected_tables": preview_rows,
                "selected_table_field": response_field_name,
                "offset_hours": offset_value,
                "direction": direction,
                "confirmed": confirm,
                "preview_only": not confirm,
            },
            status=status.HTTP_200_OK,
        )


