class UpdateTimestampFieldAPIView(APIView):
    """
    Update the delta timestamp field for a specific table in a connection.
    This field is used for delta/incremental sync to track which field contains
    the last modified timestamp.
    
    POST /api/v1/connection/update-timestamp/
    Body: {
        "connection_id": int,
        "table": str,
        "timestamp_field": str
    }
    
    Response: {
        "status": "success",
        "message": "Timestamp field updated successfully"
    }
    """
    permission_classes = [IsAuthenticated]
    
    def post(self, request):
        """Update delta timestamp field for a table"""
        print("=" * 80)
        print("⏰ UPDATE TIMESTAMP FIELD API CALLED")
        print("=" * 80)
        
        # Extract request data
        connection_id = request.data.get('connection_id')
        table_name = request.data.get('table')
        timestamp_field = request.data.get('timestamp_field')
        
        print(f"📋 Request parameters:")
        print(f"   - connection_id: {connection_id}")
        print(f"   - table: {table_name}")
        print(f"   - timestamp_field: {timestamp_field}")
        
        # Validate required fields
        if not connection_id or not table_name:
            print("❌ Missing required fields")
            return Response({
                'status': 'error',
                'message': 'connection_id and table are required'
            }, status=status.HTTP_400_BAD_REQUEST)
        
        # Find the table selection
        try:
            print(f"🔍 Looking for table selection: connection_id={connection_id}, table={table_name}")
            selection = SourceTableSelection.objects.get(
                connection_id=connection_id,
                table=table_name
            )
            print(f"✅ Found table selection: {selection.table}")
            print(f"   - Current timestamp field: {selection.delta_timestamp_field}")
            
        except SourceTableSelection.DoesNotExist:
            print(f"❌ Table selection not found")
            return Response({
                'status': 'error',
                'message': f'Table {table_name} not found for connection {connection_id}'
            }, status=status.HTTP_404_NOT_FOUND)
        
        # Update the timestamp field
        old_value = selection.delta_timestamp_field
        selection.delta_timestamp_field = timestamp_field
        selection.save()
        
        print(f"✅ Timestamp field updated:")
        print(f"   - Old value: {old_value}")
        print(f"   - New value: {timestamp_field}")
        print("=" * 80)
        
        return Response({
            'status': 'success',
            'message': 'Timestamp field updated successfully',
            'table': table_name,
            'old_timestamp_field': old_value,
            'new_timestamp_field': timestamp_field
        }, status=status.HTTP_200_OK)


class TestCeleryConnectionAPIView(APIView):
    """
    Test endpoint to verify Celery connectivity from Django to FastAPI container.
    
    GET /api/v1/test-celery-connection/
    GET /api/v1/test-celery-connection/?connection_name=MyConnection
    
    Response: {
        "worker_status": {...},
        "connection_test": {...},
        "timestamp": "...",
        "redis_host": "...",
        "celery_config": {...}
    }
    """
    permission_classes = [IsAuthenticated]
    
    def get(self, request):
        """Test Celery connectivity"""
        print("=" * 80)
        print("🧪 CELERY CONNECTION TEST STARTED")
        print("=" * 80)
        print(f"📡 Request parameters: {dict(request.GET)}")
        
        # Test worker connectivity
        print("🔧 Testing worker connectivity...")
        worker_status = get_celery_worker_status()
        print(f"📊 Worker status result: {worker_status.get('workers_available', 'unknown')}")
        
        # Test job inspection for a sample connection if provided
        connection_test = None
        connection_name = request.GET.get('connection_name')
        
        if connection_name:
            print(f"🔍 Testing connection: '{connection_name}'")
            
            # Test the direct utility function
            print("📋 Testing direct migration status check...")
            migration_status = check_connection_migration_status(connection_name)
            print(f"📊 Migration status result: can_start_migration = {migration_status.get('can_start_migration', 'unknown')}")
            
            # Also test the detailed Celery inspection
            print("🔄 Testing detailed Celery job inspection...")
            celery_detailed = is_connection_migration_active_celery(connection_name)
            
            # Also test the full migration check function (for existing connections in DB)
            print("🔄 Testing full migration check function...")
            migration_check = None
            try:
                connection = Connection.objects.filter(src_config__name=connection_name).first()
                if connection:
                    print("✅ Connection object found in database")
                    migration_check = is_migration_in_progress(connection)
                    print(f"📊 Full migration check result: is_active = {migration_check.get('is_active', 'unknown')}")
                else:
                    print(f"⚠️  Connection '{connection_name}' not found in database")
                    migration_check = {"error": "Connection not found in database"}
            except Exception as e:
                print(f"⚠️  Migration check failed: {str(e)}")
                migration_check = {"error": str(e)}
            
            # Combine all test results
            connection_test = {
                "connection_name": connection_name,
                "direct_status_check": migration_status,
                "detailed_celery_check": celery_detailed,
                "full_migration_check": migration_check
            }
        else:
            connection_test = {"message": "Provide ?connection_name=X to test specific connection"}
            print("ℹ️  No connection name provided for testing")
        
        print("🧪 CELERY CONNECTION TEST COMPLETED")
        print("=" * 80)
        
        return Response({
            "worker_status": worker_status,
            "connection_test": connection_test,
            "timestamp": timezone.now().isoformat(),
            "redis_host": "redis:6379/0",  # Same as FastAPI container
            "celery_config": {
                "broker_url": celery_app.conf.get('broker_url'),
                "result_backend": celery_app.conf.get('result_backend'),
                "task_default_queue": celery_app.conf.get('task_default_queue')
            }
        }, status=status.HTTP_200_OK)
class TableMappingSaveAPIView(APIView):
    """
    DRF API endpoint to save or update table mappings between source and destination.
    - Enforces Free plan limit (10 mappings max)
    - Deletes removed mappings
    - Updates timestamps for existing ones
    - Creates new mappings when needed
    - Runs atomically within a DB transaction
    """

    permission_classes = [IsAuthenticated]  # Removed CheckTrialPeriod

    def post(self, request):
        print("🔹 [TableMappingSaveAPIView] POST request received")

        try:
            # Step 1: Extract data from request
            data = request.data
            connection_id = data.get("connection_id")
            mappings = data.get("mappings", [])

            print(f"📥 Received data for connection_id={connection_id}")
            print(f"📋 Mappings received: {mappings}")

            # Step 2: Validate connection_id
            if not connection_id:
                print("❌ Missing connection_id in request body")
                return Response(
                    {"status": "error", "message": "Connection ID is missing."},
                    status=status.HTTP_400_BAD_REQUEST,
                )

            # Step 3: Retrieve connection
            try:
                connection = Connection.objects.get(connection_id=connection_id)
                print(f"✅ Connection found: {connection}")
            except ObjectDoesNotExist:
                print(f"❌ Connection not found for ID: {connection_id}")
                return Response(
                    {"status": "error", "message": "Connection not found."},
                    status=status.HTTP_404_NOT_FOUND,
                )

            # Step 4: Enforce Free Plan mapping limit (max 10)
            limited_by_plan = False
            if connection.cmp.plan == "Free" and len(mappings) > 10:
                mappings = mappings[:10]
                limited_by_plan = True
                print("⚠️ Free plan detected — limiting to first 10 mappings")

            # Step 5: Begin atomic transaction (ensures all-or-nothing save)
            with transaction.atomic():
                current_time = timezone.now()
                print("🕒 Transaction started at:", current_time)

                # --- Build new mapping pairs set ---
                new_mappings_set = set()
                for mapping in mappings:
                    source_name = re.sub(r"[^\w\s]+$", "", mapping.get("source", "").strip()).rstrip()
                    dest_name = re.sub(r"[^\w\s]+$", "", mapping.get("destination", "").strip()).rstrip()

                    # Validate table names
                    if not source_name or not dest_name:
                        print(f"❌ Invalid table names found in mapping: {mapping}")
                        return Response(
                            {"status": "error", "message": "Invalid table names in mapping."},
                            status=status.HTTP_400_BAD_REQUEST,
                        )

                    new_mappings_set.add((source_name, dest_name))

                print(f"✅ Cleaned and validated mapping pairs: {new_mappings_set}")

                # --- Fetch existing mappings for this connection ---
                existing_mappings = TableMapping.objects.filter(connection=connection)
                existing_pairs = set(
                    (m.source_table.table, m.destination_table.table) for m in existing_mappings
                )

                print(f"📂 Existing mappings in DB: {existing_pairs}")

                # --- Identify mappings to delete ---
                to_delete = existing_pairs - new_mappings_set
                if to_delete:
                    # Delete exact pairs only (avoid cross-product on __in filters).
                    for src_name, dst_name in to_delete:
                        TableMapping.objects.filter(
                            connection=connection,
                            source_table__table=src_name,
                            destination_table__table=dst_name,
                        ).delete()
                    print(f"🗑️ Deleted outdated mappings: {to_delete}")

                    # Unmapped sources should leave Unassigned — clear selected when
                    # the source has no remaining mapping for this connection.
                    deleted_sources = {src for src, _ in to_delete}
                    still_mapped_sources = {src for src, _ in new_mappings_set}
                    sources_to_unselect = deleted_sources - still_mapped_sources
                    if sources_to_unselect:
                        updated = SourceTableSelection.objects.filter(
                            connection=connection,
                            table__in=list(sources_to_unselect),
                            selected=True,
                        ).update(selected=False)
                        print(
                            f"🔓 Cleared selected on {updated} unmapped source table(s): "
                            f"{sources_to_unselect}"
                        )
                else:
                    print("✅ No mappings to delete.")

                # --- Create or update new mappings ---
                for src_table_name, dst_table_name in new_mappings_set:
                    print(f"🔁 Processing mapping: {src_table_name} → {dst_table_name}")

                    # Validate both tables exist
                    try:
                        source_table = SourceTableSelection.objects.get(
                            connection=connection, table__iexact=src_table_name
                        )
                        print(f"✅ Source table found: {src_table_name}")
                    except ObjectDoesNotExist:
                        print(f"❌ Source table '{src_table_name}' not found.")
                        return Response(
                            {"status": "error", "message": f"Source table '{src_table_name}' not found."},
                            status=status.HTTP_404_NOT_FOUND,
                        )

                    try:
                        dest_table = DestinationTableSelection.objects.get(
                            connection=connection, table__iexact=dst_table_name
                        )
                        print(f"✅ Destination table found: {dst_table_name}")
                    except ObjectDoesNotExist:
                        print(f"❌ Destination table '{dst_table_name}' not found.")
                        return Response(
                            {"status": "error", "message": f"Destination table '{dst_table_name}' not found."},
                            status=status.HTTP_404_NOT_FOUND,
                        )

                    # Check if mapping already exists
                    existing_mapping = TableMapping.objects.filter(
                        connection=connection,
                        source_table=source_table,
                        destination_table=dest_table,
                    ).first()

                    if existing_mapping:
                        # Update timestamp
                        existing_mapping.added_on = current_time
                        existing_mapping.save()
                        print(f"🕒 Updated existing mapping timestamp for {src_table_name} → {dst_table_name}")
                    else:
                        # Create a new mapping
                        TableMapping.objects.create(
                            connection=connection,
                            source_table=source_table,
                            destination_table=dest_table,
                            added_on=current_time,
                        )
                        source_table.selected = True
                        source_table.save()
                        print(f"✅ Created new mapping: {src_table_name} → {dst_table_name}")

            # Step 6: Return success response
            response_message = "Mappings saved successfully."
            if limited_by_plan:
                response_message += " Only first 10 mappings saved due to Free plan."

            print(f"🎉 {response_message}")
            return Response(
                {"status": "success", "message": response_message},
                status=status.HTTP_200_OK,
            )

        # --- Global Error Handling ---
        except Exception as e:
            logger.exception("❌ Exception occurred in TableMappingSaveAPIView: %s", str(e))
            print(f"❌ Unexpected error in TableMappingSaveAPIView: {str(e)}")
            return Response(
                {"status": "error", "message": str(e)},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )
class TableMappingListAPIView(APIView):
    """
    DRF API endpoint to list existing source→destination table mappings for a connection.
    - Returns all mappings with timestamps
    - Includes Free plan information
    - Used by React frontend to show current mappings
    """
    permission_classes = [IsAuthenticated]  # Removed CheckTrialPeriod

    def get(self, request, connection_id):
        print("🔹 [TableMappingListAPIView] GET request received")
        print(f"📡 Fetching mappings for connection_id={connection_id}")

        try:
            # Step 1: Validate and fetch the connection
            try:
                connection = Connection.objects.get(connection_id=connection_id)
                print(f"✅ Connection found: {connection}")
            except ObjectDoesNotExist:
                print(f"❌ Connection not found for ID: {connection_id}")
                return Response(
                    {"status": "error", "message": "Connection not found."},
                    status=status.HTTP_404_NOT_FOUND,
                )

            # Step 2: Retrieve all mappings for this connection
            mappings = TableMapping.objects.filter(connection=connection).select_related("source_table", "destination_table")

            if not mappings.exists():
                print("ℹ️ No mappings found for this connection.")
                return Response(
                    {"status": "success", "mappings": [], "message": "No mappings found."},
                    status=status.HTTP_200_OK,
                )

            print(f"📊 Found {mappings.count()} mappings. Preparing data...")

            # Step 3: Build structured response data
            mappings_data = []
            for mapping in mappings:
                mappings_data.append({
                    "source_table": mapping.source_table.table,
                    "destination_table": mapping.destination_table.table,
                    "status": mapping.source_table.status,
                    "added_on": mapping.added_on.strftime("%Y-%m-%d %H:%M:%S"),
                })

            print("✅ Mappings data prepared successfully.")

            # Step 4: Add plan info
            plan_type = connection.cmp.plan
            response_message = f"Retrieved {len(mappings_data)} mappings successfully."
            if plan_type == "Free" and len(mappings_data) >= 10:
                response_message += " ⚠️ Free plan: Maximum of 10 mappings allowed."

            # Step 5: Return success response
            print(f"🎉 {response_message}")
            return Response(
                {
                    "status": "success",
                    "connection_id": connection_id,
                    "plan_type": plan_type,
                    "total_mappings": len(mappings_data),
                    "mappings": mappings_data,
                    "message": response_message,
                },
                status=status.HTTP_200_OK,
            )

        except Exception as e:
            print(f"❌ Unexpected error in TableMappingListAPIView: {str(e)}")
            return Response(
                {"status": "error", "message": str(e)},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )
