    def get(self, request, connection_id):
        include_celery_status = (
            request.GET.get('include_celery_status', 'true').lower() == 'true'
        )

        from apps.elttool.services.update_schema_status_builder import (
            build_update_schema_status
        )

        data, error = build_update_schema_status(
            connection_id=connection_id,
            include_celery_status=include_celery_status,
            celery_app=celery_app,
        )

        if error:
            return Response(
                {'message': error['message']},
                status=status.HTTP_404_NOT_FOUND
            )

        return Response(data, status=status.HTTP_200_OK)


