from apps.elttool.services.migration_status_builder import build_migration_status


class MigrationStatusAPIView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, migration_session_id):
        logger.info(
            f"✅ MigrationStatusAPIView accessed | "
            f"migration_session_id='{migration_session_id}' | path='{request.path}'"
        )

        try:
            connection_id = request.query_params.get("connection_id")
            if connection_id is not None and str(connection_id).strip() != "":
                try:
                    connection_id = int(connection_id)
                except (TypeError, ValueError):
                    return Response(
                        {"error": "Invalid connection_id"},
                        status=status.HTTP_400_BAD_REQUEST,
                    )
            else:
                connection_id = None

            data, error, http_status = build_migration_status(
                migration_session_id,
                connection_id=connection_id,
            )

            if error:
                return Response(error, status=http_status)

            return Response(data, status=http_status)

        except Exception as e:
            logger.exception("MigrationStatusAPIView error")
            return Response(
                {'error': str(e)},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )

class InternalMigrationStatusPushAPIView(APIView):
    permission_classes = [IsInternalService]

    def post(self, request, migration_session_id):
        try:
            from apps.elttool.services.migration_status_builder import build_migration_status
            from apps.elttool.websocket.ws_utils import push_migration_status_update

            data, error, _ = build_migration_status(migration_session_id)
            if error:
                logger.warning(f"⚠️ Internal WS push failed: {error}")
                return Response(error, status=status.HTTP_404_NOT_FOUND)

            # ✅ ADD LOG HERE
            logger.info(
                f"🔔 WS push triggered | session={migration_session_id}"
            )

            push_migration_status_update(migration_session_id, data)

            return Response(
                {"message": "WebSocket update pushed successfully"},
                status=status.HTTP_200_OK
            )

        except Exception as e:
            logger.exception("InternalMigrationStatusPushAPIView error")
            return Response(
                {'error': str(e)},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )

class InternalConnectionActivityLogPushAPIView(APIView):
    """
    Internal API to trigger a WebSocket update for a connection's activity logs.
    Called when new logs are created to notify connected clients.
    """
    permission_classes = [IsInternalService]

    def post(self, request, connection_id):
        try:
            from apps.elttool.models import Connection, Log
            from django.utils import timezone
            from datetime import timedelta
            import orjson
            
            # Get connection object
            try:
                connection = Connection.objects.select_related('src_config', 'dst_config', 'cmp').get(pk=connection_id)
            except Connection.DoesNotExist:
                logger.warning(f"⚠️ Connection {connection_id} not found")
                return Response(
                    {"error": "Connection not found"}, 
                    status=status.HTTP_404_NOT_FOUND
                )
            
            # Get recent logs for the connection (last 1 hour by default)
            start_date = timezone.now() - timedelta(hours=1)
            
            all_logs = Log.objects.filter(
                connection_id=connection_id,
                time__gte=start_date,
                migration_record_id__isnull=True,
            ).select_related('user', 'migration_record').order_by('-time')
            
            logs_data = [
                serialize_connection_activity_log(log, timestamp_format="iso")
                for log in all_logs
            ]

            # Time frequencies for the connection
            time_frequencies = {
                'None': 'None',
                '1': '1 minute',
                '5': '5 minutes',
                '15': '15 minutes',
                '30': '30 minutes',
                '60': '1 hour',
                '120': '2 hours',
                '180': '3 hours',
                '360': '6 hours',
                '480': '8 hours',
                '720': '12 hours',
                '1440': '24 hours'
            }
            
            readable_time_frequency = time_frequencies.get(connection.time_frequency, 'Unknown')

            data = {
                'logs': logs_data,
                'connection': {
                    'connection_id': connection.connection_id,
                    'readable_time_frequency': readable_time_frequency,
                    'time_frequency': connection.time_frequency,
                    'status': connection.status
                },
                'cmp_id': request.user.cmp.cmp_id if hasattr(request.user, 'cmp') and request.user.cmp else None
            }
            
            from apps.elttool.websocket.ws_utils import push_connection_activity_log_update
            logger.info(f"🔔 Activity log WS push triggered | connection_id={connection_id}")
            push_connection_activity_log_update(connection_id, data)

            return Response(
                {"message": "Activity log WebSocket update pushed successfully"},
                status=status.HTTP_200_OK
            )

        except Exception as e:
            logger.exception("InternalConnectionActivityLogPushAPIView error")
            return Response(
                {'error': str(e)},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )

